--
-- Name: hr_employee_public; Type: VIEW; Schema: public; Owner: magpora_user
--

CREATE VIEW public.hr_employee_public AS
 SELECT emp.name,
    emp.active,
    emp.color,
    emp.department_id,
    emp.job_id,
    emp.job_title,
    emp.company_id,
    emp.address_id,
    emp.work_phone,
    emp.mobile_phone,
    emp.work_email,
    emp.work_contact_id,
    emp.work_location_id,
    emp.user_id,
    emp.resource_id,
    emp.resource_calendar_id,
    emp.parent_id,
    emp.coach_id,
    emp.employee_type,
    emp.create_date,
    emp.id,
    emp.create_uid,
    emp.write_uid,
    emp.write_date,
    emp.first_contract_date,
    emp.expense_manager_id
   FROM public.hr_employee emp;


ALTER TABLE public.hr_employee_public OWNER TO magpora_user;

