rap']" position="before">\n            <!--TODO DBE Fix me : If one day, there is a survey_livechat bridge module, put this in that module-->\n            <t t-set="no_livechat" t-value="True"/>\n        </xpath>\n        <xpath expr="//div[@id='wrapwrap']" position="attributes">\n            <attribute name="t-att-style" add="(('background-image: url(' + question.background_image_url + ');')                              if question and question.background_image_url                              else ('background-image: url(' + page.background_image_url + ');')                              if page and page.background_image_url                              else ('background-image: url(' + survey.background_image_url + ');')                              if survey and survey.background_image_url                              else '')"/>\n            <attribute name="t-attf-class" add="o_survey_background" separator=" "/>\n        </xpath>\n        <xpath expr="//head/t[@t-call-assets][last()]" position="after">\n            <t t-call-assets="survey.survey_assets" lazy_load="True"/>\n        </xpath>\n        <xpath expr="//header" position="before">\n            <t t-set="no_header" t-value="True"/>\n            <t t-set="no_footer" t-value="True"/>\n        </xpath>\n        <xpath expr="//header" position="after">\n            <div id="wrap" class="oe_structure oe_empty"/>\n        </xpath>\n        <xpath expr="//footer" position="after">\n            <div class="py-3 m-0 p-0 text-end">\n                <div class="o_survey_progress_wrapper d-inline-block pe-1 text-start">\n                    <t t-call="survey.survey_progression" t-if="survey and survey.questions_layout != 'one_page' and answer and answer.state == 'in_progress' and (not question or not question.is_page) and not survey_form_readonly">\n                        <t t-if="survey.questions_layout == 'page_per_section'">\n                            <t t-set="page_ids" t-value="survey.page_ids.ids"/>\n     