1000	16	\N	1	1	Question: simple choice	\N	survey.question_simple_choice	qweb	survey/views/survey_templates.xml	\N	primary	{"en_US": "<t name=\\"Question: simple choice\\" t-name=\\"survey.question_simple_choice\\">\\n        <t t-set=\\"answer_line\\" t-value=\\"answer_lines.filtered(lambda line: line.suggested_answer_id)\\"/>\\n        <t t-set=\\"comment_line\\" t-value=\\"answer_lines.filtered(lambda line: line.value_char_box)\\"/>\\n        <div class=\\"row o_survey_form_choice\\" t-att-data-name=\\"question.id\\" data-question-type=\\"simple_choice_radio\\">\\n            <t t-set=\\"item_idx\\" t-value=\\"0\\"/>\\n            <div t-attf-class=\\"col-lg-12 d-flex flex-wrap\\">\\n                <t t-set=\\"has_correct_answer\\" t-value=\\"scoring_display_correction and any(label.is_correct for label in question.suggested_answer_ids)\\"/>\\n                <t t-foreach=\\"question.suggested_answer_ids\\" t-as=\\"label\\">\\n                    <t t-set=\\"item_idx\\" t-value=\\"label_index\\"/>\\n                    <t t-set=\\"answer_selected\\" t-value=\\"answer_line and answer_line.suggested_answer_id.id == label.id\\"/>\\n                    <t t-set=\\"is_correct\\" t-value=\\"label.is_correct\\"/>\\n\\n                    <!--Used for print mode with corrections -->\\n                    <t t-set=\\"answer_class\\" t-if=\\"not has_correct_answer\\" t-value=\\"''\\"/>\\n                    <t t-set=\\"answer_class\\" t-elif=\\"is_correct\\" t-value=\\"'bg-success'\\"/>\\n                    <t t-set=\\"answer_class\\" t-elif=\\"not is_correct\\" t-value=\\"'bg-danger'\\"/>\\n\\n                    <label t-att-for=\\"str(question.id) + '_' + str(label.id)\\" t-att-class=\\"'o_survey_choice_btn me-2 mb-2 py-1 px-3 rounded %s %s' % (answer_class, 'o_survey_selected' if answer_selected else '')\\">\\n                        <t t-call=\\"survey.survey_selection_key\\">\\n                            <t t-set=\\"selection_key_class\\" t-value=\\"'position-relative o_survey_radio_btn float-start d-flex'\\"/>\\n                        </t>\\n                        <span class=\\"ms-2 text-break\\" t-field=\\"label.value\\"/>\\n                        <input t-att-id=\\"str(question.id) + '_' + str(label.id)\\" type=\\"radio\\" t-att-value=\\"label.id\\" t-attf-class=\\"o_survey_form_choice_item invisible position-absolute #{'o_survey_form_choice_item_selected' if answer_selected else ''}\\" t-att-name=\\"question.id\\" t-att-checked=\\"'checked' if answer_selected else None\\" t-att-data-selection-key=\\"letters[item_idx] if useKeySelection else ''\\"/>\\n                        <t t-if=\\"has_correct_answer and answer_selected\\">\\n                            <!-- While displaying results: change icons to have a check mark for a right answer and a cross for a wrong one -->\\n                            <i t-if=\\"is_correct\\" class=\\"float-end mt-1 position-relative d-inline fa fa-check-circle\\"/>\\n                            <i t-else=\\"\\" class=\\"float-end mt-1 position-relative d-inline fa fa-times-circle\\"/>\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            <i class=\\"fa fa-check-circle float-end mt-1 position-relative\\"/>\\n                            <i class=\\"fa fa-circle-thin float-end mt-1 position-relative\\"/>\\n                        </t>\\n                        <t t-call=\\"survey.question_suggested_value_image\\"/>\\n                    </label>\\n                </t>\\n            </div>\\n            <div t-if=\\"question.comments_allowed and question.comment_count_as_answer\\" class=\\"js_comments col-lg-12\\">\\n                <div class=\\"d-flex flex-wrap\\">\\n                    <label t-att-class=\\"'o_survey_choice_btn form-label me-2 py-1 px-3 rounded %s' % ('o_survey_selected' if comment_line else '')\\">\\n                        <t t-set=\\"item_idx\\" t-value=\\"item_idx + 1\\"/>\\n                        <t t-call=\\"survey.survey_selection_key\\">\\n                            <t t-set=\\"selection_key_class\\" t-value=\\"'position-relative o_survey_radio_btn float-start d-flex'\\"/>\\n                        </t>\\n                        <input type=\\"radio\\" class=\\"o_survey_form_choice_item o_survey_js_form_other_comment invisible position-absolute\\" value=\\"-1\\" t-att-name=\\"question.id\\" t-att-checked=\\"comment_line and 'checked' or None\\" t-att-data-selection-key=\\"letters[item_idx] if useKeySelection else ''\\"/>\\n                        <span class=\\"ms-2\\" t-out=\\"question.comments_message or default_comments_message\\"/>\\n                        <i class=\\"fa fa-check-circle float-end mt-1 position-relative\\"/>\\n                        <i class=\\"fa fa-circle-thin float-end mt-1 position-relative\\"/>\\n                    </label>\\n                </div>\\n                <div t-attf-class=\\"o_survey_comment_container mt-3 py-0 px-1  #{'d-none' if not comment_line else ''}\\">\\n                    <textarea type=\\"text\\" class=\\"form-control o_survey_question_text_box bg-transparent text-dark rounded-0 p-0\\" t-att-disabled=\\"None if comment_line else 'disabled'\\"><t t-esc=\\"comment_line.value_char_box if comment_line else ''\\"/></textarea>\\n                </div>\\n            </div>\\n            <div t-if=\\"question.comments_allowed and not question.comment_count_as_answer\\" class=\\"col-lg-12 o_survey_comment_container mx-1 mt-3 ps-3 pe-4\\">\\n                <textarea type=\\"text\\" class=\\"form-control o_survey_comment o_survey_question_text_box bg-transparent text-dark rounded-0 p-0\\" t-att-placeholder=\\"question.comments_message or default_comments_message if not survey_form_readonly else ''\\"><t t-esc=\\"comment_line.value_char_box if comment_line else ''\\"/></textarea>\\n            </div>\\n        </div>\\n    </t>"}	<t name="Question: simple choice" t-name="survey.question_simple_choice">\n        <t t-set="answer_line" t-value="answer_lines.filtered(lambda line: line.suggested_answer_id)"/>\n        <t t-set="comment_line" t-value="answer_lines.filtered(lambda line: line.value_char_box)"/>\n        <div class="row o_survey_form_choice" t-att-data-name="question.id" data-question-type="simple_choice_radio">\n            <t t-set="item_idx" t-value="0"/>\n            <div t-attf-class="col-lg-12 d-flex flex-wrap">\n                <t t-set="has_correct_answer" t-value="scoring_display_correction and any(label.is_correct for label in question.suggested_answer_ids)"/>\n                <t t-foreach="question.suggested_answer_ids" t-as="label">\n                    <t t-set="item_idx" t-value="label_index"/>\n                    <t t-set="answer_selected" t-value="answer_line and answer_line.suggested_answer_id.id == label.id"/>\n                    <t t-set="is_correct" t-value="label.is_correct"/>\n\n                    <!--Used for print mode with corrections -->\n                    <t t-set="answer_class" t-if="not has_correct_answer" t-value="''"/>\n                    <t t-set="answer_class" t-elif="is_correct" t-value="'bg-success'"/>\n                    <t t-set="answer_class" t-elif="not is_correct" t-value="'bg-danger'"/>\n\n                    <label t-att-for="str(question.id) + '_' + str(label.id)" t-att-class="'o_survey_choice_btn me-2 mb-2 py-1 px-3 rounded %s %s' % (answer_class, 'o_survey_selected' if answer_selected else '')">\n                        <t t-call="survey.survey_selection_key">\n                            <t t-set="selection_key_class" t-value="'position-relative o_survey_radio_btn float-start d-flex'"/>\n                        </t>\n                        <span class="ms-2 text-break" t-field="label.value"/>\n                        <input t-att-id="str(question.id) + '_' + str(label.id)" type="radio" t-att-value="label.id" t-attf-class="o_survey_form_choice_item invisible position-absolute #{'o_survey_form_choice_item_selected' if answer_selecte