557	16	\N	1	1	Payment Checkout	\N	payment.checkout	qweb	payment/views/payment_templates.xml	\N	primary	{"en_US": "<t name=\\"Payment Checkout\\" t-name=\\"payment.checkout\\">\\n        <!-- Variables description:\\n            - 'providers' - The payment providers compatible with the current transaction\\n            - 'tokens' - The payment tokens of the current partner and payment providers\\n            - 'default_token_id' - The id of the token that should be pre-selected. Optional\\n            - 'fees_by_provider' - The dict of transaction fees for each provider. Optional\\n            - 'show_tokenize_input' - Whether the option to save the payment method is shown\\n            - 'reference_prefix' - The custom prefix to compute the full transaction reference\\n            - 'amount' - The amount to pay. Optional (sale_subscription)\\n            - 'currency' - The currency of the transaction, as a `res.currency` record\\n            - 'partner_id' - The id of the partner on behalf of whom the payment should be made\\n            - 'access_token' - The access token used to authenticate the partner.\\n            - 'transaction_route' - The route used to create a transaction when the user clicks Pay\\n            - 'landing_route' - The route the user is redirected to after the transaction\\n            - 'footer_template_id' - The template id for the submit button. Optional\\n        -->\\n        <form name=\\"o_payment_checkout\\" class=\\"o_payment_form mt-3 clearfix\\" t-att-data-reference-prefix=\\"reference_prefix\\" t-att-data-amount=\\"amount\\" t-att-data-currency-id=\\"currency and currency.id\\" t-att-data-partner-id=\\"partner_id\\" t-att-data-access-token=\\"access_token\\" t-att-data-transaction-route=\\"transaction_route\\" t-att-data-landing-route=\\"landing_route\\" t-att-data-allow-token-selection=\\"True\\">\\n\\n            <t t-set=\\"provider_count\\" t-value=\\"len(providers) if providers else 0\\"/>\\n            <t t-set=\\"token_count\\" t-value=\\"len(tokens) if tokens else 0\\"/>\\n            <!-- Check the radio button of the default token, if set, or of the first provider if\\n                 it is the only payment option -->\\n            <t t-set=\\"default_payment_option_id\\" t-value=\\"default_token_id if default_token_id and token_count &gt; 0                         else providers[0].id if provider_count == 1 and token_count == 0                         else None\\"/>\\n            <t t-set=\\"fees_by_provider\\" t-value=\\"fees_by_provider or dict()\\"/>\\n            <t t-set=\\"footer_template_id\\" t-value=\\"footer_template_id or 'payment.footer'\\"/>\\n\\n            <div class=\\"card\\">\\n                <!-- === Providers === -->\\n                <t t-foreach=\\"providers\\" t-as=\\"provider\\">\\n                    <div name=\\"o_payment_option_card\\" class=\\"card-body o_payment_option_card\\">\\n                        <label>\\n                            <!-- === Radio button === -->\\n                            <!-- Only shown if linked to the only payment option -->\\n                            <input name=\\"o_payment_radio\\" type=\\"radio\\" t-att-checked=\\"provider.id == default_payment_option_id\\" t-att-class=\\"'' if provider_count + token_count &gt; 1 else 'd-none'\\" t-att-data-payment-option-id=\\"provider.id\\" t-att-data-provider=\\"provider.code\\" data-payment-option-type=\\"provider\\"/>\\n                            <!-- === Provider name === -->\\n                            <span class=\\"payment_option_name\\">\\n                                <b t-esc=\\"provider.display_as or provider.name\\"/>\\n                            </span>\\n                            <!-- === \\"Test Mode\\" badge === -->\\n                            <span t-if=\\"provider.state == 'test'\\" class=\\"badge rounded-pill text-bg-warning ms-1\\">\\n                                Test Mode\\n                            </span>\\n                            <!-- === \\"Unpublished\\" badge === -->\\n                            <span t-if=\\"not provider.is_published\\" class=\\"badge rounded-pill text-bg-danger ms-1\\">\\n                                Unpublished\\n                            </span>\\n                            <!-- === Extra fees badge === -->\\n                            <t t-if=\\"fees_by_provider.get(provider)\\">\\n                                <span class=\\"badge rounded-pill text-bg-secondary ms-1\\">\\n                                    + <t t-esc=\\"fees_by_provider.get(provider)\\" t-options=\\"{'widget': 'monetary', 'display_currency': currency}\\"/>\\n                                    Fees\\n                                </span>\\n                            </t>\\n                        </label>\\n                        <!-- === Payment icon list === -->\\n                        <t t-call=\\"payment.icon_list\\"/>\\n                        <!-- === Help message === -->\\n                        <div t-if=\\"not is_html_empty(provider.pre_msg)\\" t-out=\\"provider.pre_msg\\" class=\\"text-muted ms-3\\"/>\\n                    </div>\\n                    <!-- === Provider inline form === -->\\n                    <div t-attf-id=\\"o_payment_provider_inline_form_{{provider.id}}\\" name=\\"o_payment_inline_form\\" class=\\"card-footer px-3 d-none\\">\\n                        <t t-if=\\"provider.sudo()._should_build_inline_form(is_validation=False)\\">\\n                            <t t-set=\\"inline_form_xml_id\\" t-value=\\"provider.sudo().inline_form_view_id.xml_id\\"/>\\n                            <!-- === Inline form content (filled by provider) === -->\\n                            <div t-if=\\"inline_form_xml_id\\" class=\\"clearfix\\">\\n                                <t t-call=\\"{{inline_form_xml_id}}\\">\\n                                    <t t-set=\\"provider_id\\" t-value=\\"provider.id\\"/>\\n                                </t>\\n                            </div>\\n                        </t>\\n                        <!-- === \\"Save my payment details\\" checkbox === -->\\n                        <label t-if=\\"show_tokenize_input[provider.id]\\">\\n                            <input name=\\"o_payment_save_as_token\\" type=\\"checkbox\\"/>\\n                            Save my payment details\\n                        </label>\\n                    </div>\\n                </t>\\n                <!-- === Tokens === -->\\n                <t t-foreach=\\"tokens\\" t-as=\\"token\\">\\n                    <div name=\\"o_payment_option_card\\" class=\\"card-body o_payment_option_card\\">\\n                        <label>\\n                            <!-- === Radio button === -->\\n                            <input name=\\"o_payment_radio\\" type=\\"radio\\" t-att-checked=\\"token.id == default_payment_option_id\\" t-att-data-payment-option-id=\\"token.id\\" t-att-data-provider=\\"token.provider_code\\" data-payment-option-type=\\"token\\"/>\\n                            <!-- === Token name === -->\\n                            <span class=\\"payment_option_name\\" t-esc=\\"token.display_name\\"/>\\n                            <!-- === \\"V\\" check mark === -->\\n                            <t t-call=\\"payment.verified_token_checkmark\\"/>\\n                            <!-- === \\"Fees\\" badge === -->\\n                            <span t-if=\\"fees_by_provider.get(token.provider_id)\\" class=\\"badge rounded-pill text-bg-secondary ms-1\\">\\n                                    + <t t-esc=\\"fees_by_provider.get(token.provider_id)\\" t-options=\\"{'widget': 'monetary', 'display_currency': currency}\\"/>\\n                                    Fees\\n                            </span>\\n                            <!-- === \\"Unpublished\\" badge === -->\\n                            <span t-if=\\"not token.provider_id.is_published\\" class=\\"badge rounded-pill text-bg-danger ms-1\\">\\n                                Unpublished\\n                            </span>\\n                        </label>\\n                    </div>\\n                    <!-- === Token inline form === -->\\n                    <div t-attf-id=\\"o_payment_token_inline_form_{{token.id}}\\" name=\\"o_payment_inline_form\\" class=\\"card-footer d-none\\">\\n                        <t t-set=\\"token_inline_form_xml_id\\" t-value=\\"token.sudo().provider_id.token_inline_form_view_id.xml_id\\"/>\\n                        <!-- === Inline form content (filled by provider) === -->\\n                        <div t-if=\\"token_inline_form_xml_id\\" class=\\"clearfix\\">\\n                            <t t-call=\\"{{token_inline_form_xml_id}}\\">\\n                                <t t-set=\\"token\\" t-value=\\"token\\"/>\\n                            </t>\\n                        </div>\\n                    </div>\\n                </t>\\n            </div>\\n            <!-- === \\"Pay\\" button === -->\\n            <t t-call=\\"{{footer_template_id}}\\">\\n                <t t-set=\\"label\\">Pay</t>\\n                <t t-set=\\"icon_class\\" t-value=\\"'fa-lock'\\"/>\\n            </t>\\n        </form>\\n    </t>"}	<t name="Payment Checkout" t-name="payment.checkout">\n        <!-- Variables description:\n            - 'providers' - The payment providers compatible with the current transaction\n            - 'tokens' - The payment tokens of the current partner and payment providers\n            - 'default_token_id' - The id of the token that should be pre-selected. Optional\n            - 'fees_by_provider' - The dict of transaction fees for each provider. Optional\n            - 'show_tokenize_input' - Whether the option to save the payment method is shown\n            - 'reference_prefix' - The custom prefix to compute the full transaction reference\n            - 'amount' - The amount to pay. Optional (sale_subscription)\n            - 'currency' - The currency of the transaction, as a `res.currency` record\n            - 'partner_id' - The id of the partner on behalf of whom the payment should be made\n            - 'access_token' - The access token used to authenticate the partner.\n            - 'transaction_route' - The route used to create a transaction when the user clicks Pay\n            - 'landing_route' - The route the user is redirected to after the transaction\n            - 'footer_template_id' - The template id for the submit button. Optional\n        -->\n        <form name="o_payment_checkout" class="o_payment_form mt-3 clearfix" t-att-data-reference-prefix="reference_prefix" t-att-data-amount="amount" t-att-data-currency-id="currency and currency.id" t-att-data-partner-id="partner_id" t-att-data-access-token="access_token" t-att-data-transaction-route="transaction_route" t-att-data-landing-route="landing_route" t-att-data-allow-token-selection="True">\n\n            <t t-set="provider_count" t-value="len(providers) if providers else 0"/>\n            <t t-set="token_count" t-value="len(tokens) if tokens else 0"/>\n            <!-- Check the radio button of the default token, if set, or of the first provider if\n                 it is the only payment option -->\n            <t t-set="default_payment_option_id" t-value="default_token_id if default_token_id and token_count &gt; 0                         else providers[0].id if provider_count == 1 and token_count == 0                         else None"/>\n            <t t-set="fees_by_provider" t-value="fees_by_provider or dict()"/>\n            <t t-set="footer_template_id" t-value="footer_template_id or 'payment.footer'"/>\n\n            <div class="card">\n                <!-- === Providers === -->\n                <t t-foreach="providers" t-as="provider">\n                    <div name="o_payment_option_card" class="card-body o_payment_option_card">\n                        <label>\n                            <!-- === Radio button === -->\n                            <!-- Only shown if linked to the only payment option -->\n                            <input name="o_payment_radio" type="radio" t-att-checked="provider.id == default_payment_option_id" t-att-class="'' if provider_count + token_count &gt; 1 else 'd-none'" t-att-data-payment-option-id="provider.id" t-att-data-provider="provider.code" data-payment-option-type="provider"/>\n                            <!-- === Provider name === -->\n                            <span class="payment_option_name">\n                                <b t-esc="provider.display_as or provider.name"/>\n                            </span>\n                            <!-- === "Test Mode" badge === -->\n                            <span t-if="provider.state == 'test'" class="badge rounded-pill text-bg-warning ms-1">\n                                Test Mode\n                            </span>\n                            <!-- === "Unpublished" badge === -->\n                            <span t-if="not provider.is_published" class="badge rounded-pill text-bg-danger ms-1">\n                                Unpublished\n                            </span>\n                            <!-- === Extra fees badge === -->\n                            <t t-if="fees_by_provider.get(provider)">\n                                <span class="badge rounded-pill text-bg-secondary ms-1">\n                                    + <t t-esc="fees_by_provider.get(provider)" t-options="{'widget': 'monetary', 'display_currency': currency}"/>\n                                    Fees\n                                </span>\n                            </t>\n                        </label>\n                        <!-- === Payment icon list === -->\n                        <t t-call="payment.icon_list"/>\n                        <!-- === Help message === -->\n                        <div t-if="not is_html_empty(provider.pre_msg)" t-out="provider.pre_msg" class="text-muted ms-3"/>\n                    </div>\n                    <!-- === Provider inline form === -->\n                    <div t-attf-id="o_payment_provider_inline_form_{{provider.id}}" name="o_payment_inline_form" class="card-footer px-3 d-none">\n                        <t t-if="provider.sudo()._should_build_inline_form(is_validation=False)">\n                            <t t-set="inline_form_xml_id" t-value="provider.sudo().inline_form_view_id.xml_id"/>\n                            <!-- === Inline form content (filled by provider) === -->\n                            <div t-if="inline_form_xml_id" class="clearfix">\n                                <t t-call="{{inline_form_xml_id}}">\n                                    <t t-set="provider_id" t-value="provider.id"/>\n                                </t>\n                            </div>\n                        </t>\n                        <!-- === "Save my payment details" checkbox === -->\n                        <label t-if="show_tokenize_input[provider.id]">\n                            <input name="o_payment_save_as_token" type="checkbox"/>\n                            Save my payment details\n                        </label>\n                    </div>\n                </t>\n                <!-- === Tokens === -->\n                <t t-foreach="tokens" t-as="token">\n                    <div name="o_payment_option_card" class="card-body o_payment_option_card">\n                        <label>\n                            <!-- === Radio button === -->\n                            <input name="o_payment_radio" type="radio" t-att-checked="token.id == default_payment_option_id" t-att-data-payment-option-id="token.id" t-att-data-provider="token.provider_code" data-payment-option-type="token"/>\n                            <!-- === Token name === -->\n                            <span class="payment_option_name" t-esc="token.display_name"/>\n                            <!-- === "V" check mark === -->\n                            <t t-call="payment.verified_token_checkmark"/>\n                            <!-- === "Fees" badge === -->\n                            <span t-if="fees_by_provider.get(token.provider_id)" class="badge rounded-pill text-bg-secondary ms-1">\n                                    + <t t-esc="fees_by_provider.get(token.provider_id)" t-options="{'widget': 'monetary', 'display_currency': currency}"/>\n                                    Fees\n                            </span>\n                            <!-- === "Unpublished" badge === -->\n                            <span t-if="not token.provider_id.is_published" class="badge rounded-pill text-bg-danger ms-1">\n                                Unpublished\n                            </span>\n                        </label>\n                    </div>\n                    <!-- === Token inline form === -->\n                    <div t-attf-id="o_payment_token_inline_form_{{token.id}}" name="o_payment_inline_form" class="card-footer d-none">\n                        <t t-set="token_inline_form_xml_id" t-value="token.sudo().provider_id.token_inline_form_view_id.xml_id"/>\n                        <!-- === Inline form content (filled by provider) === -->\n                        <div t-if="token_inline_form_xml_id" class="clearfix">\n                            <t t-call="{{token_inline_form_xml_id}}">\n                                <t t-set="token" t-value="token"/>\n                            </t>\n                        </div>\n                    </div>\n                </t>\n            </div>\n            <!-- === "Pay" button === -->\n            <t t-call="{{footer_template_id}}">\n                <t t-set="label">Pay</t>\n                <t t-set="icon_class" t-value="'fa-lock'"/>\n            </t>\n        </form>\n    </t>	f	t	2023-11-01 09:26:08.032685	2024-05-06 12:22:54.188784	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
