>\n                <t t-foreach="vals.get('payment_means_vals_list', [])" t-as="foreach_vals">\n                    <cac:PaymentMeans>\n                        <t t-call="{{PaymentMeansType_template}}">\n                            <t t-set="vals" t-value="foreach_vals"/>\n                        </t>\n                    </cac:PaymentMeans>\n                </t>\n            </t>\n            <t t-foreach="vals.get('payment_terms_vals', [])" t-as="foreach_vals">\n                <cac:PaymentTerms>\n                    <t t-foreach="foreach_vals.get('note_vals', [])" t-as="note">\n                        <cbc:Note t-out="note"/>\n                    </t>\n                </cac:PaymentTerms>\n            </t>\n            <t t-foreach="vals.get('allowance_charge_vals', [])" t-as="foreach_vals">\n                <cac:AllowanceCharge>\n                    <t t-call="{{AllowanceChargeType_template}}">\n                        <t t-set="vals" t-value="foreach_vals"/>\n                    </t>\n                </cac:AllowanceCharge>\n            </t>\n            <t t-foreach="vals.get('tax_total_vals', [])" t-as="foreach_vals">\n                <cac:TaxTotal>\n                    <t t-call="{{TaxTotalType_template}}">\n                        <t t-set="vals" t-value="foreach_vals"/>\n                    </t>\n                </cac:TaxTotal>\n            </t>\n            <cac:LegalMonetaryTotal>\n                <t t-set="monetary_tot_vals" t-value="vals.get('legal_monetary_total_vals', {})"/>\n                <cbc:LineExtensionAmount t-att-currencyID="monetary_tot_vals['currency'].name" t-out="format_float(monetary_tot_vals.get('line_extension_amount'), monetary_tot_vals.get('currency_dp'))"/>\n                <cbc:TaxExclusiveAmount t-att-currencyID="monetary_tot_vals['currency'].name" t-out="format_float(monetary_tot_vals.get('tax_exclusive_amount'), monetary_tot_vals.get('currency_dp'))"/>\n                <cbc:TaxInclusiveAmount t-att-currencyID="monetary_tot_vals['