ment_state in ('paid', 'in_payment') or last_tx.state == 'done'\\">\\n                        <span class=\\"badge rounded-pill text-bg-success\\"><i class=\\"fa fa-fw fa-check\\"/><span class=\\"d-none d-md-inline\\"> Paid</span></span>\\n                    </t>\\n                    <t t-if=\\"invoice.state == 'posted' and invoice.payment_state == 'reversed'\\">\\n                        <span class=\\"badge rounded-pill text-bg-success\\"><i class=\\"fa fa-fw fa-check\\"/><span class=\\"d-none d-md-inline\\"> Reversed</span></span>\\n                    </t>\\n                    <t t-if=\\"invoice.state == 'cancel'\\">\\n                        <span class=\\"badge rounded-pill text-bg-danger\\"><i class=\\"fa fa-fw fa-remove\\"/><span class=\\"d-none d-md-inline\\"> Cancelled</span></span>\\n                    </t>\\n                </t>\\n                <t t-else=\\"\\">\\n                    <!-- c/p of account -->\\n                    <t t-if=\\"invoice.state == 'posted' and invoice.payment_state not in ('in_payment', 'paid', 'reversed')\\">\\n                        <span class=\\"badge rounded-pill text-bg-info\\"><i class=\\"fa fa-fw fa-clock-o\\" aria-label=\\"Opened\\" title=\\"Opened\\" role=\\"img\\"/><span class=\\"d-none d-md-inline\\"> Waiting for Payment</span></span>\\n                    </t>\\n                    <t t-if=\\"invoice.state == 'posted' and invoice.payment_state in ('paid', 'in_payment')\\">\\n                        <span class=\\"badge rounded-pill text-bg-success\\"><i class=\\"fa fa-fw fa-check\\" aria-label=\\"Paid\\" title=\\"Paid\\" role=\\"img\\"/><span class=\\"d-none d-md-inline\\"> Paid</span></span>\\n                    </t>\\n                    <t t-if=\\"invoice.state == 'posted' and invoice.payment_state == 'reversed'\\">\\n                        <span class=\\"badge rounded-pill text-bg-success\\"><i class=\\"fa fa-fw fa-check\\" aria-label=\\"Reversed\\" title=\\"Reversed\\" role=\\"img\\"/><span class=\\"d-none d-md-inline\\"> Reversed</span></span>\\n                    </t>\\n                    <t t-if=\\"invoice.state == 'cancel'\\">\\n                        <span class=\\"badge rounded-pill text-bg-warning\\"><i class=\\"fa fa-fw fa-remove\\" aria-label=\\"Cancelled\\" title=\\"Cancelled\\" role=\\"img\\"/><span class=\\"d-none d-md-inline\\"> Cancelled</span></span>\\n                    </t>\\n                </t>\\n            </td>\\n        </xpath>\\n    </data>"}	<?xml version="1.0"?>\n<data inherit_id="account_payment.portal_my_invoices_payment">\n        <xpath expr="//t[@t-foreach='invoices']/tr/td[count(t)=2]/t[@t-set='pending_manual_txs']/following-sibling::a[i]" position="attributes">\n            <attribute name="t-if">\n                invoice._has_to_be_paid()\n            </attribute>\n        </xpath>\n        <xpath expr="//t[@t-foreach='invoices']/tr/td[hasclass('tx_status')]" position="replace">\n            <td class="tx_status text-center">\n                <t t-if="last_tx">\n                    <!-- c/p of account_payment -->\n                    <t t-if="invoice.state == 'posted' and invoice.payment_state in ('not_paid', 'partial') and (last_tx.state not in ['pending', 'authorized', 'done', 'cancel'] or (last_tx.state == 'pending' and last_tx.provider_code in ('none', 'custom')))">\n                        <span class="badge rounded-pill text-bg-info"><i class="fa fa-fw fa-clock-o"/><span class="d-none d-md-inline"> Waiting for Payment</span></span>\n                    </t>\n                    <t t-if="invoice.state == 'posted' and last_tx.state == 'authorized'">\n                        <span class="badge rounded-pill text-bg-primary"><i class="fa fa-fw fa-check"/><span class="d-none d-md-inline"> Authorized</span></span>\n                    </t>\n                    <t t-if="invoice.state == 'posted' and last_tx.state == 'pending' and last_tx.provider_code not in ('none', 'custom')">\n                        <span class="badge roun