ion()"/>\n            <t t-set="combination_info" t-value="product._get_combination_info(combination, add_qty=add_qty or 1, pricelist=pricelist)"/>\n            <t t-set="product_variant" t-value="product.env['product.product'].browse(combination_info['product_id'])"/>\n\n            <input type="hidden" class="product_template_id" t-att-value="product.id"/>\n            <input type="hidden" class="product_id" t-attf-name="product_id" t-att-value="product_variant.id"/>\n            <input type="hidden" class="has_optional_products" t-attf-name="has_optional_products" t-att-value="product_variant.optional_product_ids.filtered(lambda p: p._is_add_to_cart_possible(combination))"/>\n            <div class="col-lg-12 text-center mt-5">\n                <t t-if="product._is_add_to_cart_possible()">\n                    <div class="col-lg-5 d-inline-block text-start">\n                        <t t-if="combination" t-call="sale.variants">\n                            <t t-set="parent_combination" t-value="None"/>\n                        </t>\n                        <h2>\n                            <span t-attf-class="text-danger oe_default_price oe_striked_price {{'' if combination_info['has_discounted_price'] else 'd-none'}}" t-out="combination_info['list_price']" t-options="{                                     &quot;widget&quot;: &quot;monetary&quot;,                                     &quot;display_currency&quot;: (pricelist or product).currency_id                                 }"/>\n                            <span class="oe_price product_id mt-3" style="white-space: nowrap;" t-att-data-product-id="product.id" t-out="combination_info['price']" t-options="{                                     &quot;widget&quot;: &quot;monetary&quot;,                                     &quot;display_currency&quot;: (pricelist or product).currency_id                                 }"/>\n                        </h2>\n                        <t t-if="product.visible_qty_configurat