ces td {\\n                    text-align: center !important;\\n                }\\n            }\\n            @media screen and (max-width: 1135px) {\\n                .o_stacking_wrapper {\\n                    width: 100% !important;\\n                    height: unset !important;\\n                }\\n                td {\\n                    max-width: inherit !important;\\n                }\\n                img:only-child:not(.img-fluid) {\\n                    object-fit: cover;\\n                    min-width: 100% !important;\\n                }\\n                .o_desktop_h100 {\\n                    height: unset !important;\\n                }\\n            }\\n        </style>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="mass_mailing.mass_mailing_mail_style">\n        <style>\n            .o_layout * {\n                box-sizing: border-box !important;\n            }\n            .o_layout :not(.fa) {\n                font-family: Arial,Helvetica Neue,Helvetica,sans-serif;\n            }\n            /* Remove space around the email design. */\n                html,\n                body {\n                    margin: 0 auto !important;\n                    padding: 0 !important;\n                    height: 100% !important;\n                    width: 100% !important;\n                }\n\n                /* Stop Outlook resizing small text. */\n                * {\n                    -ms-text-size-adjust: 100%;\n                }\n\n                /* Stop Outlook from adding extra spacing to tables. */\n                table,\n                td {\n                    mso-table-lspace: 0pt !important;\n                    mso-table-rspace: 0pt !important;\n                }\n\n                /* Use a better rendering method when resizing images in Outlook IE. */\n                img {\n                    -ms-interpolation-mode:bicubic;\n                }\n\n                /* Prevent Windows 10 Mail from underlining links. Styles for underl