            <div class=\\"col-6\\">\\n                                        <span><field name=\\"amount_total\\" widget=\\"monetary\\"/></span>\\n                                        <span><field name=\\"currency_id\\" invisible=\\"1\\"/></span>\\n                                    </div>\\n                                    <div class=\\"col-6\\">\\n                                        <span class=\\"float-end\\">\\n                                            <field name=\\"state\\" widget=\\"label_selection\\" options=\\"{'classes': {'draft': 'default', 'posted': 'success'}}\\"/>\\n                                        </span>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </t>\\n                    </templates>\\n                </kanban>"}	<kanban class="o_kanban_mobile" sample="1" js_class="account_documents_kanban">\n                    <field name="journal_id"/>\n                    <field name="partner_id"/>\n                    <field name="ref"/>\n                    <field name="date"/>\n                    <field name="state"/>\n                    <templates>\n                        <t t-name="kanban-box">\n                            <div t-attf-class="oe_kanban_global_click">\n                                <div class="row mb4">\n                                    <div class="col-6 o_kanban_record_headings">\n                                        <strong>\n                                            <span>\n                                                <field name="partner_id" attrs="{'invisible': [('partner_id', '=', False)]}"/>\n                                                <field name="journal_id" attrs="{'invisible': [('partner_id', '!=', False)]}"/>\n                                            </span>\n                                        </strong>\n                                    </div>\n                              