1042	16	\N	1	1	Mass Mailing: A/B Test Description	\N	mass_mailing.ab_testing_description	qweb	mass_mailing/data/mailing_data_templates.xml	\N	primary	{"en_US": "<t name=\\"Mass Mailing: A/B Test Description\\" t-name=\\"mass_mailing.ab_testing_description\\">\\n        <div name=\\"ab_testing_description\\" class=\\"mb-2\\">\\n            <t t-if=\\"mailing.ab_testing_completed\\">\\n                <p t-if=\\"mailing.ab_testing_pc == 100\\">\\n                    This <t t-out=\\"mailing.mailing_type_description\\"/> is the winner of the A/B testing campaign and has been sent to all remaining recipients.\\n                </p>\\n                <p t-else=\\"\\">The winner has already been sent. Use <b>Compare Version</b> to get an overview of this A/B testing campaign.</p>\\n            </t>\\n            <t t-elif=\\"mailing.ab_testing_mailings_count &gt;= 2\\">\\n                <p>\\n                    A sample of <b><t t-out=\\"mailing.ab_testing_pc\\"/>% of recipients</b> will receive this <b><t t-out=\\"mailing.mailing_type_description\\"/></b>, and <t t-out=\\"other_ab_testing_pc\\"/>% receive one of the\\n                    <b><t t-out=\\"mailing.ab_testing_mailings_count - 1\\"/> other versions</b> from the same campaign.\\n                </p>\\n                <p>\\n\\t\\t    <t t-if=\\"mailing.ab_testing_winner_selection == 'manual'\\">Don't forget to send your preferred version</t>\\n\\t\\t    <t t-elif=\\"not mailing.ab_testing_schedule_datetime\\">Since the date and time for this test has not been scheduled, don't forget to manually send your preferred version.</t>\\n                    <t t-else=\\"\\">\\n                        Then on <b><t t-out=\\"mailing.ab_testing_schedule_datetime.strftime('%b %d, %Y')\\"/></b> the <t t-out=\\"mailing.mailing_type_description\\"/> having the <b><t t-out=\\"ab_testing_winner_selection_description\\"/></b> will be sent\\n                    </t> to the remaining <t t-out=\\"remaining_ab_testing_pc\\"/>% of recipients.\\n                </p>\\n            </t>\\n            <t t-else=\\"\\">\\n                <p>\\n                    A sample of <b><t t-out=\\"mailing.ab_testing_pc\\"/>% of recipients</b> will receive this <b><t t-out=\\"mailing.mailing_type_description\\"/></b>.\\n                </p>\\n                <p>Try different variations in the campaign to compare their <t t-out=\\"ab_testing_winner_selection_description\\"/>.</p>\\n                <p>\\n                    <t t-if=\\"mailing.ab_testing_winner_selection != 'manual'\\">Once the best version is identified, we will send the best one to the remaining recipients.</t>\\n                    <t t-else=\\"\\">\\n                        The actual <t t-out=\\"mailing.mailing_type_description\\"/> will be sent to the remaining recipients.\\n                    </t>\\n                </p>\\n            </t>\\n        </div>\\n    </t>"}	<t name="Mass Mailing: A/B Test Description" t-name="mass_mailing.ab_testing_description">\n        <div name="ab_testing_description" class="mb-2">\n            <t t-if="mailing.ab_testing_completed">\n                <p t-if="mailing.ab_testing_pc == 100">\n                    This <t t-out="mailing.mailing_type_description"/> is the winner of the A/B testing campaign and has been sent to all remaining recipients.\n                </p>\n                <p t-else="">The winner has already been sent. Use <b>Compare Version</b> to get an overview of this A/B testing campaign.</p>\n            </t>\n            <t t-elif="mailing.ab_testing_mailings_count &gt;= 2">\n                <p>\n                    A sample of <b><t t-out="mailing.ab_testing_pc"/>% of recipients</b> will receive this <b><t t-out="mailing.mailing_type_description"/></b>, and <t t-out="other_ab_testing_pc"/>% receive one of the\n                    <b><t t-out="mailing.ab_testing_mailings_count - 1"/> other versions</b> from the same campaign.\n                </p>\n                <p>\n\t\t    <t t-if="mailing.ab_testing_winner_selection == 'manual'">Don't forget to send your preferred version</t>\n\t\t    <t t-elif="not mailing.ab_testing_schedule_datetime">Since the date and time for this test has not been scheduled, don't forget to manually send your preferred version.</t>\n                    <t t-else="">\n                        Then on <b><t t-out="mailing.ab_testing_schedule_datetime.strftime('%b %d, %Y')"/></b> the <t t-out="mailing.mailing_type_description"/> having the <b><t t-out="ab_testing_winner_selection_description"/></b> will be sent\n                    </t> to the remaining <t t-out="remaining_ab_testing_pc"/>% of recipients.\n                </p>\n            </t>\n            <t t-else="">\n                <p>\n                    A sample of <b><t t-out="mailing.ab_testing_pc"/>% of recipients</b> will receive this <b><t t-out="mailing.mailing_type_description"/></b>.\n                </p>\n                <p>Try different variations in the campaign to compare their <t t-out="ab_testing_winner_selection_description"/>.</p>\n                <p>\n                    <t t-if="mailing.ab_testing_winner_selection != 'manual'">Once the best version is identified, we will send the best one to the remaining recipients.</t>\n                    <t t-else="">\n                        The actual <t t-out="mailing.mailing_type_description"/> will be sent to the remaining recipients.\n                    </t>\n                </p>\n            </t>\n        </div>\n    </t>	f	t	2023-11-01 09:26:25.579935	2024-05-06 12:22:58.574848	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
