-muted\\" t-field=\\"picking.scheduled_date\\" t-options=\\"{'date_only': True}\\"/>\\n                                </div>\\n                            </div>\\n                            <span t-if=\\"picking.state == 'done'\\" class=\\"small badge text-bg-success orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-truck\\"/> <b>Shipped</b>\\n                            </span>\\n                            <span t-elif=\\"picking.state == 'cancel'\\" class=\\"small badge text-bg-danger orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-times\\"/> <b>Cancelled</b>\\n                            </span>\\n                            <span t-elif=\\"picking.state in ['draft', 'waiting', 'confirmed', 'assigned']\\" class=\\"small badge text-bg-info orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-clock-o\\"/> <b>Preparation</b>\\n                            </span>\\n                        </div>\\n                    </t>\\n                </div>\\n            </t>\\n        </xpath>\\n    </data>"}	<?xml version="1.0"?>\n<data name="Orders Shipping Followup" inherit_id="sale.sale_order_portal_content">\n        <xpath expr="//div[@id='so_date']" position="after">\n            <div t-if="sale_order.incoterm" class="row">\n                <div class="mb-3 col-6 ms-auto">\n                    <strong>Incoterm: </strong> <span t-field="sale_order.incoterm"/>\n                </div>\n            </div>\n        </xpath>\n        <xpath expr="//div[@id='informations']" position="inside">\n            <t t-set="delivery_orders" t-value="sale_order.picking_ids.filtered(lambda picking: picking.picking_type_id.code == 'outgoing')"/>\n            <t t-if="delivery_orders">\n                <div>\n                    <strong>Delivery Orders</strong>\n                </div>\n                <div>\n                    <t t-foreach="delivery_orders" t-as="picking">\n     