                if(footer){\\n                            var companyFooter = footer.children[index];\\n                            footer.textContent = '';\\n                            footer.appendChild(companyFooter);\\n                        }\\n                    }\\n                </script>\\n            </head>\\n            <body class=\\"container\\" t-att-data-report-id=\\"report_xml_id\\" t-att-onload=\\"subst and 'subst()'\\" style=\\"overflow:hidden\\">\\n                <t t-out=\\"body\\"/>\\n            </body>\\n        </html>\\n    </t>"}	<t t-name="web.minimal_layout">\n        &lt;!DOCTYPE html&gt;\n        <html style="height: 0;">\n            <head>\n                <base t-att-href="base_url"/>\n                <t t-call-assets="web.report_assets_pdf" t-js="false"/>\n                <t t-call-assets="web.report_assets_common" t-js="false"/>\n                <t t-call-assets="web.report_assets_pdf" t-css="false"/>\n                <meta charset="utf-8"/>\n                <script t-if="subst">\n                    function subst() {\n                        var vars = {};\n                        var x = document.location.search.substring(1).split('&amp;');\n                        for (var i in x) {\n                            var z = x[i].split('=', 2);\n                            vars[z[0]] = unescape(z[1]);\n                        }\n                        var x = ['sitepage', 'sitepages', 'section', 'subsection', 'subsubsection'];\n                        var z = {'sitepage': 'page', 'sitepages': 'topage'};\n                        for (var i in x) {\n                            var y = document.getElementsByClassName(z[x[i]] || x[i])\n                            for (var j=0; j&lt;y.length; ++j)\n                                y[j].textContent = vars[x[i]];\n                        }\n\n                        var index = vars['webpage'].split('.', 4)[3];\n                        var header = document.getElementById('minimal_lay