er data-customize-css-property=\\"\\" data-css-property=\\"color\\" data-selector-text=\\"h3\\" data-no-transparency=\\"true\\" data-color-prefix=\\"text-\\"/>\\n        </we-row>\\n        <we-row string=\\"\\" class=\\"o_we_sublevel_1 o_short_title\\">\\n            <we-fontfamilypicker data-selector-text=\\"h3\\"/>\\n            <span>​</span> <!-- Separate the select from the buttons (styling) -->\\n            <we-button title=\\"Bold\\" class=\\"fa fa-fw fa-bold\\" data-no-preview=\\"true\\" data-toggle=\\"true\\" data-customize-css-property=\\"bolder\\" data-selector-text=\\"h3\\" data-css-property=\\"font-weight\\"/>\\n            <we-button title=\\"Italic\\" class=\\"fa fa-fw fa-italic\\" data-no-preview=\\"true\\" data-toggle=\\"true\\" data-customize-css-property=\\"italic\\" data-selector-text=\\"h3\\" data-css-property=\\"font-style\\"/>\\n            <we-button title=\\"Underline\\" class=\\"fa fa-fw fa-underline\\" data-no-preview=\\"true\\" data-toggle=\\"true\\" data-customize-css-property=\\"underline\\" data-selector-text=\\"h3\\" data-css-property=\\"text-decoration-line\\"/>\\n        </we-row>\\n        <!-- TEXT -->\\n        <we-row string=\\"Text\\" class=\\"o_design_tab_title\\">\\n            <we-input data-customize-css-property=\\"\\" data-css-property=\\"font-size\\" data-selector-text=\\"p, p &gt; *, li, li &gt; *\\" data-unit=\\"px\\"/>\\n            <we-colorpicker data-customize-css-property=\\"\\" data-css-property=\\"color\\" data-selector-text=\\"p, p &gt; *, li, li &gt; *\\" data-no-transparency=\\"true\\" data-color-prefix=\\"text-\\"/>\\n        </we-row>\\n        <we-row string=\\"\\" class=\\"o_we_sublevel_1 o_short_title\\">\\n            <we-fontfamilypicker data-selector-text=\\"p, p &gt; *, li, li &gt; *\\"/>\\n            <span>​</span> <!-- Separate the select from the buttons (styling) -->\\n            <we-button title=\\"Bold\\" class=\\"fa fa-fw fa-bold\\" data-no-preview=\\"true\\" data-toggle=\\"true\\" data-customize-css-property=\\"bolder\\" data-selector-text=\\"p, p &gt; *, li, li &gt; *\\" data-css-property=\\"font-weight\\"/>\\n            <we-button title=\\"Italic\\" class=\\"fa fa-fw fa-italic\\" data-no-preview=\\"true\\" data-toggle=\\"true\\" data-customize-css-property=\\"italic\\" data-selector-text=\\"p, p &gt; *, li, li &gt; *\\" data-css-property=\\"font-style\\"/>\\n            <we-button title=\\"Underline\\" class=\\"fa fa-fw fa-underline\\" data-no-preview=\\"true\\" data-toggle=\\"true\\" data-customize-css-property=\\"underline\\" data-selector-text=\\"p, p &gt; *, li, li &gt; *\\" data-css-property=\\"text-decoration-line\\"/>\\n        </we-row>\\n        <!-- LINKS -->\\n        <we-row string=\\"Links\\" class=\\"o_design_tab_title\\">\\n            <we-colorpicker data-customize-css-property=\\"\\" data-css-property=\\"color\\" data-selector-text=\\"a:not(.btn), a.btn.btn-link\\" data-no-transparency=\\"true\\" data-color-prefix=\\"text-\\"/>\\n            <we-button title=\\"Underline\\" class=\\"fa fa-fw fa-underline\\" data-no-preview=\\"true\\" data-toggle=\\"true\\" data-customize-css-property=\\"underline\\" data-selector-text=\\"a:not(.btn), a.btn.btn-link\\" data-css-property=\\"text-decoration-line\\"/>\\n        </we-row>\\n        <!-- PRIMARY BUTTONS -->\\n        <we-row string=\\"Primary Buttons\\" class=\\"o_design_tab_title\\">\\n            <we-input data-customize-css-property=\\"\\" data-css-property=\\"font-size\\" data-selector-text=\\"a.btn.btn-primary, a.btn.btn-outline-primary, a.btn.btn-fill-primary\\" data-unit=\\"px\\"/>\\n            <we-colorpicker data-customize-css-property=\\"\\" data-css-property=\\"color\\" data-selector-text=\\"a.btn.btn-primary, a.btn.btn-outline-primary, a.btn.btn-fill-primary\\" data-no-transparency=\\"true\\" data-color-prefix=\\"text-\\"/>\\n            <we-colorpicker data-customize-css-property=\\"\\" data-css-property=\\"background-color\\" data-selector-text=\\"a.btn.btn-primary, a.btn.btn-outline-primary, a.btn.btn-fill-primary\\" data-no-transparency=\\"true\\" data-color-prefix=\\"bg-\\"/>\\n        </we-row>\\n        <we-select string=\\"Size\\" class=\\"o_we_sublevel_1\\" data-selector-text=\\"a.btn.btn-primary, a.btn.btn-outline-primary, a.btn.btn-fill-primary\\">\\n            <we-button data-apply-button-size=\\"btn-sm\\">Small</we-button>\\n            <we-button data-apply-button-size=\\"btn-md\\">Medium</we-button>\\n            <we-button data-apply-button-size=\\"btn-lg\\">Large</we-button>\\n        </we-select>\\n        <we-row string=\\"Border\\" class=\\"o_we_sublevel_1\\">\\n            <we-input data-customize-css-property=\\"\\" data-css-property=\\"border-width\\" data-selector-text=\\"a.btn.btn-primary, a.btn.btn-outline-primary, a.btn.btn-fill-primary\\" data-unit=\\"px\\"/>\\n            <we-select data-selector-text=\\"a.btn.btn-primary, a.btn.btn-outline-primary, a.btn.btn-fill-primary\\" data-css-property=\\"border-style\\">\\n                <we-button title=\\"Solid\\" data-customize-css-property=\\"solid\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: solid;\\"/>\\n                </we-button>\\n                <we-button title=\\"Dashed\\" data-customize-css-property=\\"dashed\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: dashed;\\"/>\\n                </we-button>\\n                <we-button title=\\"Dotted\\" data-customize-css-property=\\"dotted\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: dotted;\\"/>\\n                </we-button>\\n                <we-button title=\\"Double\\" data-customize-css-property=\\"double\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: double; border-left: none; border-right: none;\\"/>\\n                </we-button>\\n            </we-select>\\n            <we-colorpicker data-customize-css-property=\\"\\" data-css-property=\\"border-color\\" data-selector-text=\\"a.btn.btn-primary, a.btn.btn-outline-primary, a.btn.btn-fill-primary\\" data-no-transparency=\\"true\\" data-color-prefix=\\"border-\\"/>\\n        </we-row>\\n        <!-- SECONDARY BUTTONS -->\\n        <we-row string=\\"Secondary Buttons\\" class=\\"o_design_tab_title\\">\\n            <we-input data-customize-css-property=\\"\\" data-css-property=\\"font-size\\" data-selector-text=\\"a.btn.btn-secondary, a.btn.btn-outline-secondary, a.btn.btn-fill-secondary\\" data-unit=\\"px\\"/>\\n            <we-colorpicker data-customize-css-property=\\"\\" data-css-property=\\"color\\" data-selector-text=\\"a.btn.btn-secondary, a.btn.btn-outline-secondary, a.btn.btn-fill-secondary\\" data-no-transparency=\\"true\\" data-color-prefix=\\"text-\\"/>\\n            <we-colorpicker data-customize-css-property=\\"\\" data-css-property=\\"background-color\\" data-selector-text=\\"a.btn.btn-secondary, a.btn.btn-outline-secondary, a.btn.btn-fill-secondary\\" data-no-transparency=\\"true\\" data-color-prefix=\\"bg-\\"/>\\n        </we-row>\\n        <we-select string=\\"Size\\" class=\\"o_we_sublevel_1\\" data-selector-text=\\"a.btn.btn-secondary, a.btn.btn-outline-secondary, a.btn.btn-fill-secondary\\">\\n            <we-button data-apply-button-size=\\"btn-sm\\">Small</we-button>\\n            <we-button data-apply-button-size=\\"btn-md\\">Medium</we-button>\\n            <we-button data-apply-button-size=\\"btn-lg\\">Large</we-button>\\n        </we-select>\\n        <we-row string=\\"Border\\" class=\\"o_we_sublevel_1\\">\\n            <we-input data-customize-css-property=\\"\\" data-css-property=\\"border-width\\" data-selector-text=\\"a.btn.btn-secondary, a.btn.btn-outline-secondary, a.btn.btn-fill-secondary\\" data-unit=\\"px\\"/>\\n            <we-select data-selector-text=\\"a.btn.btn-secondary, a.btn.btn-outline-secondary, a.btn.btn-fill-secondary\\" data-css-property=\\"border-style\\">\\n                <we-button title=\\"Solid\\" data-customize-css-property=\\"solid\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: solid;\\"/>\\n                </we-button>\\n                <we-button title=\\"Dashed\\" data-customize-css-property=\\"dashed\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: dashed;\\"/>\\n                </we-button>\\n                <we-button title=\\"Dotted\\" data-customize-css-property=\\"dotted\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: dotted;\\"/>\\n                </we-button>\\n                <we-button title=\\"Double\\" data-customize-css-property=\\"double\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: double; border-left: none; border-right: none;\\"/>\\n                </we-button>\\n            </we-select>\\n            <we-colorpicker data-customize-css-property=\\"\\" data-css-property=\\"border-color\\" data-selector-text=\\"a.btn.btn-secondary, a.btn.btn-outline-secondary, a.btn.btn-fill-secondary\\" data-no-transparency=\\"true\\" data-color-prefix=\\"border-\\"/>\\n        </we-row>\\n        <!-- SEPARATORS -->\\n        <we-row string=\\"Separators\\" class=\\"o_design_tab_title\\">\\n            <we-input data-customize-css-property=\\"\\" data-css-property=\\"border-top-width\\" data-selector-text=\\"hr\\" data-unit=\\"px\\"/>\\n            <we-select data-selector-text=\\"hr\\" data-css-property=\\"border-top-style\\">\\n                <we-button title=\\"Solid\\" data-customize-css-property=\\"solid\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: solid;\\"/>\\n                </we-button>\\n                <we-button title=\\"Dashed\\" data-customize-css-property=\\"dashed\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: dashed;\\"/>\\n                </we-button>\\n                <we-button title=\\"Dotted\\" data-customize-css-property=\\"dotted\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: dotted;\\"/>\\n                </we-button>\\n                <we-button title=\\"Double\\" data-customize-css-property=\\"double\\">\\n                    <div class=\\"o_we_fake_img_item o_we_border_preview\\" style=\\"border-style: double; border-left: none; border-right: none;\\"/>\\n                </we-button>\\n            </we-select>\\n            <we-colorpicker data-customize-css-property=\\"\\" data-css-property=\\"border-top-color\\" data-selector-text=\\"hr\\" data-no-transparency=\\"true\\" data-color-prefix=\\"border-\\"/>\\n        </we-row>\\n        <we-select string=\\"Width\\" class=\\"o_we_sublevel_1\\" data-selector-text=\\"hr\\" data-css-property=\\"width\\">\\n            <we-button data-customize-css-property=\\"25%\\">25%</we-button>\\n            <we-button data-customize-css-property=\\"50%\\">50%</we-button>\\n            <we-button data-customize-css-property=\\"75%\\">75%</we-button>\\n            <we-button data-customize-css-property=\\"100%\\">100%</we-button>\\n        </we-select>\\n    </div>\\n\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">mass_mailing.snippet_options</attribute></xpath></data>"}	<data inherit_id="web_editor.snippet_options" primary="True">\n    <!-- =================================================================== -->\n    <!-- Modify generic snippet options                                      -->\n    <!-- =================================================================== -->\n\n    <xpath expr="//t[@t-set='no_animations']" position="attributes">\n        <attribute name="t-value">True</attribute>\n    </xpath>\n\n    <!-- Extra shapes -->\n    <xpath expr="//div[hasclass('o_we_image_shape')]//we-select-page[hasclass('o_we_basic_shapes')]" position="inside">\n        <we-button data-set-img-shape="mass_mailing/basic/circle" data-select-label="Circle"/>\n        <we-button data-set-img-shape="mass_mailing/basic/triangle" data-select-label="Triangle"/>\n        <we-button data-set-img-shape="mass_mailing/basic/slanted" data-select-label="Slanted"/>\n    </xpath>\n    <xpath expr="//div[hasclass('o_we_image_shape')]//we-select-page[hasclass('o_we_basic_shapes')]" position="attributes">\n        <attribute name="t-if">True</attribute>\n    </xpath>\n\n    <!-- Image styles -->\n    <!-- TODO review to only modify what's really necessary and potentially -->\n    <!-- make the changes in web_editor directly so that website can benefit -->\n    <!-- from it. -->\n    <xpath expr="//div[hasclass('o_we_image_options')]" position="replace">\n        <div data-selector="span.fa, i.fa, img">\n            <we-select string="Alignment" data-state-to-first-class="true">\n                <we-button data-select-class="float-start" title="Align Left">Left</we-button>\n                <we-button data-select-class="" title="Align Center">Center</we-button>\n                <we-button data-select-class="float-end" title="Align Right">Right</we-button>\n            </we-select>\n\n            <t t-call="mass_mailing.snippet_options_border_line_widgets">\n                <t t-set="label">Border</t>\n                <t t-set="with_bs_class" t-value="True"/>\n            </t>\n\n            <we-input string="Round Corners" data-select-style="0" data-css-property="border-radius" data-unit="px" data-extra-class="rounded" t-att-data-variable="radius_variable"/>\n\n            <we-row string="Padding ⭤">\n                <we-input data-select-style="" data-unit="px" data-css-property="padding-left"/>\n                <we-input data-select-style="" data-unit="px" data-css-property="padding-right"/>\n            </we-row>\n            <we-row string="Padding ↕">\n                <we-input data-select-style="" data-unit="px" data-css-property="padding-top"/>\n                <we-input data-select-style="" data-unit="px" data-css-property="padding-bottom"/>\n            </we-row>\n        </div>\n    </xpath>\n\n    <!-- Transform is _very_ badly supported in mail clients -->\n    <xpath expr="//we-button[@data-name='image_transform_opt']" position="replace"/>\n\n    <xpath expr="//div[@data-js='ImageTools']" position="attributes">\n        <attribute name="data-js">MassMailingImageTools</attribute>\n    </xpath>\n\n    <!-- =================================================================== -->\n    <!-- Adding mass_mailing specific snippet options                        -->\n    <!-- =================================================================== -->\n\n    <xpath expr="." position="inside">\n\n    <!-- Border | Columns -->\n    <div data-js="Box" data-selector=".row &gt; div" data-exclude=".o_mail_wrapper_td, .s_col_no_bgcolor, .s_col_no_bgcolor.row &gt; div, .s_image_gallery .row &gt; div">\n        <t t-call="mass_mailing.snippet_options_border_widgets"/>\n    </div>\n    <div data-js="layout_column" data-selector=".o_mail_snippet_general" data-target="&gt; *:has(&gt; .row:not(.s_nb_column_fixed)), &gt; .s_allow_columns">\n        <we-select string="Columns" data-no-preview="true">\n            <we-button data-select-count="0" data-name="zero_cols_opt">None</we-button>\n            <we-button data-select-count="1">1</we-button>\n            <we-button data-select-count="2">2</we-button>\n            <we-button data-select-count="3">3</we-button>\n            <we-button data-select-count="4">4</we-button>\n            <we-button data-select-count="5">5</we-button>\n            <we-button data-select-count="6">6</we-button>\n        </we-select>\n    </div>\n\n    <!-- Move snippets around -->\n    <div data-js="SnippetMove" data-selector=".o_mail_snippet_general">\n        <we-button class="fa fa-fw fa-angle-up" data-move-snippet="prev" data-no-preview="true" data-name="move_up_opt"/>\n        <we-button class="fa fa-fw fa-angle-down" data-move-snippet="next" data-no-preview="true" data-name="move_down_opt"/>\n    </div>\n    <div data-js="SnippetMove" data-selector=".row:not(.s_col_no_resize) &gt; div" data-exclude=".s_showcase .row &gt; div" data-name="move_horizontally_opt">\n        <we-button class="fa fa-fw fa-angle-left" data-move-snippet="prev" data-no-preview="true" data-name="move_left_opt"/>\n        <we-button class="fa fa-fw fa-angle-right" data-move-snippet="next" data-no-preview="true" data-name="move_right_opt"/>\n    </div>\n\n    <div id="so_width" data-selector=".s_mail_alert .s_alert, .s_mail_blockquote, .s_mail_text_highlight">\n        <we-select string="Width">\n            <we-button data-select-class="w-25">25%</we-button>\n            <we-button data-select-class="w-50">50%</we-button>\n            <we-button data-select-class="w-75">75%</we-button>\n            <we-button data-select-class="w-100" data-name="so_width_100">100%</we-button>\n        </we-select>\n    </div>\n\n    <div id="so_block_align" data-selector=".s_mail_alert .s_alert, .s_mail_blockquote, .s_mail_text_highlight">\n        <we-button-group string="Alignment" data-dependencies="!so_width_100">\n            <we-button class="fa fa-fw fa-align-left" title="Left" data-select-class="me-auto"/>\n            <we-button class="fa fa-fw fa-align-center" title="Center" data-select-class="mx-auto"/>\n            <we-button class="fa fa-fw fa-align-right" title="Right" data-select-class="ms-auto"/>\n        </we-button-group>\n    </div>\n    <!-- TODO there is no data-js associated to this but a data-option-name, -->\n    <!-- somehow it acts as data-js... it will be reviewed in master. -->\n    <div data-option-name="minHeight" data-selector=".o_mail_snippet_general" data-exclude=".o_mail_snippet_general .row &gt; div *">\n        <we-button-group string="Height">\n            <we-button data-name="minheight_auto_opt" data-select-class="" title="Fit content">Auto</we-button>\n            <we-button data-select-class="o_height_400" title="400px">50%</we-button>\n            <we-button data-select-class="o_height_800" title="800px">100%</we-button>\n        </we-button-group>\n    </div>\n    <div data-js="mass_mailing_sizing_x" data-selector="img, .mv, .col_mv, td, th" data-exclude=".o_mail_no_resize, .o_mail_no_options"/>\n\n    <div data-js="table_row" data-selector="tr:has(&gt; .row), tr:has(&gt; .col_mv)" data-exclude=".o_mail_no_options" data-drop-near="tr:has(&gt; .row), tr:has(&gt; .col_mv)"/>\n\n    <div data-js="table_column" data-selector=".col&gt;td, .col&gt;th" data-exclude=".o_mail_no_options" data-drop-near=".col&gt;td, .col&gt;th"/>\n\n    <div data-js="table_column_mv" data-selector=".col_mv, td, th" data-exclude=".o_mail_no_options" data-drop-near=".col_mv, td, th"/>\n\n    <t t-set="mailing_content_selector" t-translation="off">.note-editable &gt; div:not(.o_layout), .note-editable .oe_structure &gt; div, .oe_snippet_body</t>\n    <div data-js="content" t-att-data-selector="mailing_content_selector" data-exclude=".o_mail_no_options" data-drop-near="[data-oe-field='body_html']:not(:has(.o_layout)) &gt; *, .oe_structure &gt; *" data-drop-in="[data-oe-field='body_html']:not(:has(.o_layout)), .oe_structure"/>\n\n    <t t-set="so_snippet_addition_selector" t-translation="off">.o_mail_snippet_general</t>\n    <div id="so_snippet_addition" t-att-data-selector="so_snippet_addition_selector" data-drop-in=":not(p).oe_structure:not(.oe_structure_solo), :not(.o_mega_menu):not(p)[data-oe-type=html], :not(p).oe_structure.oe_structure_solo:not(:has(&gt; section, &gt; div))"/>\n\n    <t t-set="so_content_addition_selector" t-translation="off">.s_mail_blockquote, .s_mail_alert, .s_rating, .s_hr, .s_mail_text_highlight</t>\n    <div id="so_content_addition" t-att-data-selector="so_content_addition_selector" t-attf-data-drop-near="p, h1, h2, h3, ul, ol, .row &gt; div &gt; img, #{so_content_addition_selector}" data-drop-in=".content, nav"/>\n\n    <div data-js="sizing_y" data-selector=".o_mail_snippet_general, .o_mail_snippet_general .row &gt; div" data-exclude=".o_mail_no_resize, .o_mail_no_options"/>\n\n    <div data-js="sizing_x" data-selector=".row &gt; div" data-drop-near=".row:not(.s_col_no_resize) &gt; div" data-exclude=".o_mail_no_resize, .o_mail_no_options"/>\n\n    <div data-selector=".note-editable .oe_structure &gt; div:not(:has(&gt; .o_mail_snippet_general)),         .note-editable .oe_structure &gt; div.o_mail_snippet_general,         .note-editable .oe_structure &gt; div.o_mail_snippet_general .o_cc,         .note-editable .oe_structure &gt; div.o_mail_snippet_general .btn:not(.btn-link)" data-exclude=".o_mail_no_colorpicker, .o_mail_no_options, .s_mail_color_blocks_2, .s_mail_color_blocks_2 .row &gt; div">\n        <we-colorpicker string="Background Color" data-select-style="true" data-no-transparency="true" data-css-property="background-color" data-color-prefix="bg-"/>\n    </div>\n\n    <div data-selector=".s_mail_color_blocks_2 .row &gt; div">\n        <we-colorpicker string="Background Color" data-select-style="true" data-no-transparency="true" data-css-property="background-color" data-color-prefix="bg-"/>\n    </div>\n    <!-- Allow customised padding-x on snippets -->\n    <div data-selector="[class*='col-lg-'], .s_discount2, .s_text_block, .s_media_list, .s_picture, .s_rating">\n        <we-row string="Padding ⭤">\n            <we-input data-select-style="" data-unit="px" data-css-property="padding-left"/>\n            <we-input data-select-style="" data-unit="px" data-css-property="padding-right"/>\n        </we-row>\n    </div>\n\n    <!-- Allow changing background images in Masonry and Cover -->\n    <t t-call="mass_mailing.snippet_options_background_options">\n        <t t-set="selector" t-value="'.s_masonry_block .row &gt; div, .s_cover .oe_img_bg'"/>\n   