                   <t t-else=\\"\\">Tax ID</t>: <span t-field=\\"o.partner_id.vat\\"/>\\n                                </div>\\n                            </t>\\n                        </div>\\n                    </t>\\n                    <t t-elif=\\"o.partner_shipping_id and (o.partner_shipping_id == o.partner_id)\\">\\n                        <div class=\\"offset-col-6 col-6\\" name=\\"address_same_as_shipping\\">\\n                            <t t-set=\\"address\\">\\n                                <address class=\\"mb-0\\" t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                                <div t-if=\\"o.partner_id.vat\\" id=\\"partner_vat_address_same_as_shipping\\">\\n                                    <t t-if=\\"o.company_id.account_fiscal_country_id.vat_label\\" t-esc=\\"o.company_id.account_fiscal_country_id.vat_label\\" id=\\"inv_tax_id_label\\"/>\\n                                    <t t-else=\\"\\">Tax ID</t>: <span t-field=\\"o.partner_id.vat\\"/>\\n                                </div>\\n                            </t>\\n                        </div>\\n                    </t>\\n                    <t t-else=\\"\\">\\n                        <div class=\\"offset-col-6 col-6\\" name=\\"no_shipping\\">\\n                            <t t-set=\\"address\\">\\n                                <address class=\\"mb-0\\" t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                                <div t-if=\\"o.partner_id.vat\\" id=\\"partner_vat_no_shipping\\">\\n                                    <t t-if=\\"o.company_id.account_fiscal_country_id.vat_label\\" t-esc=\\"o.company_id.account_fiscal_country_id.vat_label\\" id=\\"inv_tax_id_label\\"/>\\n                                    <t t-else=\\"\\">Tax ID</t>: <span t-field=\\"o.partner_id.vat\\"/>\\n                                </div>\\n                            </t>\\n                        </div>\\n                    </t>\\n                </div>\\n                <div class=\\"mt-5\\">\\n                    <div class=\\"page\\">\\n                        <h2>\\n                            <span t-if=\\"o.move_type == 'out_invoice' and o.state == 'posted'\\">Invoice</span>\\n                            <span t-if=\\"o.move_type == 'out_invoice' and o.state == 'draft'\\">Draft Invoice</span>\\n                            <span t-if=\\"o.move_type == 'out_invoice' and o.state == 'cancel'\\">Cancelled Invoice</span>\\n                            <span t-if=\\"o.move_type == 'out_refund'\\">Credit Note</span>\\n                            <span t-if=\\"o.move_type == 'in_refund'\\">Vendor Credit Note</span>\\n                            <span t-if=\\"o.move_type == 'in_invoice'\\">Vendor Bill</span>\\n                            <span t-if=\\"o.name != '/'\\" t-field=\\"o.name\\"/>\\n                        </h2>\\n\\n                        <div id=\\"informations\\" class=\\"row mt-4 mb-4\\">\\n                            <div class=\\"col-auto col-3 mw-100 mb-2\\" t-if=\\"o.invoice_date\\" name=\\"invoice_date\\">\\n                                <t t-if=\\"o.move_type == 'out_invoice'\\"><strong>Invoice Date:</strong></t>\\n                                <t t-elif=\\"o.move_type == 'out_refund'\\"><strong>Credit Note Date:</strong></t>\\n                                <t t-elif=\\"o.move_type == 'out_receipt'\\"><strong>Receipt Date:</strong></t>\\n                                <t t-else=\\"\\"><strong>Date:</strong></t>\\n                                <p class=\\"m-0\\" t-field=\\"o.invoice_date\\"/>\\n                            </div>\\n                            <div class=\\"col-auto col-3 mw-100 mb-2\\" t-if=\\"o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted'\\" name=\\"due_date\\">\\n                                <strong>Due Date:</strong>\\n                                <p class=\\"m-0\\" t-field=\\"o.invoice_date_due\\"/>\\n                            </div>\\n                            <div class=\\"col-auto col-3 mw-100 mb-2\\" t-if=\\"o.invoice_origin\\" name=\\"origin\\">\\n                                <strong>Source:</strong>\\n                                <p class=\\"m-0\\" t-field=\\"o.invoice_origin\\"/>\\n                            </div>\\n                            <div class=\\"col-auto col-3 mw-100 mb-2\\" t-if=\\"o.partner_id.ref\\" name=\\"customer_code\\">\\n                                <strong>Customer Code:</strong>\\n                                <p class=\\"m-0\\" t-field=\\"o.partner_id.ref\\"/>\\n                            </div>\\n                            <div class=\\"col-auto col-3 mw-100 mb-2\\" t-if=\\"o.ref\\" name=\\"reference\\">\\n                                <strong>Reference:</strong>\\n                                <p class=\\"m-0\\" t-field=\\"o.ref\\"/>\\n                            </div>\\n                        </div>\\n\\n                        <t t-set=\\"display_discount\\" t-value=\\"any(l.discount for l in o.invoice_line_ids)\\"/>\\n\\n                        <table class=\\"table table-sm o_main_table table-borderless\\" name=\\"invoice_line_table\\">\\n                            <thead>\\n                                <tr>\\n                                    <th name=\\"th_description\\" class=\\"text-start\\"><span>Description</span></th>\\n                                    <th name=\\"th_quantity\\" class=\\"text-end\\"><span>Quantity</span></th>\\n                                    <th name=\\"th_priceunit\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"><span>Unit Price</span></th>\\n                                    <th name=\\"th_price_unit\\" t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <span>Disc.%</span>\\n                                    </th>\\n                                    <th name=\\"th_taxes\\" t-attf-class=\\"text-start {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"><span>Taxes</span></th>\\n                                    <th name=\\"th_subtotal\\" class=\\"text-end\\">\\n                                        <span groups=\\"account.group_show_line_subtotals_tax_excluded\\">Amount</span>\\n                                        <span groups=\\"account.group_show_line_subtotals_tax_included\\">Total Price</span>\\n                                    </th>\\n                                </tr>\\n                            </thead>\\n                            <tbody class=\\"invoice_tbody\\">\\n                                <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                                <t t-set=\\"lines\\" t-value=\\"o.invoice_line_ids.sorted(key=lambda l: (-l.sequence, l.date, l.move_name, -l.id), reverse=True)\\"/>\\n\\n                                <t t-foreach=\\"lines\\" t-as=\\"line\\">\\n                                    <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_subtotal\\" groups=\\"account.group_show_line_subtotals_tax_excluded\\"/>\\n                                    <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_total\\" groups=\\"account.group_show_line_subtotals_tax_included\\"/>\\n\\n                                    <tr t-att-class=\\"'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''\\">\\n                                        <t t-if=\\"line.display_type == 'product'\\" name=\\"account_invoice_line_accountable\\">\\n                                            <td name=\\"account_invoice_line_name\\"><span t-field=\\"line.name\\" t-options=\\"{'widget': 'text'}\\"/></td>\\n                                            <td class=\\"text-end\\">\\n                                                <span t-field=\\"line.quantity\\"/>\\n                                                <span t-field=\\"line.product_uom_id\\" groups=\\"uom.group_uom\\"/>\\n                                            </td>\\n                                            <td t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                <span class=\\"text-nowrap\\" t-field=\\"line.price_unit\\"/>\\n                                            </td>\\n                                            <td t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                <span class=\\"text-nowrap\\" t-field=\\"line.discount\\"/>\\n                                            </td>\\n                                            <td t-attf-class=\\"text-start {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                <span t-esc=\\"', '.join(map(lambda x: (x.description or x.name), line.tax_ids))\\" id=\\"line_tax_ids\\"/>\\n                                            </td>\\n                                            <td class=\\"text-end o_price_total\\">\\n                                                <span class=\\"text-nowrap\\" t-field=\\"line.price_subtotal\\" groups=\\"account.group_show_line_subtotals_tax_excluded\\"/>\\n                                                <span class=\\"text-nowrap\\" t-field=\\"line.price_total\\" groups=\\"account.group_show_line_subtotals_tax_included\\"/>\\n                                            </td>\\n                                        </t>\\n                                        <t t-if=\\"line.display_type == 'line_section'\\">\\n                                            <td colspan=\\"99\\">\\n                                                <span t-field=\\"line.name\\" t-options=\\"{'widget': 'text'}\\"/>\\n                                            </td>\\n                                            <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                            <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                                        </t>\\n                                        <t t-if=\\"line.display_type == 'line_note'\\">\\n                                            <td colspan=\\"99\\">\\n                                                <span t-field=\\"line.name\\" t-options=\\"{'widget': 'text'}\\"/>\\n                                            </td>\\n                                        </t>\\n                                    </tr>\\n\\n                                    <t t-if=\\"current_section and (line_last or lines[line_index+1].display_type == 'line_section')\\">\\n                                        <tr class=\\"is-subtotal text-end\\">\\n                                            <td colspan=\\"99\\">\\n                                                <strong class=\\"mr16\\">Subtotal</strong>\\n                                                <span t-esc=\\"current_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\"/>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                </t>\\n                            </tbody>\\n                        </table>\\n\\n                    <div class=\\"clearfix mb-4\\">\\n                        <div id=\\"total\\" class=\\"row\\">\\n                            <div t-attf-class=\\"#{'col-6' if report_type != 'html' else 'col-sm-7 col-md-6'} ms-auto\\">\\n                                <table class=\\"table table-sm table-borderless\\" style=\\"page-break-inside: avoid;\\">\\n\\n                                    <!--Tax totals-->\\n                                    <t t-set=\\"tax_totals\\" t-value=\\"o.tax_totals\\"/>\\n                                    <t t-call=\\"account.document_tax_totals\\"/>\\n\\n                                    <!--Payments-->\\n                                    <t t-if=\\"print_with_payments\\">\\n                                        <t t-if=\\"o.payment_state != 'invoicing_legacy'\\">\\n                                            <t t-set=\\"payments_vals\\" t-value=\\"o.sudo().invoice_payments_widget and o.sudo().invoice_payments_widget['content'] or []\\"/>\\n                                            <t t-foreach=\\"payments_vals\\" t-as=\\"payment_vals\\">\\n                                                <tr t-if=\\"payment_vals['is_exchange'] == 0\\">\\n                                                    <td>\\n                                                        <i class=\\"oe_form_field text-end oe_payment_label\\">Paid on <t t-esc=\\"payment_vals['date']\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/></i>\\n                                                    </td>\\n                                                    <td class=\\"text-end\\">\\n                                                        <span t-esc=\\"payment_vals['amount']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\"/>\\n                                                    </td>\\n                                                </tr>\\n                                            </t>\\n                                            <t t-if=\\"len(payments_vals) &gt; 0\\">\\n                                                <tr class=\\"border-black fw-bold\\">\\n                                                    <td>Amount Due</td>\\n                                                    <td class=\\"text-end\\">\\n                                                        <span t-field=\\"o.amount_residual\\"/>\\n                                                    </td>\\n                                                </tr>\\n                                                </t>\\n                                            </t>\\n                                        </t>\\n                                    </table>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    <p t-if=\\"o.move_type in ('out_invoice', 'in_refund') and o.payment_reference\\" name=\\"payment_communication\\" class=\\"mt-4\\">\\n                        Please use the following communication for your payment : <b><span t-field=\\"o.payment_reference\\"/></b>\\n                    </p>\\n                    <t t-set=\\"payment_term_details\\" t-value=\\"o.payment_term_details\\"/>\\n                    <div t-field=\\"o.invoice_payment_term_id.note\\" name=\\"payment_term\\"/>\\n                    <t t-if=\\"o.invoice_payment_term_id.display_on_invoice and payment_term_details\\">\\n                        <div t-if=\\"o.show_payment_term_details\\" id=\\"total_payment_term_details_table\\" class=\\"row\\">\\n                            <div t-attf-class=\\"#{'col-7' if report_type != 'html' else 'col-sm-7 col-md-6'} mt-2 mb-2\\">\\n                                <table class=\\"table table-sm\\" style=\\"page-break-inside: avoid;\\">\\n                                    <th class=\\"border-black text-start\\">\\n                                        Due Date\\n                                    </th>\\n                                    <th class=\\"border-black text-end\\">\\n                                        Amount Due\\n                                    </th>\\n                                    <th t-if=\\"o.show_discount_details\\" class=\\"border-black text-end\\">\\n                                        Discount\\n                                    </th>\\n                                    <t t-foreach=\\"payment_term_details\\" t-as=\\"term\\">\\n                                        <tr>\\n                                            <td t-esc=\\"term.get('date')\\" class=\\"text-start\\"/>\\n                                            <td t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-esc=\\"term.get('amount')\\" class=\\"text-end\\"/>\\n                                            <td t-if=\\"term.get('discount_date')\\" class=\\"text-end\\">\\n                                                <span t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-esc=\\"term.get('discount_amount_currency')\\"/> if paid before\\n                                                <span t-esc=\\"term.get('discount_date')\\"/>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                </table>\\n                            </div>\\n                        </div>\\n                    </t>\\n                    <div t-if=\\"not is_html_empty(o.narration)\\" name=\\"comment\\">\\n                        <span t-field=\\"o.narration\\"/>\\n                    </div>\\n                    <p t-if=\\"not is_html_empty(o.fiscal_position_id.note)\\" name=\\"note\\">\\n                        <span t-field=\\"o.fiscal_position_id.note\\"/>\\n                    </p>\\n                    <p t-if=\\"o.invoice_incoterm_id\\" name=\\"incoterm\\">\\n                        <strong>Incoterm: </strong><span t-field=\\"o.invoice_incoterm_id.code\\"/> - <span t-field=\\"o.invoice_incoterm_id.name\\"/>\\n                    </p>\\n                    <div id=\\"qrcode\\" t-if=\\"o.display_qr_code and o.amount_residual &gt; 0\\">\\n                        <t t-set=\\"qr_code_url\\" t-value=\\"o._generate_qr_code(silent_errors=True)\\"/>\\n                        <p t-if=\\"qr_code_url\\">\\n                            <strong class=\\"text-center\\">Scan me with your banking app.</strong><br/><br/>\\n                            <img class=\\"border border-dark rounded\\" t-att-src=\\"qr_code_url\\"/>\\n                        </p>\\n                    </div>\\n                    </div>\\n                </div>\\n            </t>\\n        </t>"}	<t t-name="account.report_invoice_document">\n            <t t-call="web.external_layout">\n                <t t-set="o" t-value="o.with_context(lang=lang)"/>\n                <t t-set="forced_vat" t-value="o.fiscal_position_id.foreign_vat"/> <!-- So that it appears in the footer of the report instead of the company VAT if it's set -->\n                <div class="row">\n                    <t t-if="o.partner_shipping_id and (o.partner_shipping_id != o.partner_id)">\n                        <div class="col-6">\n                            <t t-set="information_block">\n                                <div groups="account.group_delivery_invoice_address" name="shipping_address_block">\n                                    <strong>Shipping Address:</strong>\n                                    <div t-field="o.partner_shipping_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                                </div>\n                            </t>\n                        </div>\n                        <div class="col-6" name="address_not_same_as_shipping">\n                            <t t-set="address">\n                                <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                                <div t-if="o.partner_id.vat" id="partner_vat_address_not_same_as_shipping">\n                                    <t t-if="o.company_id.account_fiscal_country_id.vat_label" t-esc="o.company_id.account_fiscal_country_id.vat_label" id="inv_tax_id_label"/>\n                                    <t t-else="">Tax ID</t>: <span t-field="o.partner_id.vat"/>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                    <t t-elif="o.partner_shipping_id and (o.partner_shipping_id == o.partner_id)">\n                        <div class="offset-col-6 col-6" name="address_same_as_shipping">\n                            <t t-set="address">\n                                <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                                <div t-if="o.partner_id.vat" id="partner_vat_address_same_as_shipping">\n                                    <t t-if="o.company_id.account_fiscal_country_id.vat_label" t-esc="o.company_id.account_fiscal_country_id.vat_label" id="inv_tax_id_label"/>\n                                    <t t-else="">Tax ID</t>: <span t-field="o.partner_id.vat"/>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                    <t t-else="">\n                        <div class="offset-col-6 col-6" name="no_shipping">\n                            <t t-set="address">\n                                <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                                <div t-if="o.partner_id.vat" id="partner_vat_no_shipping">\n                                    <t t-if="o.company_id.account_fiscal_country_id.vat_label" t-esc="o.company_id.account_fiscal_country_id.vat_label" id="inv_tax_id_label"/>\n                                    <t t-else="">Tax ID</t>: <span t-field="o.partner_id.vat"/>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                </div>\n                <div class="mt-5">\n                    <div class="page">\n                        <h2>\n                            <span t-if="o.move_type == 'out_invoice' and o.state == 'posted'">Invoice</span>\n                            <span t-if="o.move_type == 'out_invoice' and o.state == 'draft'">Draft Invoice</span>\n                            <span t-if="o.move_type == 'out_invoice' and o.state == 'cancel'">Cancelled Invoice</span>\n                            <span t-if="o.move_type == 'out_refund'">Credit Note</span>\n                            <span t-if="o.move_type == 'in_refund'">Vendor Credit Note</span>\n                            <span t-if="o.move_type == 'in_invoice'">Vendor Bill</span>\n                            <span t-if="o.name != '/'" t-field="o.name"/>\n                        </h2>\n\n                        <div id="informations" class="row mt-4 mb-4">\n                            <div class="col-auto col-3 mw-100 mb-2" t-if="o.invoice_date" name="invoice_date">\n                                <t t-if="o.move_type == 'out_invoice'"><strong>Invoice Date:</strong></t>\n                                <t t-elif="o.move_type == 'out_refund'"><strong>Credit Note Date:</strong></t>\n                                <t t-elif="o.move_type == 'out_receipt'"><strong>Receipt Date:</strong></t>\n                                <t t-else=""><strong>Date:</strong></t>\n                                <p class="m-0" t-field="o.invoice_date"/>\n                            </div>\n                            <div class="col-auto col-3 mw-100 mb-2" t-if="o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted'" name="due_date">\n                                <strong>Due Date:</strong>\n                                <p class="m-0" t-field="o.invoice_date_due"/>\n                            </div>\n                            <div class="col-auto col-3 mw-100 mb-2" t-if="o.invoice_origin" name="origin">\n                                <strong>Source:</strong>\n                                <p class="m-0" t-field="o.invoice_origin"/>\n                            </div>\n                            <div class="col-auto col-3 mw-100 mb-2" t-if="o.partner_id.ref" name="customer_code">\n                                <strong>Customer Code:</strong>\n                                <p class="m-0" t-field="o.partner_id.ref"/>\n                            </div>\n                            <div class="col-auto col-3 mw-100 mb-2" t-if="o.ref" name="reference">\n                                <strong>Reference:</strong>\n                                <p class="m-0" t-field="o.ref"/>\n                            </div>\n                        </div>\n\n                        <t t-set="display_discount" t-value="any(l.discount for l in o.invoice_line_ids)"/>\n\n                        <table class="table table-sm o_main_table table-borderless" name="invoice_line_table">\n                            <thead>\n                                <tr>\n                                    <th name="th_description" class="text-start"><span>Description</span></th>\n                                    <th name="th_quantity" class="text-end"><span>Quantity</span></th>\n                                    <th name="th_priceunit" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}"><span>Unit Price</span></th>\n                                    <th name="th_price_unit" t-if="display_discount" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                        <span>Disc.%</span>\n                                    </th>\n                                    <th name="th_taxes" t-attf-class="text-start {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}"><span>Taxes</span></th>\n                                    <th name="th_subtotal" class="text-end">\n                                        <span groups="account.group_show_line_subtotals_tax_excluded">Amount</span>\n                                        <span groups="account.group_show_line_subtotals_tax_included">Total Price</span>\n                                    </th>\n                                </tr>\n                            </thead>\n                            <tbody class="invoice_tbody">\n                                <t t-set="current_subtotal" t-value="0"/>\n                                <t t-set="lines" t-value="o.invoice_line_ids.sorted(key=lambda l: (-l.sequence, l.date, l.move_name, -l.id), reverse=True)"/>\n\n                                <t t-foreach="lines" t-as="line">\n                                    <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal" groups="account.group_show_line_subtotals_tax_excluded"/>\n                                    <t t-set="current_subtotal" t-value="current_subtotal + line.price_total" groups="account.group_show_line_subtotals_tax_included"/>\n\n                                    <tr t-att-class="'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''">\n                                        <t t-if="line.display_type == 'product'" name="account_invoice_line_accountable">\n                                            <td name="account_invoice_line_name"><span t-field="line.name" t-options="{'widget': 'text'}"/></td>\n                                            <td class="text-end">\n                                                <span t-field="line.quantity"/>\n                                                <span t-field="line.product_uom_id" groups="uom.group_uom"/>\n                                            </td>\n                                            <td t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                                <span class="text-nowrap" t-field="line.price_unit"/>\n                                            </td>\n                                            <td t-if="display_discount" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                                <span class="text-nowrap" t-field="line.discount"/>\n                                            </td>\n                                            <td t-attf-class="text-start {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                                <span t-esc="', '.join(map(lambda x: (x.description or x.name), line.tax_ids))" id="line_tax_ids"/>\n                                            </td>\n                                            <td class="text-end o_price_total">\n                                                <span class="text-nowrap" t-field="line.price_subtotal" groups="account.group_show_line_subtotals_tax_excluded"/>\n                                                <span class="text-nowrap" t-field="line.price_total" groups="account.group_show_line_subtotals_tax_included"/>\n                                            </td>\n                                        </t>\n                                        <t t-if="line.display_type == 'line_section'">\n                                            <td colspan="99">\n                                                <span t-field="line.name" t-options="{'widget': 'text'}"/>\n                                            </td>\n                                            <t t-set="current_section" t-value="line"/>\n                                            <t t-set="current_subtotal" t-value="0"/>\n                                        </t>\n                                        <t t-if="line.display_type == 'line_note'">\n                                            <td colspan="99">\n                                                <span t-field="line.name" t-options="{'widget': 'text'}"/>\n                                            </td>\n                                        </t>\n                                    </tr>\n\n                                    <t t-if="current_section and (line_last or lines[line_index+1].display_type == 'line_section')">\n                                        <tr class="is-subtotal text-end">\n                                            <td colspan="99">\n                                                <strong class="mr16">Subtotal</strong>\n                                                <span t-esc="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                            </td>\n                                        </tr>\n                                    </t>\n                                </t>\n                            </tbody>\n                        </table>\n\n                    <div class="clearfix mb-4">\n                        <div id="total" class="row">\n                            <div t-attf-class="#{'col-6' if report_type != 'html' else 'col-sm-7 col-md-6'} ms-auto">\n                                <table class="table table-sm table-borderless" style="page-break-inside: avoid;">\n\n                                    <!--Tax totals-->\n                                    <t t-set="tax_totals" t-value="o.tax_totals"/>\n                                    <t t-call="account.document_tax_totals"/>\n\n                                    <!--Payments-->\n                                    <t t-if="print_with_payments">\n                                        <t t-if="o.payment_state != 'invoicing_legacy'">\n                                            <t t-set="payments_vals" t-value="o.sudo().invoice_payments_widget and o.sudo().invoice_payments_widget['content'] or []"/>\n                                            <t t-foreach="payments_vals" t-as="payment_vals">\n                                                <tr t-if="payment_vals['is_exchange'] == 0">\n                                                    <td>\n                                                        <i class="oe_form_field text-end oe_payment_label">Paid on <t t-esc="payment_vals['date']" t-options="{&quot;widget&quot;: &quot;date&quot;}"/></i>\n                                                    </td>\n                                                    <td class="text-end">\n                                                        <span t-esc="payment_vals['amount']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                                    </td>\n                                                </tr>\n                                            </t>\n                                            <t t-if="len(payments_vals) &gt; 0">\n                                                <tr class="border-black fw-bold">\n                                                    <td>Amount Due</td>\n                                                    <td class="text-end">\n                                                        <span t-field="o.amount_residual"/>\n                                                    </td>\n                                                </tr>\n                                                </t>\n                                            </t>\n                                        </t>\n                                    </table>\n                                </div>\n                            </div>\n                        </div>\n                    <p t-if="o.move_type in ('out_invoice', 'in_refund') and o.payment_reference" name="payment_communication" class="mt-4">\n                        Please use the following communication for your payment : <b><span t-field="o.payment_reference"/></b>\n                    </p>\n                    <t t-set="payment_term_details" t-value="o.payment_term_details"/>\n                    <div t-field="o.invoice_payment_term_id.note" name="payment_term"/>\n                    <t t-if="o.invoice_payment_term_id.display_on_invoice and payment_term_details">\n                        <div t-if="o.show_payment_term_details" id="total_payment_term_details_table" class="row">\n                            <div t-attf-class="#{'col-7' if report_type != 'html' else 'col-sm-7 col-md-6'} mt-2 mb-2">\n                                <table class="table table-sm" style="page-break-inside: avoid;">\n                                    <th class="border-black text-start">\n                                        Due Date\n                                    </th>\n                                    <th class="border-black text-end">\n                                        Amount Due\n                                    </th>\n                                    <th t-if="o.show_discount_details" class="border-black text-end">\n                                        Discount\n                                    </th>\n                                    <t t-foreach="payment_term_details" t-as="term">\n                                        <tr>\n                                            <td t-esc="term.get('date')" class="text-start"/>\n                                            <td t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}" t-esc="term.get('amount')" class="text-end"/>\n                                            <td t-if="term.get('discount_date')" class="text-end">\n                                                <span t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}" t-esc="term.get('discount_amount_currency')"/> if paid before\n                                                <span t-esc="term.get('discount_date')"/>\n                                            </td>\n                                        </tr>\n                                    </t>\n                                </table>\n                            </div>\n                        </div>\n                    </t>\n                    <div t-if="not is_html_empty(o.narration)" name="comment">\n                        <span t-field="o.narration"/>\n                    </div>\n                    <p t-if="not is_html_empty(o.fiscal_position_id.note)" name="note">\n                        <span t-field="o.fiscal_position_id.note"/>\n                    </p>\n                    <p t-if="o.invoice_incoterm_id" name="incoterm">\n                        <strong>Incoterm: </strong><span t-field="o.invoice_incoterm_id.code"/> - <span t-field="o.invoice_incoterm_id.name"/>\n                    </p>\n                    <div id="qrcode" t-if="o.display_qr_code and o.amount_residual &gt; 0">\n                        <t t-set="qr_code_url" t-value="o._generate_qr_code(silent_errors=True)"/>\n                        <p t-if="qr_code_url">\n                            <strong class="text-center">Scan me with your banking app.</strong><br/><br/>\n                            <img class="border border-dark rounded" t-att-src="qr_code_url"/>\n                        </p>\n                    </div>\n                    </div>\n                </div>\n            </t>\n        </t>	f	t	2023-11-01 09:26:09.464869	2024-05-06 12:22:55.631576	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
687	16	\N	1	1	document_tax_totals	\N	account.document_tax_totals	qweb	account/views/report_invoice.xml	\N	primary	{"en_US": "<t t-name=\\"account.document_tax_totals\\">\\n            <!--\\n                Generic template to display tax totals in pdf reports.\\n                Used by invoices, SO and PO.\\n\\n                ARGUMENTS:\\n                - tax_totals: dict in the form generated by account.move's _get_tax_totals.\\n            -->\\n            <t t-foreach=\\"tax_totals['subtotals']\\" t-as=\\"subtotal\\">\\n                <tr class=\\"border-black o_subtotal\\">\\n                    <td><strong t-esc=\\"subtotal['name']\\"/></td>\\n\\n                    <td class=\\"text-end\\">\\n                        <span t-att-class=\\"oe_subtotal_footer_separator\\" t-esc=\\"subtotal['formatted_amount']\\"/>\\n                    </td>\\n                </tr>\\n\\n                <t t-set=\\"subtotal_to_show\\" t-value=\\"subtotal['name']\\"/>\\n                <t t-call=\\"account.tax_groups_totals\\"/>\\n            </t>\\n\\n            <t t-if=\\"'formatted_rounding_amount' in tax_totals and tax_totals['rounding_amount'] != 0\\">\\n                <td>Rounding</td>\\n                <td class=\\"text-end\\">\\n                    <span t-esc=\\"tax_totals['formatted_rounding_amount']\\"/>\\n                </td>\\n            </t>\\n            \\n            <!--Total amount with all taxes-->\\n            <tr class=\\"border-black o_total\\">\\n                <td><strong>Total</strong></td>\\n                <td class=\\"text-end\\">\\n                    <span t-esc=\\"tax_totals['formatted_amount_total_rounded']\\" t-if=\\"'formatted_amount_total_rounded' in tax_totals\\"/>\\n                    <span t-esc=\\"tax_totals['formatted_amount_total']\\" t-else=\\"\\"/>\\n                </td>\\n            </tr>\\n        </t>"}	<t t-name="account.document_tax_totals">\n            <!--\n                Generic template to display tax totals in pdf reports.\n                Used by invoices, SO and PO.\n\n                ARGUMENTS:\n                - tax_totals: dict in the form generated by account.move's _get_tax_totals.\n            -->\n            <t t-foreach="tax_totals['subtotals']" t-as="subtotal">\n                <tr class="border-black o_subtotal">\n                    <td><strong t-esc="subtotal['name']"/></td>\n\n                    <td class="text-end">\n                        <span t-att-class="oe_subtotal_footer_separator" t-esc="subtotal['formatted_amount']"/>\n                    </td>\n                </tr>\n\n                <t t-set="subtotal_to_show" t-value="subtotal['name']"/>\n                <t t-call="account.tax_groups_totals"/>\n            </t>\n\n            <t t-if="'formatted_rounding_amount' in tax_totals and tax_totals['rounding_amount'] != 0">\n                <td>Rounding</td>\n                <td class="text-end">\n                    <span t-esc="tax_totals['formatted_rounding_amount']"/>\n                </td>\n            </t>\n            \n            <!--Total amount with all taxes-->\n            <tr class="border-black o_total">\n                <td><strong>Total</strong></td>\n                <td class="text-end">\n                    <span t-esc="tax_totals['formatted_amount_total_rounded']" t-if="'formatted_amount_total_rounded' in tax_totals"/>\n                    <span t-esc="tax_totals['formatted_amount_total']" t-else=""/>\n                </td>\n            </tr>\n        </t>	f	t	2023-11-01 09:26:09.464869	2024-05-06 12:22:55.631576	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
