y account.move's _get_tax_totals.\n                - subtotal_to_show: The subtotal we need to render the groups from\n            -->\n            <t t-foreach="tax_totals['groups_by_subtotal'][subtotal_to_show]" t-as="amount_by_group">\n                <tr>\n                    <t t-if="tax_totals['display_tax_base']">\n                        <td>\n                            <span t-esc="amount_by_group['tax_group_name']"/>\n                            <span class="text-nowrap"> on\n                                <t t-esc="amount_by_group['formatted_tax_group_base_amount']"/>\n                            </span>\n                        </td>\n                        <td class="text-end o_price_total">\n                            <span class="text-nowrap" t-esc="amount_by_group['formatted_tax_group_amount']"/>\n                        </td>\n                    </t>\n                    <t t-else="">\n                        <td><span class="text-nowrap" t-esc="amount_by_group['tax_group_name']"/></td>\n                        <td class="text-end o_price_total">\n                            <span class="text-nowrap" t-esc="amount_by_group['formatted_tax_group_amount']"/>\n                        </td>\n                    </t>\n                </tr>\n            </t>\n        </t>	f	t	2023-11-01 09:26:09.464869	2024-05-06 12:22:55.631576	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
