s=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"account_default_credit_limit\\"/>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n                        <h2>Customer Payments</h2>\\n                        <div class=\\"row mt16 o_settings_container\\" id=\\"pay_invoice_online_setting_container\\">\\n                            <div class=\\"col-12 col-lg-6 o_setting_box\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_payment\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\">\\n                                    <label for=\\"module_account_payment\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Let your customers pay their invoices online\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"account_batch_payment\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_batch_payment\\" widget=\\"upgrade_boolean\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\">\\n                                    <label for=\\"module_account_batch_payment\\" string=\\"Batch Payments\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Group payments into a single batch to ease the reconciliation process\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"collect_customer_payment\\" title=\\"If you check this box, you will be able to collect payments using SEPA Direct Debit mandates.\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_sepa_direct_debit\\" class=\\"oe_inline\\" widget=\\"upgrade_boolean\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\" name=\\"sepa_direct_debit_right_pane\\">\\n                                    <label string=\\"SEPA Direct Debit (SDD)\\" for=\\"module_account_sepa_direct_debit\\"/>\\n                                    <span class=\\"fa fa-lg fa-building-o\\" title=\\"Values set here are company-specific.\\" aria-label=\\"Values set here are company-specific.\\" groups=\\"base.group_multi_company\\" role=\\"img\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Collect customer payments in one-click using Euro SEPA Service\\n                                    </div>\\n                                    <div class=\\"content-group\\" attrs=\\"{'invisible': [('module_account_sepa_direct_debit', '=', False)]}\\">\\n                                        <div class=\\"text-warning mt16 mb4\\">\\n                                            Save this page and come back here to set up the feature.\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"col-xs-12 col-md-6 o_setting_box\\" id=\\"qr_code_invoices\\" title=\\"Add a QR-code to your invoices so that your customers can pay instantly with their mobile banking application.\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"qr_code\\" class=\\"oe_inline\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\" name=\\"qr_code_right_pane\\">\\n                                    <label string=\\"QR Codes\\" for=\\"qr_code\\"/>\\n                                    <span class=\\"fa fa-lg fa-building-o\\" title=\\"Values set here are company-specific.\\" aria-label=\\"Values set here are company-specific.\\" groups=\\"base.group_multi_company\\" role=\\"img\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Add a payment QR-code to your invoices\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n                        <h2>Vendor Bills</h2>\\n                        <div class=\\"row mt16 o_settings_container\\" id=\\"account_vendor_bills\\">\\n                            <div class=\\"col-xs-12 col-md-6 o_setting_box\\" id=\\"show_purchase_receipts\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"group_show_purchase_receipts\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\" name=\\"show_purchase_receipts_right_pane\\">\\n                                    <label for=\\"group_show_purchase_receipts\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Activate to create purchase receipt\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n                        <h2>Vendor Payments</h2>\\n                        <div class=\\"row mt16 o_settings_container\\" id=\\"print_vendor_checks_setting_container\\">\\n                            <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"print_checks\\" groups=\\"account.group_account_user\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_check_printing\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\">\\n                                    <label string=\\"Checks\\" for=\\"module_account_check_printing\\"/>\\n                                    <span class=\\"fa fa-lg fa-building-o\\" title=\\"Values set here are company-specific.\\" aria-label=\\"Values set here are company-specific.\\" groups=\\"base.group_multi_company\\" role=\\"img\\"/>\\n                                    <div class=\\"text-muted\\" id=\\"print_bills_payment\\">\\n                                        Print checks to pay your vendors\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"sepa_payments\\" title=\\"If you check this box, you will be able to register your payment using SEPA.\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_sepa\\" widget=\\"upgrade_boolean\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\" name=\\"sepa_right_pane\\">\\n                                    <label for=\\"module_account_sepa\\"/>\\n                                    <span class=\\"fa fa-lg fa-building-o\\" title=\\"Values set here are company-specific.\\" aria-label=\\"Values set here are company-specific.\\" groups=\\"base.group_multi_company\\" role=\\"img\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Pay your bills in one-click using Euro SEPA Service\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n\\n                        <h2>Digitization</h2>\\n                        <div class=\\"row mt16 o_settings_container\\" id=\\"account_digitalization\\">\\n                            <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"account_ocr_settings\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_invoice_extract\\" widget=\\"upgrade_boolean\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\" id=\\"digitalizeocr\\">\\n                                    <label for=\\"module_account_invoice_extract\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Digitize your PDF or scanned documents with OCR and Artificial Intelligence\\n                                    </div>\\n                                    <div id=\\"msg_invoice_extract\\" class=\\"content-group\\" attrs=\\"{'invisible': [('module_account_invoice_extract', '=', False)]}\\">\\n                                        <div class=\\"text-warning mt16 mb4\\">\\n                                            Save this page and come back here to set up the feature.\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <h2>Default Accounts</h2>\\n                            <div class=\\"row mt16 o_settings_container\\" id=\\"default_accounts\\">\\n                                <div class=\\"col-12 col-lg-6 o_setting_box\\" attrs=\\"{'invisible': [('group_multi_currency', '=', False)]}\\">\\n                                    <div class=\\"o_setting_left_pane\\"/>\\n                                    <div class=\\"o_setting_right_pane\\">\\n                                        <div class=\\"content-group\\">\\n                                            <div>\\n                                                <span class=\\"o_form_label\\">Post Exchange difference entries in:</span>\\n                                            </div>\\n                                            <div class=\\"row mt8\\">\\n                                                <label for=\\"currency_exchange_journal_id\\" class=\\"col-lg-4 o_light_label\\" string=\\"Journal\\"/>\\n                                                <field name=\\"currency_exchange_journal_id\\"/>\\n                                            </div>\\n                                            <div class=\\"row mt8\\">\\n                                                <label for=\\"income_currency_exchange_account_id\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                                <field name=\\"income_currency_exchange_account_id\\"/>\\n                                            </div>\\n                                            <div class=\\"row mt8\\">\\n                                                <label for=\\"expense_currency_exchange_account_id\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                                <field name=\\"expense_currency_exchange_account_id\\"/>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"col-12 col-lg-6 o_setting_box\\">\\n                                    <div class=\\"o_setting_left_panel\\"/>\\n                                    <div class=\\"o_setting_right_pane\\">\\n                                        <span class=\\"o_form_label\\">The following default accounts are used with certain features.</span>\\n                                        <div class=\\"content-group\\">\\n                                            <div class=\\"row mt8\\">\\n                                                <label for=\\"account_journal_suspense_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                                <field name=\\"account_journal_suspense_account_id\\"/>\\n                                            </div>\\n                                            <div class=\\"row mt8\\">\\n                                                <label for=\\"account_journal_payment_debit_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                                <field name=\\"account_journal_payment_debit_account_id\\"/>\\n                                            </div>\\n                                            <div class=\\"row mt8\\">\\n                                                <label for=\\"account_journal_payment_credit_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                                <field name=\\"account_journal_payment_credit_account_id\\"/>\\n                                            </div>\\n                                            <div class=\\"row mt8\\">\\n                                                <label for=\\"transfer_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                                <field name=\\"transfer_account_id\\"/>\\n                                            </div>\\n                                            <div class=\\"row mt8\\">\\n                                                <label for=\\"account_journal_early_pay_discount_gain_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                                <field name=\\"account_journal_early_pay_discount_gain_account_id\\"/>\\n                                            </div>\\n                                            <div class=\\"row mt8\\">\\n                                                <label for=\\"account_journal_early_pay_discount_loss_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                                <field name=\\"account_journal_early_pay_discount_loss_account_id\\"/>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <h2>Bank &amp; Cash</h2>\\n                            <div class=\\"row mt16 o_settings_container\\" id=\\"bank_cash\\">\\n                                <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"import_bank_statements_csv\\" title=\\"Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.\\">\\n                                    <div class=\\"o_setting_left_pane\\">\\n                                        <field name=\\"module_account_bank_statement_import_csv\\" widget=\\"upgrade_boolean\\"/>\\n                                    </div>\\n                                    <div class=\\"o_setting_right_pane\\">\\n                                        <label for=\\"module_account_bank_statement_import_csv\\" string=\\"CSV Import\\"/>\\n                                        <div class=\\"text-muted\\">\\n                                            Import your bank statements in CSV\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"col-12 col-lg-6 o_setting_box\\" title=\\"Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.\\">\\n                                    <div class=\\"o_setting_left_pane\\">\\n                                        <field name=\\"module_account_bank_statement_import_qif\\" widget=\\"upgrade_boolean\\"/>\\n                                    </div>\\n                                    <div class=\\"o_setting_right_pane\\">\\n                                        <label for=\\"module_account_bank_statement_import_qif\\" string=\\"QIF Import\\"/>\\n                                        <div class=\\"text-muted\\">\\n                                            Import your bank statements in QIF\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"col-12 col-lg-6 o_setting_box\\" title=\\"Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.\\">\\n                                    <div class=\\"o_setting_left_pane\\">\\n                                        <field name=\\"module_account_bank_statement_import_ofx\\" widget=\\"upgrade_boolean\\"/>\\n                                    </div>\\n                                    <div class=\\"o_setting_right_pane\\">\\n                                        <label for=\\"module_account_bank_statement_import_ofx\\" string=\\"OFX Import\\"/>\\n                                        <div class=\\"text-muted\\">\\n                                            Import your bank statements in OFX\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"import_bank_statement_camt\\" title=\\"Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.\\">\\n                                    <div class=\\"o_setting_left_pane\\">\\n                                        <field name=\\"module_account_bank_statement_import_camt\\" widget=\\"upgrade_boolean\\"/>\\n                                    </div>\\n                                    <div class=\\"o_setting_right_pane\\">\\n                                        <label for=\\"module_account_bank_statement_import_camt\\" string=\\"CAMT Import\\"/>\\n                                        <div class=\\"text-muted\\">\\n                                            Import your bank statements in CAMT.053\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <h2>Fiscal Periods</h2>\\n                            <div class=\\"row mt16 o_settings_container\\" id=\\"accounting_reports\\">\\n                                <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"fiscalyear\\" invisible=\\"1\\" groups=\\"account.group_account_user\\"/>\\n                                <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"dynamic_report\\" invisible=\\"1\\" groups=\\"account.group_account_user\\">\\n                                    <div class=\\"o_setting_left_pane\\">\\n                                        <field name=\\"module_account_reports\\" widget=\\"upgrade_boolean\\"/>\\n                                    </div>\\n                                    <div class=\\"o_setting_right_pane\\">\\n                                        <label for=\\"module_account_reports\\"/>\\n                                        <div class=\\"text-muted\\" id=\\"account_reports\\">\\n                                            Navigate easily through reports and see what is behind the numbers\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </t>\\n                        <h2>Analytics</h2>\\n                        <div class=\\"row mt16 o_settings_container\\" id=\\"analytic\\">\\n                            <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"track_costs_revenues\\" title=\\"Allows you to use the analytic accounting.\\" groups=\\"account.group_account_user\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"group_analytic_accounting\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\">\\n                                    <label for=\\"group_analytic_accounting\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Track costs &amp; revenues by project, department, etc\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"account_budget\\" title=\\"This allows accountants to manage analytic and crossovered budgets. Once the master budgets and the budgets are defined, the project managers can set the planned amount on each analytic account.\\" groups=\\"account.group_account_user\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_budget\\" widget=\\"upgrade_boolean\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\" id=\\"budget_management\\">\\n                                    <label for=\\"module_account_budget\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Use budgets to compare actual with expected revenues and costs\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"monitor_product_margins\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_product_margin\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\">\\n                                    <label for=\\"module_product_margin\\" string=\\"Margin Analysis\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Monitor your product margins from invoices\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n                        <h2>Storno Accounting</h2>\\n                        <div class=\\"row mt16 o_settings_container\\" id=\\"storno\\">\\n                            <div class=\\"col-12 col-lg-6 o_setting_box\\" id=\\"enable_storno_accounting\\" title=\\"Allows you to use Storno accounting.\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"account_storno\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\">\\n                                    <label for=\\"account_storno\\"/>\\n                                    <span class=\\"fa fa-lg fa-building-o\\" title=\\"Values set here are company-specific.\\" aria-label=\\"Values set here are company-specific.\\" groups=\\"base.group_multi_company\\" role=\\"img\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Use Storno accounting\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n                        <h2>Accounting Firms mode</h2>\\n                        <div class=\\"row mt16 o_settings_container\\" id=\\"quick_edit_mode\\">\\n                            <div class=\\"col-12 col-lg-12 o_setting_box\\">\\n                                <div class=\\"text-muted\\">\\n                                    <p style=\\"margin-bottom: 0\\">Accounting firm mode will change invoice/bill encoding:</p>\\n                                    <p style=\\"margin-bottom: 0\\"> - The document's sequence becomes editable on all documents.</p>\\n                                    <p style=\\"margin-bottom: 0\\"> - A new field « Total (tax inc.) » to speed up and control the encoding by automating line creation with the right account &amp; tax.</p>\\n                                    <p style=\\"margin-bottom: 0\\"> - A default Customer Invoice / Vendor Bill date will be suggested.</p>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane mt16\\">\\n                                    <label for=\\"quick_edit_mode\\"/>\\n                                    <span class=\\"fa fa-lg fa-building-o\\" title=\\"Values set here are company-specific.\\" aria-label=\\"Values set here are company-specific.\\" groups=\\"base.group_multi_company\\" role=\\"img\\"/>\\n                                    <div>\\n                                        <field name=\\"quick_edit_mode\\" placeholder=\\"Disabled\\"/>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </xpath>"}	<xpath expr="//div[hasclass('settings')]" position="inside">\n                    <field name="country_code" invisible="1" groups="account.group_account_manager"/>\n                    <div class="app_settings_block" data-string="Invoicing" string="Invoicing" data-key="account" groups="account.group_account_manager">\n                        <field name="has_chart_of_accounts" invisible="1"/>\n                        <field name="has_accounting_entries" invisible="1"/>\n                        <h2 attrs="{'invisible': [('has_accounting_entries','!=',False)]}">Fiscal Localization</h2>\n                        <div class="row mt16 o_settings_container" name="fiscal_localization_setting_container" attrs="{'invisible': [('has_accounting_entries','!=',False)]}">\n                            <div class="col-12 o_setting_box">\n                                <div class="o_setting_left_pane"/>\n                                <div class="o_setting_right_pane">\n                                    <span class="o_form_label">Fiscal Localization</span>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." aria-label="Values set here are company-specific." groups="base.group_multi_company" role="img"/>\n                                    <div class="text-muted">\n                                        Taxes, fiscal positions, chart of accounts &amp; legal statements for your country\n                                    </div>\n                                    <div class="content-group">\n                                        <div class="row mt16">\n                                            <label for="chart_template_id" string="Package" class="col-2 o_light_label"/>\n                                            <field name="chart_template_id" options="{'no_open': True, 'no_create': True}"/>\n                                        </div>\n                                        <div class="mt8">\n                                            <button name="269" icon="fa-arrow-right" type="action" string="Install More Packages" discard="0" class="btn-link"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <h2>Taxes</h2>\n                        <div class="row mt16 o_settings_container" name="default_taxes_setting_container">\n                            <div class="col-12 col-lg-6 o_setting_box" id="default_taxes" title="These taxes are set in any new product created.">\n                                <div class="o_setting_left_pane"/>\n                                <div class="o_setting_right_pane">\n                                    <span class="o_form_label">Default Taxes</span>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." aria-label="Values set here are company-specific." groups="base.group_multi_company" role="img"/>\n                                    <div class="text-muted">\n                                        Default taxes applied to local transactions\n                                    </div>\n                                    <div class="content-group">\n                                        <div class="row mt16">\n                                            <label string="Sales Tax" for="sale_tax_id" class="col-lg-3 o_light_label"/>\n                                            <field name="sale_tax_id" domain="[('type_tax_use', 'in', ('sale', 'all')), ('company_id', '=', company_id)]"/>\n                                        </div>\n                                        <div class="row">\n                                            <label string="Purchase Tax" for="purchase_tax_id" class="col-lg-3 o_light_label"/>\n                                            <field name="purchase_tax_id" domain="[('type_tax_use', 'in', ('purchase', 'all')), ('company_id', '=', company_id)]"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="rounding_method" title="A rounding per line is advised if your prices are tax-included. That way, the sum of line subtotals equals the total with taxes.">\n                                <div class="o_setting_left_pane"/>\n                                <div class="o_setting_right_pane">\n                                    <span class="o_form_label">Rounding Method</span>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." aria-label="Values set here are company-specific." groups="base.group_multi_company" role="img"/>\n                                    <div class="text-muted">\n                                        How total tax amount is computed in orders and invoices\n                                    </div>\n                                     <div class="content-group">\n                                        <field name="tax_calculation_rounding_method" class="o_light_label mt16" widget="radio"/>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box">\n                                <div class="o_setting_left_pane"/>\n                                <div class="o_setting_right_pane">\n                                    <span class="o_form_label">Cash Discount Tax Reduction</span>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." role="img" aria-label="Values set here are company-specific." groups="base.group_multi_company"/>\n                                    <div class="text-muted">\n                                        When will the tax be reduced when offering a cash discount\n                                    </div>\n                                    <div class="content-group">\n                                        <field name="early_pay_discount_computation"/>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="taxcloud_settings">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_taxcloud" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="account_taxcloud_right_pane">\n                                    <label for="module_account_taxcloud" string="TaxCloud"/>\n                                    <div class="text-muted">\n                                        Compute tax rates based on U.S. ZIP codes\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="eu_service" title="If you sell goods and services to customers in a foreign EU country, you must charge VAT based on the delivery address. This rule applies regardless of where you are located.">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_l10n_eu_oss"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="l10n_eu_oss_right_pane">\n                                    <label for="module_l10n_eu_oss"/>\n                                    <a href="https://www.odoo.com/documentation/16.0/applications/finance/accounting/taxation/taxes/eu_distance_selling.html" title="Documentation" class="o_doc_link" target="_blank"/>\n                                    <div class="text-muted">\n                                        Apply VAT of the EU country to which goods and services are delivered.\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="tax_exigibility" title="Select this if the taxes should use cash basis, which will create an entry for such taxes on a given account during reconciliation." groups="account.group_account_user">\n                                <div class="o_setting_left_pane">\n                                    <field name="tax_exigibility"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="tax_exigibility"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." aria-label="Values set here are company-specific." groups="base.group_multi_company" role="img"/>\n                                    <div class="text-muted">\n                                        Allow to configure taxes using cash basis\n                                    </div>\n                                    <div class="content-group" attrs="{'invisible': [('tax_exigibility', '=', False)]}">\n                                        <div class="row mt16">\n                                            <label for="tax_cash_basis_journal_id" class="col-lg-3 o_light_label"/>\n                                            <field name="tax_cash_basis_journal_id"/>\n                                        </div>\n                                        <div class="row mt16">\n                                            <label for="account_cash_basis_base_account_id" class="col-lg-3 o_light_label"/>\n                                            <field name="account_cash_basis_base_account_id"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="tax_fiscal_country_234">\n                                <div class="o_setting_left_pane"/>\n                                <div class="o_setting_right_pane">\n                                    <span class="o_form_label">Fiscal Country</span>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." role="img" aria-label="Values set here are company-specific." groups="base.group_multi_company"/>\n                                    <div class="text-muted">\n                                        Domestic country of your accounting\n                                    </div>\n                                    <div class="text-muted">\n                                        <field name="account_fiscal_country_id" options="{'no_create': True, 'no_open': True}"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <h2>Currencies</h2>\n                        <div class="row mt16 o_settings_container" name="main_currency_setting_container">\n                            <div class="col-12 col-lg-6 o_setting_box" id="main_currency">\n                                <div class="o_setting_left_pane"/>\n                                <div class="o_setting_right_pane">\n                                    <span class="o_form_label">Main Currency</span>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." aria-label="Values set here are company-specific." groups="base.group_multi_company" role="img"/>\n                                    <div class="text-muted">\n                                        Main currency of your company\n                                    </div>\n                                    <div class="content-group">\n                                        <div class="row mt16">\n                                            <label for="currency_id" class="col-lg-3 o_light_label"/>\n                                            <field name="currency_id" options="{'no_create_edit': True, 'no_open': True}" context="{'active_test': False}"/>\n                                            <field name="group_multi_currency" invisible="1"/>\n                                        </div>\n                                        <div class="mt8">\n                                            <button type="action" name="67" string="Currencies" class="btn-link" icon="fa-arrow-right"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="update_exchange_rates" attrs="{'invisible': [('group_multi_currency', '=', False)]}">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_currency_rate_live" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_currency_rate_live"/>\n                                    <div class="text-muted" id="update_currency_live">\n                                        Update exchange rates automatically\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <h2>Customer Invoices</h2>\n                        <div class="row mt16 o_settings_container" id="invoicing_settings">\n                            <div class="col-12 col-lg-6 o_setting_box" id="default_setting_options">\n                                <div class="o_setting_left_pane">\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <span class="o_form_label">Default Sending Options</span>\n                                    <div class="text-muted">\n                                        Those options will be selected by default when clicking "Send &amp; Print" on invoices\n                                    </div>\n                                    <div class="mt16">\n                                        <div class="content-group" id="send_default">\n                                            <div>\n                                                <field name="invoice_is_print"/>\n                                                <label for="invoice_is_print"/>\n                                                <span class="fa fa-lg fa-building-o" title="Values set here are company-specific."/>\n                                            </div>\n                                            <div>\n                                                <field name="invoice_is_email"/>\n                                                <label for="invoice_is_email"/>\n                                                <span class="fa fa-lg fa-building-o" title="Values set here are company-specific."/>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="send_invoices_followups">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_snailmail_account"/>\n                                </div>\n                                <div class="o_setting_right_pane" id="snailmail_settings">\n                                    <label for="module_snailmail_account"/>\n                                    <div class="text-muted">\n                                        Send invoices and payment follow-ups by post\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="invoice_delivery_addresses">\n                                <div class="o_setting_left_pane">\n                                    <field name="group_sale_delivery_address"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="group_sale_delivery_address"/>\n                                    <a href="https://www.odoo.com/documentation/16.0/applications/sales/sales/send_quotations/different_addresses.html" title="Documentation" class="o_doc_link" target="_blank"/>\n                                    <div class="text-muted">\n                                        Select specific invoice and delivery addresses\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="line_subtotals">\n                                <div class="o_setting_left_pane">\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="show_line_subtotals_tax_selection"/>\n                                    <div class="text-muted">\n                                        Line subtotals tax display\n                                    </div>\n                                    <div class="mt16">\n                                        <field name="show_line_subtotals_tax_selection" class="o_light_label" widget="radio"/>\n                                        <field name="group_show_line_subtotals_tax_excluded" invisible="1"/>\n                                        <field name="group_show_line_subtotals_tax_included" invisible="1"/>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="get_invoice_warnings">\n                                <div class="o_setting_left_pane">\n                                    <field name="group_warning_account"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="group_warning_account" string="Warnings"/>\n                                    <div class="text-muted">\n                                        Get warnings when invoicing specific customers\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="smallest_coinage_currency">\n                                <div class="o_setting_left_pane">\n                                    <field name="group_cash_rounding"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="group_cash_rounding"/>\n                                    <div class="text-muted">\n                                        Define the smallest coinage of the currency used to pay by cash\n                                    </div>\n                                    <div class="mt8">\n                                        <button name="268" icon="fa-arrow-right" type="action" string="Cash Roundings" class="btn-link" attrs="{'invisible': [('group_cash_rounding', '=', False)]}"/>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" id="intrastat_statistics">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_intrastat" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="intrastat_right_pane">\n                                    <label for="module_account_intrastat"/>\n                                    <div class="text-muted">\n                                        Collect information and produce statistics on the trade in goods in Europe with intrastat\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="default_incoterm">\n                                <div class="o_setting_left_pane"/>\n                                <div class="o_setting_right_pane">\n                                    <span class="o_form_label">Default Incoterm</span>\n                                    <div class="text-muted">\n                                        Default Incoterm of your company\n                                    </div>\n                                    <div class="text-muted">\n                                        <field name="incoterm_id"/>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" id="show_sale_receipts">\n                                <div class="o_setting_left_pane">\n                                    <field name="group_show_sale_receipts"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="show_sale_receipts_right_pane">\n                                    <label for="group_show_sale_receipts"/>\n                                    <div class="text-muted">\n                                        Activate to create sale receipt\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="use_invoice_terms">\n                                <div class="o_setting_left_pane">\n                                    <field name="use_invoice_terms"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="use_invoice_terms"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." aria-label="Values set here are company-specific." groups="base.group_multi_company" role="img"/>\n                                    <div class="text-muted">\n                                        Add your terms &amp; conditions at the bottom of invoices/orders/quotations\n                                    </div>\n                                    <div class="content-group" attrs="{'invisible': [('use_invoice_terms','=',False)]}">\n                                        <div class="mt16">\n                                            <field name="terms_type" class="o_light_label" widget="radio"/>\n                                            <div>\n                                                <field name="invoice_terms" attrs="{'invisible': [('terms_type', '=', 'html')]}" class="oe_account_terms mt-5 w-100" placeholder="Insert your terms &amp; conditions here..."/>\n                                            </div>\n                                            <div class="mt8" attrs="{'invisible': [('terms_type', '!=', 'html')]}">\n                                                <button name="action_update_terms" icon="fa-arrow-right" type="object" string="Update Terms" class="btn-link"/>\n                                            </div>\n                                            <field name="preview_ready" invisible="1"/>\n                                            <div class="mt4 ms-1" attrs="{'invisible': [('preview_ready', '=', False)]}">\n                                                <a class="btn-link" href="/terms" role="button">\n                                                    <i class="fa fa-arrow-right"/>\n                                                    Preview\n                                                </a>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box">\n                                <div class="o_setting_left_pane">\n                                    <field name="account_use_credit_limit"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="account_use_credit_limit"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." aria-label="Values set here are company-specific." role="img"/>\n                                    <div class="text-muted">\n                                        Trigger alerts when creating Invoices and Sales Orders for Partners with a Total Receivable amount exceeding a limit.\n                                    </div>\n                                    <div class="content-group mt-2" attrs="{'invisible': [('account_use_credit_limit', '=', False)]}">\n                                        <div class="row">\n                                            <label for="account_default_credit_limit" class="col-lg-4 o_light_label"/>\n                                            <field name="account_default_credit_limit"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <h2>Customer Payments</h2>\n                        <div class="row mt16 o_settings_container" id="pay_invoice_online_setting_container">\n                            <div class="col-12 col-lg-6 o_setting_box">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_payment"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_account_payment"/>\n                                    <div class="text-muted">\n                                        Let your customers pay their invoices online\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="account_batch_payment">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_batch_payment" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_account_batch_payment" string="Batch Payments"/>\n                                    <div class="text-muted">\n                                        Group payments into a single batch to ease the reconciliation process\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-12 col-lg-6 o_setting_box" id="collect_customer_payment" title="If you check this box, you will be able to collect payments using SEPA Direct Debit mandates.">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_sepa_direct_debit" class="oe_inline" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="sepa_direct_debit_right_pane">\n                                    <label string="SEPA Direct Debit (SDD)" for="module_account_sepa_direct_debit"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." aria-label="Values set here are company-specific." groups="base.group_multi_company" role="img"/>\n                                    <div class="text-muted">\n                                        Collect customer payments in one-click using Euro SEPA Service\n                                    </div>\n                                    <div class="content-group" attrs="{'invisible': [('module_account_sepa_direct_debit', '=', False)]}">\n                                        <div class="text-warning mt16 mb4">\n                                            Save this page and come back here to set up the feature.\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" id="qr_code_invoices" title="Add a QR-code to your invoices so that your customers can pay instantly with their mobile banking application.">\n                                <div class="o_setting_left_pane">\n                                    <field name="qr_code" class="oe_inline"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="qr_code_right_pane">\n                                    <label string="QR Codes" for="qr_code"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." aria-label="Values set here are company-specific." groups="base.group_multi_company" role="img"/>\n                                    <div class="text-muted">\n                                        Add a payment QR-code to your invoices\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <h2>Vendor Bills</h2>\n                        <div class="row mt16 o_settings_container" id="account_vendor_bills">\n                            <div class="col-xs-12 col-md-6 o_setting_box" id="show_purchase_receipts">\n                                <div class="o_setting_left_pane">\n                                    <field name="group_show_purchase_receipts"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="show_purchase_receipts_right_pane">\n                                    <label for="group_show_purchase_receipts"/>\n                                    <div class="text-muted">\n                                        Activate to create purchase receipt\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <h2>Vendor Payments</h2>\n                        <div class="row mt16 o_settings_container" id="print_vendor_checks_setting_container">\n                            <div class="col-12 col-lg-6 o_setting_box" id="print_checks" groups="account.group_account_user">\n                                <div class="o_se