ll text-bg-info\\"><i class=\\"fa fa-fw fa-clock-o\\" aria-label=\\"Opened\\" title=\\"Opened\\" role=\\"img\\"/><span class=\\"d-none d-md-inline\\"> Waiting for Payment</span></span>\\n                            </t>\\n                            <t t-if=\\"invoice.state == 'posted' and invoice.payment_state in ('paid', 'in_payment')\\">\\n                                <span class=\\"badge rounded-pill text-bg-success\\"><i class=\\"fa fa-fw fa-check\\" aria-label=\\"Paid\\" title=\\"Paid\\" role=\\"img\\"/><span class=\\"d-none d-md-inline\\"> Paid</span></span>\\n                            </t>\\n                            <t t-if=\\"invoice.state == 'posted' and invoice.payment_state == 'reversed'\\">\\n                                <span class=\\"badge rounded-pill text-bg-success\\"><i class=\\"fa fa-fw fa-check\\" aria-label=\\"Reversed\\" title=\\"Reversed\\" role=\\"img\\"/><span class=\\"d-none d-md-inline\\"> Reversed</span></span>\\n                            </t>\\n                            <t t-if=\\"invoice.state == 'cancel'\\">\\n                                <span class=\\"badge rounded-pill text-bg-warning\\"><i class=\\"fa fa-fw fa-remove\\" aria-label=\\"Cancelled\\" title=\\"Cancelled\\" role=\\"img\\"/><span class=\\"d-none d-md-inline\\"> Cancelled</span></span>\\n                            </t>\\n                        </td>\\n                        <td class=\\"text-end\\"><span t-esc=\\"-invoice.amount_residual if invoice.move_type == 'out_refund' else invoice.amount_residual\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}\\"/></td>\\n                    </tr>\\n                </t>\\n            </tbody>\\n        </t>\\n      </t>\\n    </t>"}	<t name="My Invoices and Payments" t-name="account.portal_my_invoices">\n      <t t-call="portal.portal_layout">\n        <t t-set="breadcrumbs_searchbar" t-value="True"/>\n\n        <t t-call="portal.portal_searchbar">\n            <t t-set="title">Invoices</t>\n        </t>\n        <t t-if="not invoices">\n            <p>There are currently no invoices and payments for your account.</p>\n        </t>\n        <t t-if="invoices" t-call="portal.portal_table">\n            <thead>\n                <tr class="active">\n                    <th>Invoice #</th>\n                    <th>Invoice Date</th>\n                    <th class="d-none d-md-table-cell">Due Date</th>\n                    <th class="text-center">Status</th>\n                    <th class="text-end">Amount Due</th>\n                </tr>\n            </thead>\n            <tbody>\n                <t t-foreach="invoices" t-as="invoice">\n                    <tr>\n                        <td>\n                            <a t-att-href="invoice.get_portal_url()" t-att-title="invoice.name">\n                                <t t-esc="invoice.name" t-if="invoice.name != '/'"/>\n                                <em t-else="">Draft Invoice</em>\n                            </a>\n                        </td>\n                        <td><span t-field="invoice.invoice_date"/></td>\n                        <td class="d-none d-md-table-cell"><span t-field="invoice.invoice_date_due"/></td>\n                        <td class="tx_status text-center">\n                            <t t-if="invoice.state == 'posted' and invoice.payment_state not in ('in_payment', 'paid', 'reversed')">\n                                <span class="badge rounded-pill text-bg-info"><i class="fa fa-fw fa-clock-o" aria-label="Opened" title="Opened" role="img"/><span class="d-none d-md-inline"> Waiting for Payment</span></span>\n                            </t>\n                            <t t-if="invoice.state == 'posted' and invoice.payment_state in ('paid', 'in_payment')">\n                                <span class="badge rounded-pill text-bg-success"><i class="fa fa-fw fa-check" aria-label="Paid" title="Paid" role="img"/><span class="d-none d-md-inline"> Paid</span></span>\n                            </t>\n                            <t t-if="invoice.state == 'posted' and invoice.payment_state == 'reversed'">\n                                <span class="badge rounded-pill text-bg-success"><i class="fa fa-fw fa-check" aria-label="Reversed" title="Reversed" role="img"/><span class="d-none d-md-inline"> Reversed</span></span>\n                            </t>\n                            <t t-if="invoice.state == 'cancel'">\n                                <span class="badge rounded-pill text-bg-warning"><i class="fa fa-fw fa-remove" aria-label="Cancelled" title="Cancelled" role="img"/><span class="d-none d-md-inline"> Cancelled</span></span>\n                            </t>\n                        </td>\n                        <td class="text-end"><span t-esc="-invoice.amount_residual if invoice.move_type == 'out_refund' else invoice.amount_residual" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/></td>\n                    </tr>\n                </t>\n            </tbody>\n        </t>\n      </t>\n    </t>	f	t	2023-11-01 09:26:09.464869	2024-05-06 12:22:55.631576	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
711	16	511	1	1	Invoice Portal Template	\N	account.portal_invoice_page	qweb	account/views/account_portal_templates.xml	\N	primary	{"en_US": "<data name=\\"Invoice Portal Template\\" inherit_id=\\"portal.portal_sidebar\\" primary=\\"True\\">\\n        <xpath expr=\\"//div[hasclass('o_portal_sidebar')]\\" position=\\"inside\\">\\n            <t t-set=\\"o_portal_fullwidth_alert\\" groups=\\"sales_team.group_sale_salesman,account.group_account_invoice,account.group_account_readonly\\">\\n                <t t-call=\\"portal.portal_back_in_edit_mode\\">\\n                    <t t-set=\\"backend_url\\" t-value=\\"'/web#model=%s&amp;id=%s&amp;action=%s&amp;view_type=form' % (invoice._name, invoice.id, invoice.env.ref('account.action_move_out_invoice_type').id)\\"/>\\n                </t>\\n            </t>\\n\\n            <div class=\\"row mt16 o_portal_invoice_sidebar\\">\\n                <!-- Sidebar -->\\n                <t t-call=\\"portal.portal_record_sidebar\\">\\n                    <t t-set=\\"classes\\" t-value=\\"'col-lg-auto d-print-none'\\"/>\\n                    <t t-set=\\"title\\">\\n                        <h2 class=\\"mb-0\\">\\n                            <b t-if=\\"invoice.amount_residual &gt; 0\\" t-field=\\"invoice.amount_residual\\"/>\\n                            <b t-else=\\"1\\" t-field=\\"invoice.amount_total\\"/>\\n                        </h2>\\n                        <div class=\\"small\\" t-if=\\"invoice.payment_state not in ('paid', 'in_payment') and invoice.move_type == 'out_invoice'\\"><i class=\\"fa fa-clock-o\\"/><span class=\\"o_portal_sidebar_timeago ml4\\" t-att-datetime=\\"invoice.invoice_date_due\\"/></div>\\n                    </t>\\n\\n                    <t t-set=\\"entries\\">\\n                        <ul class=\\"list-group list-group-flush flex-wrap flex-row flex-lg-column\\">\\n                            <li class=\\"list-group-item flex-grow-1\\">\\n                                <div class=\\"o_download_pdf btn-toolbar flex-sm-nowrap\\">\\n                                    <div class=\\"btn-group  flex-grow-1 me-1 mb-1\\">\\n                                        <a class=\\"btn btn-secondary btn-block o_download_btn\\" t-att-href=\\"invoice.get_portal_url(report_type='pdf', download=True)\\" title=\\"Download\\"><i class=\\"fa fa-download\\"/> Download</a>\\n                                    </div>\\n                                    <div class=\\"btn-group flex-grow-1 mb-1\\">\\n                                        <a class=\\"btn btn-secondary btn-block o_print_btn o_portal_invoice_print\\" t-att-href=\\"invoice.get_portal_url(report_type='pdf')\\" id=\\"print_invoice_report\\" title=\\"Print\\" target=\\"_blank\\"><i class=\\"fa fa-print\\"/> Print</a>\\n                                    </div>\\n                                </div>\\n                            </li>\\n                            <li t-if=\\"invoice.invoice_user_id\\" class=\\"list-group-item flex-grow-1\\">\\n                                <div class=\\"small mb-1\\"><strong class=\\"text-muted\\">\\n                                    <t t-if=\\"invoice.move_type == 'out_invoice'\\">\\n                                        Salesperson\\n                                    </t>\\n                                    <t t-if=\\"invoice.move_type == 'in_invoice'\\">\\n                                        Purchase Representative\\n                                    </t>\\n                                </strong></div>\\n                                <div class=\\"row\\">\\n                                    <div class=\\"col flex-grow-0 pe-2\\">\\n                                        <img class=\\"rounded-circle mt-1 o_portal_contact_img\\" t-att-src=\\"image_data_uri(invoice.invoice_user_id.avatar_1024)\\" alt=\\"Contact\\"/>\\n                                    </div>\\n                                    <div class=\\"col ps-0\\">\\n                                        <span t-field=\\"invoice.invoice_user_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True}\\"/>\\n                                        <a href=\\"#discussion\\" class=\\"small\\"><i class=\\"fa fa-fw fa-comments\\"/><b>Send message</b></a>\\n                                    </div>\\n                                </div>\\n                            </li>\\n                        </ul>\\n                    </t>\\n                </t>\\n\\n                <!-- Page Content -->\\n                <div id=\\"invoice_content\\" class=\\"col-12 col-lg\\">\\n                    <t t-if=\\"error or warning\\" t-call=\\"account.portal_invoice_error\\"/>\\n                    <t t-if=\\"success and (not error and not warning)\\" t-call=\\"account.portal_invoice_success\\"/>\\n\\n                    <div class=\\"o_portal_html_view shadow p-3\\">\\n                        <div class=\\"o_portal_html_loader text-center\\">\\n                            <i class=\\"fa fa-circle-o-notch fa-spin fa-2x fa-fw text-black-50\\"/>\\n                        </div>\\n                        <iframe id=\\"invoice_html\\" class=\\"mt8 mb8\\" width=\\"100%\\" height=\\"100%\\" frameborder=\\"0\\" scrolling=\\"no\\" t-att-src=\\"invoice.get_portal_url(report_type='html')\\"/>\\n                    </div>\\n                    <!-- chatter -->\\n                    <div id=\\"invoice_communication\\" class=\\"mt-4\\">\\n                        <h2>History</h2>\\n                        <t t-call=\\"portal.message_thread\\"/>\\n                    </div>\\n                </div>\\n            </div>\\n        </xpath>\\n    <xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">account.portal_invoice_page</attribute></xpath></data>"}	<data name="Invoice Portal Template" inherit_id="portal.portal_sidebar" primary="True">\n        <xpath expr="//div[hasclass('o_portal_sidebar')]" position="inside">\n            <t t-set="o_portal_fullwidth_alert" groups="sales_team.group_sale_salesman,account.group_account_invoice,account.group_account_readonly">\n                <t t-call="portal.portal_back_in_edit_mode">\n                    <t t-set="backend_url" t-value="'/web#model=%s&amp;id=%s&amp;action=%s&amp;view_type=form' % (invoice._name, invoice.id, invoice.env.ref('account.action_move_out_invoice_type').id)"/>\n                </t>\n            </t>\n\n            <div class="row mt16 o_portal_invoice_sidebar">\n                <!-- Sidebar -->\n                <t t-call="portal.portal_record_sidebar">\n                    <t t-set="classes" t-value="'col-lg-auto d-print-none'"/>\n                    <t t-set="title">\n                        <h2 class="mb-0">\n                            <b t-if="invoice.amount_residual &gt; 0" t-field="invoice.amount_residual"/>\n                            <b t-else="1" t-field="invoice.amount_total"/>\n                        </h2>\n                        <div class="small" t-if="invoice.payment_state not in ('paid', 'in_payment') and invoice.move_type == 'out_invoice'"><i class="fa fa-clock-o"/><span class="o_portal_sidebar_timeago ml4" t-att-datetime="invoice.invoice_date_due"/></div>\n                    </t>\n\n                    <t t-set="entries">\n                        <ul class="list-group list-group-flush flex-wrap flex-row flex-lg-column">\n                            <li class="list-group-item flex-grow-1">\n                                <div class="o_download_pdf btn-toolbar flex-sm-nowrap">\n                                    <div class="btn-group  flex-grow-1 me-1 mb-1">\n                                        <a class="btn btn-secondary btn-block o_download_btn" t-att-href="invoice.get_portal_url(report_type='pdf', download=True)" title="Download"><i class="fa fa-download"/> Download</a>\n                                    </div>\n                                    <div class="btn-group flex-grow-1 mb-1">\n                                        <a class="btn btn-secondary btn-block o_print_btn o_portal_invoice_print" t-att-href="invoice.get_portal_url(report_type='pdf')" id="print_invoice_report" title="Print" target="_blank"><i class="fa fa-print"/> Print</a>\n                                    </div>\n                                </div>\n                            </li>\n                            <li t-if="invoice.invoice_user_id" class="list-group-item flex-grow-1">\n                                <div class="small mb-1"><strong class="text-muted">\n                                    <t t-if="invoice.move_type == 'out_invoice'">\n                                        Salesperson\n                                    </t>\n                                    <t t-if="invoice.move_type == 'in_invoice'">\n                                        Purchase Representative\n                                    </t>\n                                </strong></div>\n                                <div class="row">\n                                    <div class="col flex-grow-0 pe-2">\n                                        <img class="rounded-circle mt-1 o_portal_contact_img" t-att-src="image_data_uri(invoice.invoice_user_id.avatar_1024)" alt="Contact"/>\n                                    </div>\n                                    <div class="col ps-0">\n                                        <span t-field="invoice.invoice_user_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True}"/>\n                                        <a href="#discussion" class="small"><i class="fa fa-fw fa-comments"/><b>Send message</b></a>\n                                    </div>\n                                </div>\n                            </li>\n                        </ul>\n                    </t>\n                </t>\n\n                <!-- Page Content -->\n                <div id="invoice_content" class="col-12 col-lg">\n                    <t t-if="error or warning" t-call="account.portal_invoice_error"/>\n                    <t t-if="success and (not error and not warning)" t-call="account.portal_invoice_success"/>\n\n                    <div class="o_portal_html_view shadow p-3">\n                        <div class="o_portal_html_loader text-center">\n                            <i class="fa fa-circle-o-notch fa-spin fa-2x fa-fw text-black-50"/>\n                        </div>\n                        <iframe id="invoice_html" class="mt8 mb8" width="100%" height="100%" frameborder="0" scrolling="no" t-att-src="invoice.get_portal_url(report_type='html')"/>\n                    </div>\n                    <!-- chatter -->\n                    <div id="invoice_communication" class="mt-4">\n                        <h2>History</h2>\n                        <t t-call="portal.message_thread"/>\n                    </div>\n                </div>\n            </div>\n        </xpath>\n    <xpath expr="." position="attributes"><attribute name="t-name">account.portal_invoice_page</attribute></xpath></data>	f	t	2023-11-01 09:26:09.464869	2024-05-06 12:22:55.631576	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
