             </div>\\n                                </div>\\n                                <div class=\\"col-5 offset-1\\" name=\\"div_incoming_address\\">\\n                                    <t t-set=\\"show_partner\\" t-value=\\"False\\"/>\\n                                    <div t-if=\\"o.picking_type_id.code=='incoming' and o.partner_id\\">\\n                                        <span><strong>Vendor Address:</strong></span>\\n                                        <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                                    </div>\\n                                    <div t-if=\\"o.picking_type_id.code=='internal' and o.partner_id\\">\\n                                        <span><strong>Warehouse Address:</strong></span>\\n                                        <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                                    </div>\\n                                    <div t-if=\\"o.picking_type_id.code=='outgoing' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id\\">\\n                                        <span><strong>Customer Address:</strong></span>\\n                                        <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                                    </div>\\n                                    <div t-if=\\"show_partner\\" name=\\"partner_header\\">\\n                                        <div t-field=\\"o.partner_id.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <br/>\\n                            <h1 t-field=\\"o.name\\" class=\\"mt0\\"/>\\n                            <div class=\\"row mt48 mb32\\">\\n                                <div t-if=\\"o.origin\\" class=\\"col-auto\\" name=\\"div_origin\\">\\n                                    <strong>Order:</strong>\\n                                    <p t-field=\\"o.origin\\"/>\\n                                </div>\\n                                <div class=\\"col-auto\\" name=\\"div_state\\">\\n                                    <strong>Status:</strong>\\n                                    <p t-field=\\"o.state\\"/>\\n                                </div>\\n                                <div class=\\"col-auto\\" name=\\"div_sched_date\\">\\n                                    <strong>Scheduled Date:</strong>\\n                                    <p t-field=\\"o.scheduled_date\\"/>\\n                                </div>\\n                            </div>\\n                            <table class=\\"table table-sm\\" t-if=\\"o.move_line_ids and o.move_ids_without_package\\">\\n                                <t t-set=\\"has_barcode\\" t-value=\\"any(move_line.product_id and move_line.product_id.sudo().barcode or move_line.package_id for move_line in o.move_line_ids)\\"/>\\n                                <t t-set=\\"has_serial_number\\" t-value=\\"any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)\\" groups=\\"stock.group_production_lot\\"/>\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_product\\">\\n                                            <strong>Product</strong>\\n                                        </th>\\n                                        <th>\\n                                            <strong>Quantity</strong>\\n                                        </th>\\n                                        <th name=\\"th_from\\" t-if=\\"o.picking_type_id.code != 'incoming'\\" align=\\"left\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <strong>From</strong>\\n                                        </th>\\n                                        <th name=\\"th_to\\" t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <strong>To</strong>\\n                                        </th>\\n                                        <th name=\\"th_serial_number\\" class=\\"text-center\\" t-if=\\"has_serial_number\\">\\n                                           <strong>Lot/Serial Number</strong>\\n                                        </th>\\n                                        <th name=\\"th_barcode\\" class=\\"text-center\\" t-if=\\"has_barcode\\">\\n                                            <strong>Product Barcode</strong>\\n                                        </th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <!-- In case you come across duplicated lines, ask NIM or LAP -->\\n                                    <t t-foreach=\\"o.move_line_ids_without_package\\" t-as=\\"ml\\">\\n                                        <tr>\\n                                            <td>\\n                                                <span t-field=\\"ml.product_id.display_name\\"/><br/>\\n                                                <span t-field=\\"ml.product_id.description_picking\\"/>\\n                                            </td>\\n                                            <td>\\n                                                <span t-if=\\"o.state != 'done'\\" t-field=\\"ml.reserved_uom_qty\\"/>\\n                                                <span t-if=\\"o.state == 'done'\\" t-field=\\"ml.qty_done\\"/>\\n                                                <span t-field=\\"ml.product_uom_id\\" groups=\\"uom.group_uom\\"/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-esc=\\"ml.location_id.display_name\\"/>\\n                                                    <t t-if=\\"ml.package_id\\">\\n                                                        <span t-field=\\"ml.package_id\\"/>\\n                                                    </t>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <div>\\n                                                    <span t-field=\\"ml.location_dest_id\\"/>\\n                                                    <t t-if=\\"ml.result_package_id\\">\\n                                                        <span t-field=\\"ml.result_package_id\\"/>\\n                                                    </t>\\n                                                </div>\\n                                            </td>\\n                                            <td class=\\" text-center h6\\" t-if=\\"has_serial_number\\">\\n                                                <div t-if=\\"has_serial_number and (ml.lot_id or ml.lot_name)\\" t-esc=\\"ml.lot_id.name or ml.lot_name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}\\"/>\\n                                            </td>\\n                                            <td class=\\"text-center\\" t-if=\\"has_barcode\\">\\n                                                <t t-if=\\"product_barcode != ml.product_id.barcode\\">\\n                                                    <span t-if=\\"ml.product_id and ml.product_id.barcode\\">\\n                                                        <div t-field=\\"ml.product_id.barcode\\" t-options=\\"{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}\\"/>\\n                                                    </span>\\n                                                    <t t-set=\\"product_barcode\\" t-value=\\"ml.product_id.barcode\\"/>\\n                                                </t>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                  </tbody>\\n                            </table>\\n                            <table class=\\"table table-sm\\" t-if=\\"o.package_level_ids and o.picking_type_entire_packs and o.state in ['assigned', 'done']\\">\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_package\\">Package</th>\\n                                        <th name=\\"th_pko_from\\" t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">From</th>\\n                                        <th name=\\"th_pki_from\\" t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">To</th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <tr t-foreach=\\"o.package_level_ids.sorted(key=lambda p: p.package_id.name)\\" t-as=\\"package\\">\\n                                        <t t-set=\\"package\\" t-value=\\"package.with_context(picking_id=o.id)\\"/>\\n                                        <td name=\\"td_pk_barcode\\">\\n                                            <div t-field=\\"package.package_id.name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}\\"/><br/>\\n                                        </td>\\n                                        <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <span t-field=\\"package.location_id\\"/>\\n                                        </td>\\n                                        <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <span t-field=\\"package.location_dest_id\\"/>\\n                                        </td>\\n                                    </tr>\\n                                </tbody>\\n                            </table>\\n                            <t t-set=\\"no_reserved_product\\" t-value=\\"o.move_ids.filtered(lambda x: x.product_uom_qty != x.reserved_availability and x.move_line_ids and x.state!='done')\\"/>\\n                            <p t-if=\\"o.state in ['draft', 'waiting', 'confirmed'] or no_reserved_product\\"><i class=\\"fa fa-exclamation-triangle\\"/>\\n                                All products could not be reserved. Click on the \\"Check Availability\\" button to try to reserve products.\\n                            </p>\\n                            <p t-field=\\"o.note\\"/>\\n                        </div>\\n                    </t>\\n                </t>\\n            </t>\\n        </t>"}	<t t-name="stock.report_picking">\n            <t t-call="web.html_container">\n                <t t-foreach="docs" t-as="o">\n                    <t t-call="web.external_layout">\n                        <div class="page">\n                            <div class="row justify-content-end mb16">\n                                <div class="col-4" name="right_box">\n                                    <div t-field="o.name" t-options="{'widget': 'barcode', 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;'}"/>\n                                </div>\n                            </div>\n                            <div class="row">\n                                <div class="col-6" name="div_outgoing_address">\n                                    <div t-if="o.should_print_delivery_address()">\n                                        <span><strong>Delivery Address:</strong></span>\n                                        <div t-field="o.move_ids[0].partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                                    </div>\n                                    <div t-elif="o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id">\n                                        <span><strong>Warehouse Address:</strong></span>\n                                        <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                                    </div>\n                                </div>\n                                <div class="col-5 offset-1" name="div_incoming_address">\n                                    <t t-set="show_partner" t-value="False"/>\n                                    <div t-if="o.picking_type_id.code=='incoming' and o.partner_id">\n                                        <span><strong>Vendor Address:</strong></span>\n                                        <t t-set="show_partner" t-value="True"/>\n                                    </div>\n                                    <div t-if="o.picking_type_id.code=='internal' and o.partner_id">\n                                        <span><strong>Warehouse Address:</strong></span>\n                                        <t t-set="show_partner" t-value="True"/>\n                                    </div>\n                                    <div t-if="o.picking_type_id.code=='outgoing' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id">\n                                        <span><strong>Customer Address:</strong></span>\n                                        <t t-set="show_partner" t-value="True"/>\n                                    </div>\n                                    <div t-if="show_partner" name="partner_header">\n                                        <div t-field="o.partner_id.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                                    </div>\n                                </div>\n                            </div>\n                            <br/>\n                            <h1 t-field="o.name" class="mt0"/>\n                            <div class="row mt48 mb32">\n                                <div t-if="o.origin" class="col-auto" name="div_origin">\n                                    <strong>Order:</strong>\n                                    <p t-field="o.origin"/>\n                                </div>\n                                <div class="col-auto" name="div_state">\n                                    <strong>Status:</strong>\n                                    <p t-field="o.state"/>\n                                </div>\n                                <div class="col-auto" name="div_sched_date">\n                                    <strong>Scheduled Date:</strong>\n                                    <p t-field="o.scheduled_date"/>\n                                </div>\n                            </div>\n                            <table class="table table-sm" t-if="o.move_line_ids and o.move_ids_without_package">\n                                <t t-set="has_barcode" t-value="any(move_line.product_id and move_line.product_id.sudo().barcode or move_line.package_id for move_line in o.move_line_ids)"/>\n                                <t t-set="has_serial_number" t-value="any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)" groups="stock.group_production_lot"/>\n                                <thead>\n                                    <tr>\n                                        <th name="th_product">\n                                            <strong>Product</strong>\n                                        </th>\n                                        <th>\n                                            <strong>Quantity</strong>\n                                        </th>\n                                        <th name="th_from" t-if="o.picking_type_id.code != 'incoming'" align="left" groups="stock.group_stock_multi_locations">\n                                            <strong>From</strong>\n                                        </th>\n                                        <th name="th_to" t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                            <strong>To</strong>\n                                        </th>\n                                        <th name="th_serial_number" class="text-center" t-if="has_serial_number">\n                                           <strong>Lot/Serial Number</strong>\n                                        </th>\n                                        <th name="th_barcode" class="text-center" t-if="has_barcode">\n                                            <strong>Product Barcode</strong>\n                                        </th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <!-- In case you come across duplicated lines, ask NIM or LAP -->\n                                    <t t-foreach="o.move_line_ids_without_package" t-as="ml">\n                                        <tr>\n                                            <td>\n                                                <span t-field="ml.product_id.display_name"/><br/>\n                                                <span t-field="ml.product_id.description_picking"/>\n                                            </td>\n                                            <td>\n                                                <span t-if="o.state != 'done'" t-field="ml.reserved_uom_qty"/>\n                                                <span t-if="o.state == 'done'" t-field="ml.qty_done"/>\n                                                <span t-field="ml.product_uom_id" groups="uom.group_uom"/>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">\n                                                <span t-esc="ml.location_id.display_name"/>\n                                                    <t t-if="ml.package_id">\n                                                        <span t-field="ml.package_id"/>\n                                                    </t>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                                <div>\n                                                    <span t-field="ml.location_dest_id"/>\n                                                    <t t-if="ml.result_package_id">\n                                                        <span t-field="ml.result_package_id"/>\n                                                    </t>\n                                                </div>\n                                            </td>\n                                            <td class=" text-center h6" t-if="has_serial_number">\n                                                <div t-if="has_serial_number and (ml.lot_id or ml.lot_name)" t-esc="ml.lot_id.name or ml.lot_name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}"/>\n                                            </td>\n                                            <td class="text-center" t-if="has_barcode">\n                                                <t t-if="product_barcode != ml.product_id.barcode">\n                                                    <span t-if="ml.product_id and ml.product_id.barcode">\n                                                        <div t-field="ml.product_id.barcode" t-options="{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}"/>\n                                                    </span>\n                                                    <t t-set="product_barcode" t-value="ml.product_id.barcode"/>\n                                                </t>\n                                            </td>\n                                        </tr>\n                                    </t>\n                                  </tbody>\n                            </table>\n                            <table class="table table-sm" t-if="o.package_level_ids and o.picking_type_entire_packs and o.state in ['assigned', 'done']">\n                                <thead>\n                                    <tr>\n                                        <th name="th_package">Package</th>\n                                        <th name="th_pko_from" t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">From</th>\n                                        <th name="th_pki_from" t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">To</th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <tr t-foreach="o.package_level_ids.sorted(key=lambda p: p.package_id.name)" t-as="package">\n                                        <t t-set="package" t-value="package.with_context(picking_id=o.id)"/>\n                                        <td name="td_pk_barcode">\n                                            <div t-field="package.package_id.name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}"/><br/>\n                                        </td>\n                                        <td t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">\n                                            <span t-field="package.location_id"/>\n                                        </td>\n                                        <td t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                            <span t-field="package.location_dest_id"/>\n                                        </td>\n                                    </tr>\n                                </tbody>\n                            </table>\n                            <t t-set="no_reserved_product" t-value="o.move_ids.filtered(lambda x: x.product_uom_qty != x.reserved_availability and x.move_line_ids and x.state!='done')"/>\n                            <p t-if="o.state in ['draft', 'waiting', 'confirmed'] or no_reserved_product"><i class="fa fa-exclamation-triangle"/>\n                                All products could not be reserved. Click on the "Check Availability" button to try to reserve products.\n                            </p>\n              