1353	16	\N	1	1	Submenu	\N	website.submenu	qweb	website/views/website_templates.xml	\N	primary	{"en_US": "<t name=\\"Submenu\\" t-name=\\"website.submenu\\">\\n    <t t-set=\\"show_dropdown\\" t-value=\\"(submenu.is_mega_menu and submenu.is_visible) or submenu.child_id.filtered(lambda menu: menu.is_visible)\\"/>\\n    <li t-if=\\"submenu.is_visible and not (submenu.child_id or submenu.is_mega_menu)\\" t-attf-class=\\"#{item_class or ''}\\" role=\\"presentation\\">\\n        <a t-att-href=\\"submenu.clean_url()\\" t-attf-class=\\"#{link_class or ''} #{'active' if submenu.clean_url() and unslug_url(request.httprequest.path) == unslug_url(submenu.clean_url()) else ''}\\" role=\\"menuitem\\" t-ignore=\\"true\\" t-att-target=\\"'_blank' if submenu.new_window else None\\">\\n            <span t-field=\\"submenu.name\\"/>\\n        </a>\\n    </li>\\n    <li t-elif=\\"show_dropdown\\" t-attf-class=\\"#{item_class or ''} dropdown #{         (submenu.clean_url() and submenu.clean_url() != '/' and any(request.httprequest.path == child.url for child in submenu.child_id if child.url) or          (submenu.clean_url() and request.httprequest.path == submenu.clean_url())) and 'active'         } #{submenu.is_mega_menu and 'position-static'}\\">\\n        <a t-attf-class=\\"#{link_class or ''} dropdown-toggle #{submenu.is_mega_menu and 'o_mega_menu_toggle'}\\" data-bs-toggle=\\"dropdown\\" href=\\"#\\">\\n            <span t-field=\\"submenu.name\\"/>\\n        </a>\\n        <div t-if=\\"submenu.is_mega_menu\\" t-attf-class=\\"dropdown-menu o_mega_menu #{submenu.mega_menu_classes}\\" data-name=\\"Mega Menu\\" t-field=\\"submenu.mega_menu_content\\"/>\\n        <ul t-else=\\"\\" class=\\"dropdown-menu\\" role=\\"menu\\">\\n            <t t-foreach=\\"submenu.child_id\\" t-as=\\"submenu\\">\\n                <t t-call=\\"website.submenu\\">\\n                    <t t-set=\\"item_class\\" t-value=\\"None\\"/>\\n                    <t t-set=\\"link_class\\" t-valuef=\\"dropdown-item\\"/>\\n                </t>\\n            </t>\\n        </ul>\\n    </li>\\n</t>"}	<t name="Submenu" t-name="website.submenu">\n    <t t-set="show_dropdown" t-value="(submenu.is_mega_menu and submenu.is_visible) or submenu.child_id.filtered(lambda menu: menu.is_visible)"/>\n    <li t-if="submenu.is_visible and not (submenu.child_id or submenu.is_mega_menu)" t-attf-class="#{item_class or ''}" role="presentation">\n        <a t-att-href="submenu.clean_url()" t-attf-class="#{link_class or ''} #{'active' if submenu.clean_url() and unslug_url(request.httprequest.path) == unslug_url(submenu.clean_url()) else ''}" role="menuitem" t-ignore="true" t-att-target="'_blank' if submenu.new_window else None">\n            <span t-field="submenu.name"/>\n        </a>\n    </li>\n    <li t-elif="show_dropdown" t-attf-class="#{item_class or ''} dropdown #{         (submenu.clean_url() and submenu.clean_url() != '/' and any(request.httprequest.path == child.url for child in submenu.child_id if child.url) or          (submenu.clean_url() and request.httprequest.path == submenu.clean_url())) and 'active'         } #{submenu.is_mega_menu and 'position-static'}">\n        <a t-attf-class="#{link_class or ''} dropdown-toggle #{submenu.is_mega_menu and 'o_mega_menu_toggle'}" data-bs-toggle="dropdown" href="#">\n            <span t-field="submenu.name"/>\n        </a>\n        <div t-if="submenu.is_mega_menu" t-attf-class="dropdown-menu o_mega_menu #{submenu.mega_menu_classes}" data-name="Mega Menu" t-field="submenu.mega_menu_content"/>\n        <ul t-else="" class="dropdown-menu" role="menu">\n            <t t-foreach="submenu.child_id" t-as="submenu">\n                <t t-call="website.submenu">\n                    <t t-set="item_class" t-value="None"/>\n                    <t t-set="link_class" t-valuef="dropdown-item"/>\n                </t>\n            </t>\n        </ul>\n    </li>\n</t>	f	t	2023-11-03 05:56:04.332428	2024-05-06 12:23:05.521885	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
1354	16	487	1	1	Main layout	\N	website.layout	qweb	website/views/website_templates.xml	\N	extension	{"en_US": "<data name=\\"Main layout\\" inherit_id=\\"portal.frontend_layout\\">\\n    <xpath expr=\\"//html\\" position=\\"before\\">\\n        <!--\\n            /!\\\\ Notice that some `html_data` keys were moved between the `t-if`\\n            version and the normal `t-set` below as a bug fix in stable 16.0.\\n            Existing users before that fix may experience issues with:\\n            - The publish button as a restricted editor\\n            - The \\"edit-in-backend\\" button as a restricted editor\\n            - The \\"Products\\" snippet as a visitor\\n            - ...\\n            None should be critical though (you just not have access to some\\n            (important) features anymore). An update of the website app or\\n            patching this view directly to have the following lines setting\\n            `html_data` should solve the issue.\\n\\n            TODO remove this comment in master and also avoid the t-set outside\\n            of the if (kept here to be a bit more stable).\\n        -->\\n        <t t-set=\\"editable_in_backend\\" t-value=\\"edit_in_backend or ('website_published' in main_object.fields_get() and main_object._name != 'website.page')\\"/>\\n        <t t-set=\\"html_data\\" t-value=\\"{             'lang': lang and lang.replace('_', '-'),             'data-website-id': website.id if website else None,             'data-edit_translations': '1' if edit_translations else None,             'data-main-object': repr(main_object) if main_object else None,             'data-seo-object': repr(seo_object) if seo_object else None,         }\\"/>\\n        <!-- The `and '1' or '0'` in `data-can-optimize-seo` property is there\\n        only for stable compliance as if omitted, `False` will not display the\\n        property in the DOM (it's how `t-att` works), meaning we won't be able\\n        to differentiate old database without `-u` and database with the fix.\\n        TODO: Remove this part of the condition in master.\\n        -->\\n        <t t-if=\\"not request.env.user._is_public()\\" t-set=\\"nothing\\" t-value=\\"html_data.update({             'data-is-published': 'website_published' in main_object.fields_get() and main_object.website_published,             'data-can-optimize-seo': 'website_meta_description' in main_object.fields_get() and '1' or '0',             'data-can-publish': 'can_publish' in main_object.fields_get() and main_object.can_publish,             'data-editable-in-backend': editable_in_backend,         })\\"/>\\n        <!-- TODO investigate: data-oe-company-name seems like dead code -->\\n        <t t-if=\\"editable or translatable\\" t-set=\\"nothing\\" t-value=\\"html_data.update({             'data-editable': '1' if editable else None,             'data-translatable': '1' if translatable else None,             'data-view-xmlid': xmlid,             'data-viewid': viewid,             'data-oe-company-name': res_company.name,         })\\"/>\\n    </xpath>\\n\\n    <xpath expr=\\"//head\\" position=\\"attributes\\">\\n        <!--\\n        Cache the <head> of the website.layout:\\n        - For each individual website.page record (their css/js might be the\\n          same but their title will not for example). Arguably we could do this\\n          for any record (not only website.page) but this t-cache was originally\\n          added to replace the website.page own cache system. For other records,\\n          it could probably depend on each individual access right.\\n        - Only for non-designers (especially visitors) (hence the \\"editable or\\n          translatable\\" check).\\n        - Only if not in any debug mode (we want any correct value of debug mode\\n          to correctly appear in the `odoo` object + assets may depend on this\\n          (e.g. debug=assets or debug=tests)).\\n        -->\\n        <attribute name=\\"t-cache\\">main_object if main_object and main_object._name == 'website.page' and not request.session.debug and not editable and not translatable else None</attribute>\\n    </xpath>\\n    <xpath expr=\\"//head/*[1]\\" position=\\"before\\">\\n        <t t-if=\\"not title\\">\\n            <t t-if=\\"not additional_title and main_object and 'name' in main_object\\">\\n                <t t-set=\\"additional_title\\" t-value=\\"main_object.name\\"/>\\n            </t>\\n            <t t-set=\\"default_title\\" t-translation=\\"off\\"> <t t-if=\\"additional_title\\"><t t-out=\\"additional_title\\"/> | </t><t t-out=\\"(website or res_company).name\\"/> </t>\\n            <t t-set=\\"seo_object\\" t-value=\\"seo_object or main_object\\"/>\\n            <t t-if=\\"seo_object and 'website_meta_title' in seo_object and seo_object.website_meta_title\\">\\n                <t t-set=\\"title\\" t-value=\\"seo_object.website_meta_title\\"/>\\n            </t>\\n            <t t-else=\\"\\">\\n                <t t-set=\\"title\\" t-value=\\"default_title\\"/>\\n            </t>\\n        </t>\\n        <t t-set=\\"x_icon\\" t-value=\\"website.image_url(website, 'favicon')\\"/>\\n    </xpath>\\n    <xpath expr=\\"//head/meta[last()]\\" position=\\"after\\">\\n        <meta name=\\"generator\\" content=\\"Odoo\\"/>\\n        <t t-set=\\"website_meta\\" t-value=\\"seo_object and seo_object.get_website_meta() or {}\\"/>\\n        <meta name=\\"default_title\\" t-att-content=\\"default_title\\" groups=\\"website.group_website_designer\\"/>\\n        <meta t-if=\\"(main_object and 'website_indexed' in main_object         and not main_object.website_indexed) or (website.domain and not website._is_indexable_url(request.httprequest.url_root))\\" name=\\"robots\\" content=\\"noindex\\"/>\\n        <t t-set=\\"seo_object\\" t-value=\\"seo_object or main_object\\"/>\\n        <t t-set=\\"meta_description\\" t-value=\\"seo_object and 'website_meta_description' in seo_object             and seo_object.website_meta_description or website_meta_description or website_meta.get('meta_description', '')\\"/>\\n        <t t-set=\\"meta_keywords\\" t-value=\\"seo_object and 'website_meta_keywords' in seo_object             and seo_object.website_meta_keywords or website_meta_keywords\\"/>\\n        <meta t-if=\\"meta_description or editable\\" name=\\"description\\" t-att-content=\\"meta_description\\"/>\\n        <meta t-if=\\"meta_keywords or editable\\" name=\\"keywords\\" t-att-content=\\"meta_keywords\\"/>\\n        <t t-if=\\"seo_object\\">\\n        <meta name=\\"default_description\\" t-att-content=\\"website_meta_description or website_meta.get('meta_description')\\" groups=\\"website.group_website_designer\\"/>\\n            <!-- OpenGraph tags for Facebook sharing -->\\n            <t t-set=\\"opengraph_meta\\" t-value=\\"website_meta.get('opengraph_meta')\\"/>\\n            <t t-if=\\"opengraph_meta\\">\\n                <t t-foreach=\\"opengraph_meta\\" t-as=\\"property\\">\\n                    <t t-if=\\"isinstance(opengraph_meta[property], list)\\">\\n                        <t t-foreach=\\"opengraph_meta[property]\\" t-as=\\"meta_content\\">\\n        <meta t-att-property=\\"property\\" t-att-content=\\"meta_content\\"/>\\n                        </t>\\n                    </t>\\n                    <t t-else=\\"\\">\\n        <meta t-att-property=\\"property\\" t-att-content=\\"opengraph_meta[property]\\"/>\\n                    </t>\\n                </t>\\n            </t>\\n            <!-- Twitter tags for sharing -->\\n            <t t-set=\\"twitter_meta\\" t-value=\\"website_meta.get('twitter_meta')\\"/>\\n            <t t-if=\\"opengraph_meta\\">\\n                <t t-foreach=\\"twitter_meta\\" t-as=\\"t_meta\\">\\n        <meta t-att-name=\\"t_meta\\" t-att-content=\\"twitter_meta[t_meta]\\"/>\\n                </t>\\n            </t>\\n        </t>\\n        <!-- `alternate`/`canonical` mainly useful to crawlers/bots/SEO tools, which test the website as public user -->\\n        <t t-if=\\"request and request.is_frontend_multilang and website and website.is_public_user()\\">\\n            <t t-set=\\"alternate_languages\\" t-value=\\"website._get_alternate_languages(canonical_params=canonical_params)\\"/>\\n            <t t-foreach=\\"alternate_languages\\" t-as=\\"lg\\">\\n        <link rel=\\"alternate\\" t-att-hreflang=\\"lg['hreflang']\\" t-att-href=\\"lg['href']\\"/>\\n            </t>\\n        </t>\\n        <link t-if=\\"request and website and website.is_public_user()\\" rel=\\"canonical\\" t-att-href=\\"website._get_canonical_url(canonical_params=canonical_params)\\"/>\\n        <!-- TODO: Once we have style in DB, add this preconnect only if a\\n        google font is actually used. Note that if no font is used, the\\n        preconnect is actually not connecting to the google servers. -->\\n        <link rel=\\"preconnect\\" href=\\"https://fonts.gstatic.com/\\" crossorigin=\\"\\"/>\\n    </xpath>\\n\\n    <xpath expr=\\"//header\\" position=\\"attributes\\">\\n        <attribute name=\\"data-name\\">Header</attribute>\\n    </xpath>\\n\\n    <xpath expr=\\"//header/t[@t-cache]\\" position=\\"attributes\\">\\n        <!-- website.is_public_user() is needed for menus having a page with\\n        restricted visibility (only shown to logged in user): public users and\\n        logged in users can't share the menu cache. -->\\n        <attribute name=\\"t-cache\\">xmlid,website,website.is_public_user()</attribute>\\n    </xpath>\\n\\n    <xpath expr=\\"//header\\" position=\\"before\\">\\n        <t t-set=\\"cta_btn_text\\" t-value=\\"False\\"/>\\n        <t t-set=\\"cta_btn_href\\">/contactus</t>\\n    </xpath>\\n\\n    <xpath expr=\\"//footer\\" position=\\"attributes\\">\\n        <attribute name=\\"data-name\\">Footer</attribute>\\n        <!-- Background now controlled by css configuration, using color combinations -->\\n        <attribute name=\\"t-attf-class\\" add=\\"o_colored_level o_cc\\" remove=\\"bg-light\\" separator=\\" \\"/>\\n        <!-- Add the main object as a cache key so that the footer_visible page\\n        option is properly reflected across pages. Controllers and other objects\\n        do not have any page option (yet) so they can share the same cache -->\\n        <attribute name=\\"t-cache\\" add=\\"website,main_object._name == 'website.page' and main_object\\"/>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('o_footer_copyright')]\\" position=\\"attributes\\">\\n        <attribute name=\\"data-name\\">Copyright</attribute>\\n        <!-- Background now controlled by css configuration, using color combinations -->\\n        <attribute name=\\"class\\" add=\\"o_colored_level o_cc\\" separator=\\" \\"/>\\n    </xpath>\\n    <xpath expr=\\"//t[@t-call='web.brand_promotion']/..\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" add=\\"o_not_editable\\" separator=\\" \\"/>\\n        <attribute name=\\"t-if\\">not editable</attribute>\\n    </xpath>\\n\\n    <xpath expr=\\"//div[@id='wrapwrap']\\" position=\\"after\\">\\n        <t t-if=\\"website and website.google_analytics_key and request.env['ir.http']._is_allowed_cookie('optional') and not editable\\">\\n            <script id=\\"tracking_code\\" async=\\"1\\" t-attf-src=\\"https://www.googletagmanager.com/gtag/js?id={{ website.google_analytics_key }}\\"/>\\n            <script>\\n                window.dataLayer = window.dataLayer || [];\\n                function gtag(){dataLayer.push(arguments);}\\n                gtag('js', new Date());\\n                gtag('config', '<t t-esc=\\"website.google_analytics_key\\"/>');\\n            </script>\\n        </t>\\n        <t t-if=\\"website and website.plausible_shared_key and not editable\\">\\n            <script id=\\"plausible_script\\" name=\\"plausible\\" defer=\\"defer\\" t-att-data-domain=\\"website.plausible_site\\" t-att-src=\\"website._get_plausible_script_url()\\"/>\\n        </t>\\n    </xpath>\\n\\n    <!-- Page options -->\\n    <xpath expr=\\"//div[@id='wrapwrap']\\" position=\\"before\\">\\n        <t groups=\\"website.group_website_restricted_editor\\">\\n            <t t-foreach=\\"['header_overlay', 'header_color', 'header_visible', 'footer_visible']\\" t-as=\\"optionName\\">\\n                <!-- Firefox autocomplete is too aggressive and works on hidden inputs,\\n                so we need to disable it (https://bugzilla.mozilla.org/show_bug.cgi?id=520561) -->\\n                <input t-if=\\"optionName in main_object\\" type=\\"hidden\\" class=\\"o_page_option_data\\" autocomplete=\\"off\\" t-att-name=\\"optionName\\" t-att-value=\\"main_object[optionName]\\"/>\\n            </t>\\n        </t>\\n        <div groups=\\"base.group_user\\" class=\\"o_frontend_to_backend_nav position-fixed d-none\\">\\n            <svg xmlns=\\"http://www.w3.org/2000/svg\\" class=\\"o_frontend_to_backend_icon position-absolute\\" width=\\"24px\\" height=\\"24px\\" viewBox=\\"-7 -7 24 24\\" preserveAspectRatio=\\"xMinYMin\\">\\n                <path fill=\\"#FFF\\" d=\\"M8 8V1a1 1 0 1 1 2 0v8a1 1 0 0 1-1 1H1a1 1 0 1 1 0-2h7z\\"/>\\n            </svg>\\n            <div class=\\"o_frontend_to_backend_buttons d-flex\\">\\n                <a href=\\"#\\" title=\\"Go to your Odoo Apps\\" class=\\"o_frontend_to_backend_apps_btn fa fa-th d-flex align-items-center justify-content-center text-decoration-none\\" data-bs-toggle=\\"dropdown\\"/>\\n                <div class=\\"dropdown-menu o_frontend_to_backend_apps_menu\\" role=\\"menu\\">\\n                    <a role=\\"menuitem\\" class=\\"dropdown-item\\" t-esc=\\"menu['name']\\" t-as=\\"menu\\" t-foreach=\\"env['ir.ui.menu'].with_context(force_action=True).load_menus_root()['children']\\" t-attf-href=\\"/web#menu_id=#{menu['id']}&amp;action=#{menu['action'] and menu['action'].split(',')[1] or ''}\\"/>\\n                </div>\\n                <a groups=\\"website.group_website_restricted_editor\\" href=\\"#\\" title=\\"Edit this content\\" class=\\"o_frontend_to_backend_edit_btn px-3 d-flex align-items-center justify-content-center text-decoration-none\\">\\n                    <img src=\\"/website/static/description/icon.png\\"/>Editor\\n                </a>\\n            </div>\\n        </div>\\n    </xpath>\\n    <xpath expr=\\"//div[@id='wrapwrap']\\" position=\\"attributes\\">\\n        <attribute name=\\"t-attf-class\\" add=\\"#{'o_header_overlay' if 'header_overlay' in main_object and main_object.header_overlay else ''}\\" separator=\\" \\"/>\\n    </xpath>\\n    <xpath expr=\\"//header\\" position=\\"attributes\\">\\n        <attribute name=\\"t-attf-class\\" add=\\"#{main_object.header_color if 'header_color' in main_object else ''}\\" separator=\\" \\"/>\\n    </xpath>\\n    <xpath expr=\\"//header\\" position=\\"attributes\\">\\n        <attribute name=\\"t-attf-class\\" add=\\"#{'d-none o_snippet_invisible' if 'header_visible' in main_object and not main_object.header_visible else ''}\\" separator=\\" \\"/>\\n    </xpath>\\n    <xpath expr=\\"//footer[@id='bottom']\\" position=\\"attributes\\">\\n        <attribute name=\\"t-attf-class\\" add=\\"#{'d-none o_snippet_invisible' if 'footer_visible' in main_object and not main_object.footer_visible else ''}\\" separator=\\" \\"/>\\n    </xpath>\\n</data>"}	<data name="Main layout" inherit_id="portal.frontend_layout">\n    <xpath expr="//html" position="before">\n        <!--\n            /!\\ Notice that some `html_data` keys were moved between the `t-if`\n            version and the normal `t-set` below as a bug fix in stable 16.0.\n            Existing users before that fix may experience issues with:\n            - The publish button as a restricted editor\n            - The "edit-in-backend" button as a restricted editor\n            - The "Products" snippet as a visitor\n            - ...\n            None should be critical though (you just not have access to some\n            (important) features anymore). An update of the website app or\n            patching this view directly to have the following lines setting\n            `html_data` should solve the issue.\n\n            TODO remove this comment in master and also avoid the t-set outside\n            of the if (kept here to be a bit more stable).\n        -->\n        <t t-set="editable_in_backend" t-value="edit_in_backend or ('website_published' in main_object.fields_get() and main_object._name != 'website.page')"/>\n        <t t-set="html_data" t-value="{             'lang': lang and lang.replace('_', '-'),             'data-website-id': website.id if website else None,             'data-edit_translations': '1' if edit_translations else None,             'data-main-object': repr(main_object) if main_object else None,             'data-seo-object': repr(seo_object) if seo_object else None,         }"/>\n        <!-- The `and '1' or '0'` in `data-can-optimize-seo` property is there\n        only for stable compliance as if omitted, `False` will not display the\n        property in the DOM (it's how `t-att` works), meaning we won't be able\n        to differentiate old database without `-u` and database with the fix.\n        TODO: Remove this part of the condition in master.\n        -->\n        <t t-if="not request.env.user._is_public()" t-set="nothing" t-value="html_data.update({             'data-is-published': 'website_published' in main_object.fields_get() and main_object.website_published,             'data-can-optimize-seo': 'website_meta_description' in main_object.fields_get() and '1' or '0',             'data-can-publish': 'can_publish' in main_object.fields_get() and main_object.can_publish,             'data-editable-in-backend': editable_in_backend,         })"/>\n        <!-- TODO investigate: data-oe-company-name seems like dead code -->\n        <t t-if="editable or translatable" t-set="nothing" t-value="html_data.update({             'data-editable': '1' if editable else None,             'data-translatable': '1' if translatable else None,             'data-view-xmlid': xmlid,             'data-viewid': viewid,             'data-oe-company-name': res_company.name,         })"/>\n    </xpath>\n\n    <xpath expr="//head" position="attributes">\n        <!--\n        Cache the <head> of the website.layout:\n        - For each individual website.page record (their css/js might be the\n          same but their title will not for example). Arguably we could do this\n          for any record (not only website.page) but this t-cache was originally\n          added to replace the website.page own cache system. For other records,\n          it could probably depend on each individual access right.\n        - Only for non-designers (especially visitors) (hence the "editable or\n          translatable" check).\n        - Only if not in any debug mode (we want any correct value of debug mode\n          to correctly appear in the `odoo` object + assets may depend on this\n          (e.g. debug=assets or debug=tests)).\n        -->\n        <attribute name="t-cache">main_object if main_object and main_object._name == 'website.page' and not request.session.debug and not editable and not translatable else None</attribute>\n    </xpath>\n    <xpath expr="//head/*[1]" position="before">\n        <t t-if="not title">\n            <t t-if="not additional_title and main_object and 'name' in main_object">\n                <t t-set="additional_title" t-value="main_object.name"/>\n            </t>\n            <t t-set="default_title" t-translation="off"> <t t-if="additional_title"><t t-out="additional_title"/> | </t><t t-out="(website or res_company).name"/> </t>\n            <t t-set="seo_object" t-value="seo_object or main_object"/>\n            <t t-if="seo_object and 'website_meta_title' in seo_object and seo_object.website_meta_title">\n                <t t-set="title" t-value="seo_object.website_meta_title"/>\n            </t>\n            <t t-else="">\n                <t t-set="title" t-value="default_title"/>\n            </t>\n        </t>\n        <t t-set="x_icon" t-value="website.image_url(website, 'favicon')"/>\n    </xpath>\n    <xpath expr="//head/meta[last()]" position="after">\n        <meta name="generator" content="Odoo"/>\n        <t t-set="website_meta" t-value="seo_object and seo_object.get_website_meta() or {}"/>\n        <meta name="default_title" t-att-content="default_title" groups="website.group_website_designer"/>\n        <meta t-if="(main_object and 'website_indexed' in main_object         and not main_object.website_indexed) or (website.domain and not website._is_indexable_url(request.httprequest.url_root))" name="robots" content="noindex"/>\n        <t t-set="seo_object" t-value="seo_object or main_object"/>\n        <t t-set="meta_description" t-value="seo_object and 'website_meta_description' in seo_object             and seo_object.website_meta_description or website_meta_description or website_meta.get('meta_description', '')"/>\n        <t t-set="meta_keywords" t-value="seo_object and 'website_meta_keywords' in seo_object             and seo_object.website_meta_keywords or website_meta_keywords"/>\n        <meta t-if="meta_description or editable" name="description" t-att-content="meta_description"/>\n        <meta t-if="meta_keywords or editable" name="keywords" t-att-content="meta_keywords"/>\n        <t t-if="seo_object">\n        <meta name="default_description" t-att-content="website_meta_description or website_meta.get('meta_description')" groups="website.group_website_designer"/>\n            <!-- OpenGraph tags for Facebook sharing -->\n            <t t-set="opengraph_meta" t-value="website_meta.get('opengraph_meta')"/>\n            <t t-if="opengraph_meta">\n                <t t-foreach="opengraph_meta" t-as="property">\n                    <t t-if="isinstance(opengraph_meta[property], list)">\n                        <t t-foreach="opengraph_meta[property]" t-as="meta_content">\n        <meta t-att-property="property" t-att-content="meta_content"/>\n                        </t>\n                    </t>\n                    <t t-else="">\n        <meta t-att-property="property" t-att-content="opengraph_meta[property]"/>\n                    </t>\n                </t>\n            </t>\n            <!-- Twitter tags for sharing -->\n            <t t-set="twitter_meta" t-value="website_meta.get('twitter_meta')"/>\n            <t t-if="opengraph_meta">\n                <t t-foreach="twitter_meta" t-as="t_meta">\n        <meta t-att-name="t_meta" t-att-content="twitter_meta[t_meta]"/>\n                </t>\n            </t>\n        </t>\n        <!-- `alternate`/`canonical` mainly useful to crawlers/bots/SEO tools, which test the website as public user -->\n        <t t-if="request and request.is_frontend_multilang and website and website.is_public_user()">\n            <t t-set="alternate_languages" t-value="website._get_alternate_languages(canonical_params=canonical_params)"/>\n            <t t-foreach="alternate_languages" t-as="lg">\n        <link rel="alternate" t-att-hreflang="lg['hreflang']" t-att-href="lg['href']"/>\n            </t>\n        </t>\n        <link t-if="request and website and website.is_public_user()" rel="canonical" t-att-href="website._get_canonical_url(canonical_params=canonical_params)"/>\n        <!-- TODO: Once we have style in DB, add this preconnect only if a\n        google font is actually used. Note that if no font is used, the\n        preconnect is actually not connecting to the google servers. -->\n        <link rel="preconnect" href="https://fonts.gstatic.com/" crossorigin=""/>\n    </xpath>\n\n    <xpath expr="//header" position="attributes">\n        <attribute name="data-name">Header</attribute>\n    </xpath>\n\n    <xpath expr="//header/t[@t-cache]" position="attributes">\n        <!-- website.is_public_user() is needed for menus having a page with\n        restricted visibility (only shown to logged in user): public users and\n        logged in users can't share the menu cache. -->\n        <attribute name="t-cache">xmlid,website,website.is_public_user()</attribute>\n    </xpath>\n\n    <xpath expr="//header" position="before">\n        <t t-set="cta_btn_text" t-value="False"/>\n        <t t-set="cta_btn_href">/contactus</t>\n    </xpath>\n\n    <xpath expr="//footer" position="attributes">\n        <attribute name="data-name">Footer</attribute>\n        <!-- Background now controlled by css configuration, using color combinations -->\n        <attribute name="t-attf-class" add="o_colored_level o_cc" remove="bg-light" separator=" "/>\n        <!-- Add the main object as a cache key so that the footer_visible page\n        option is properly reflected across pages. Controllers and other objects\n        do not have any page option (yet) so they can share the same cache -->\n        <attribute name="t-cache" add="website,main_object._name == 'website.page' and main_object"/>\n    </xpath>\n    <xpath expr="//div[hasclass('o_footer_copyright')]" position="attributes">\n        <attribute name="data-name">Copyright</attribute>\n        <!-- Background now controlled by css configuration, using color combinations -->\n        <attribute name="class" add="o_colored_level o_cc" separator=" "/>\n    </xpath>\n    <xpath expr="//t[@t-call='web.brand_promotion']/.." position="attributes">\n        <attribute name="class" add="o_not_editable" separator=" "/>\n        <attribute name="t-if">not editable</attribute>\n    </xpath>\n\n    <xpath expr="//div[@id='wrapwrap']" position="after">\n        <t t-if="website and website.google_analytics_key and request.env['ir.http']._is_allowed_cookie('optional') and not editable">\n            <script id="tracking_code" async="1" t-attf-src="https://www.googletagmanager.com/gtag/js?id={{ website.google_analytics_key }}"/>\n            <script>\n                window.dataLayer = window.dataLayer || [];\n                function gtag(){dataLayer.push(arguments);}\n                gtag('js', new Date());\n                gtag('config', '<t t-esc="website.google_analytics_key"/>');\n            </script>\n        </t>\n        <t t-if="website and website.plausible_shared_key and not editable">\n            <script id="plausible_script" name="plausible" defer="defer" t-att-data-domain="website.plausible_site" t-att-src="website._get_plausible_script_url()"/>\n        </t>\n    </xpath>\n\n    <!-- Page options -->\n    <xpath expr="//div[@id='wrapwrap']" position="before">\n        <t groups="website.group_website_restricted_editor">\n            <t t-foreach="['header_overlay', 'header_color', 'header_visible', 'footer_visible']" t-as="optionName">\n                <!-- Firefox autocomplete is too aggressive and works on hidden inputs,\n                so we need to disable it (https://bugzilla.mozilla.org/show_bug.cgi?id=520561) -->\n                <input t-if="optionName in main_object" type="hidden" class="o_page_option_data" autocomplete="off" t-att-name="optionName" t-att-value="main_object[optionName]"/>\n            </t>\n        </t>\n        <div groups="base.group_user" class="o_frontend_to_backend_nav position-fixed d-none">\n            <svg xmlns="http://www.w3.org/2000/svg" class="o_frontend_to_backend_icon position-absolute" width="24px" height="24px" viewBox="-7 -7 24 24" preserveAspectRatio="xMinYMin">\n                <path fill="#FFF" d="M8 8V1a1 1 0 1 1 2 0v8a1 1 0 0 1-1 1H1a1 1 0 1 1 0-2h7z"/>\n            </svg>\n            <div class="o_frontend_to_backend_buttons d-flex">\n                <a href="#" title="Go to your Odoo Apps" class="o_frontend_to_backend_apps_btn fa fa-th d-flex align-items-center justify-content-center text-decoration-none" data-bs-toggle="dropdown"/>\n                <div class="dropdown-menu o_frontend_to_backend_apps_menu" role="menu">\n                    <a role="menuitem" class="dropdown-item" t-esc="menu['name']" t-as="menu" t-foreach="env['ir.ui.menu'].with_context(force_action=True).load_menus_root()['children']" t-attf-href="/web#menu_id=#{menu['id']}&amp;action=#{menu['action'] and menu['action'].split(',')[1] or ''}"/>\n                </div>\n                <a groups="website.group_website_restricted_editor" href="#" title="Edit this content" class="o_frontend_to_backend_edit_btn px-3 d-flex align-items-center justify-content-center text-decoration-none">\n                    <img src="/website/static/description/icon.png"/>Editor\n                </a>\n            </div>\n        </div>\n    </xpath>\n    <xpath expr="//div[@id='wrapwrap']" position="attributes">\n        <attribute name="t-attf-class" add="#{'o_header_overlay' if 'header_overlay' in main_object and main_object.header_overlay else ''}" separator=" "/>\n    </xpath>\n    <xpath expr="//header" position="attributes">\n        <attribute name="t-attf-class" add="#{main_object.header_color if 'header_color' in main_object else ''}" separator=" "/>\n    </xpath>\n    <xpath expr="//header" position="attributes">\n        <attribute name="t-attf-class" add="#{'d-none o_snippet_invisible' if 'header_visible' in main_object and not main_object.header_visible else ''}" separator=" "/>\n    </xpath>\n    <xpath expr="//footer[@id='bottom']" position="attributes">\n        <attribute name="t-attf-class" add="#{'d-none o_snippet_invisible' if 'footer_visible' in main_object and not main_object.footer_visible else ''}" separator=" "/>\n    </xpath>\n</data>	f	t	2023-11-03 05:56:04.332428	2024-05-06 12:23:05.521885	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
