1369	16	1354	1	1	Template Header Vertical	\N	website.template_header_vertical	qweb	website/views/website_templates.xml	\N	extension	{"en_US": "<data inherit_id=\\"website.layout\\" name=\\"Template Header Vertical\\" active=\\"False\\">\\n    <xpath expr=\\"//header//nav\\" position=\\"replace\\">\\n        <t t-call=\\"website.navbar\\">\\n            <t t-set=\\"_navbar_classes\\" t-valuef=\\"flex-lg-column shadow-sm py-0\\"/>\\n            <div id=\\"top_menu_container\\" class=\\"container align-items-center flex-lg-column flex-wrap\\">\\n                <div class=\\"d-flex flex-lg-row justify-content-between w-100 align-items-center flex-wrap flex-lg-nowrap\\">\\n                    <!-- Left -->\\n                    <div class=\\"o_header_centered_logo\\">\\n                        <div class=\\"oe_structure oe_structure_solo\\" id=\\"oe_structure_header_vertical_1\\"/>\\n                    </div>\\n                    <!-- Brand -->\\n                    <t t-call=\\"website.placeholder_header_brand\\">\\n                        <t t-set=\\"_link_class\\" t-valuef=\\"m-0\\"/>\\n                    </t>\\n                    <!-- Right -->\\n                    <div class=\\"o_header_centered_logo text-end\\">\\n                        <div class=\\"oe_structure oe_structure_solo\\" id=\\"oe_structure_header_vertical_2\\"/>\\n                    </div>\\n                    <!-- Call To Action -->\\n                    <t t-call=\\"website.placeholder_header_call_to_action\\">\\n                        <t t-set=\\"_div_classes\\" t-valuef=\\"ms-1 d-block d-lg-none ms-auto me-4\\"/>\\n                    </t>\\n                    <!-- Navbar Toggler -->\\n                    <t t-call=\\"website.navbar_toggler\\">\\n                        <t t-set=\\"_toggler_class\\" t-valuef=\\"my-3\\"/>\\n                    </t>\\n                </div>\\n                <div class=\\"d-lg-flex flex-lg-row align-items-center w-100\\">\\n                    <!-- Navbar 