data-save-unit=\\"rem\\"/>\\n                <we-input title=\\"X\\" data-customize-website-variable=\\"\\" data-variable=\\"btn-padding-x-lg\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            </we-row>\\n        </we-collapse>\\n        <we-collapse>\\n            <we-input string=\\"Font Size\\" data-customize-website-variable=\\"\\" data-variable=\\"btn-font-size\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <we-input string=\\"Small\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"\\" data-variable=\\"btn-font-size-sm\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <we-input string=\\"Large\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"\\" data-variable=\\"btn-font-size-lg\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n        </we-collapse>\\n        <we-input string=\\"Border Width\\" data-customize-website-variable=\\"\\" data-variable=\\"btn-border-width\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>&gt;\\n        <we-collapse>\\n            <we-input string=\\"Border Radius\\" data-customize-website-variable=\\"\\" data-variable=\\"btn-border-radius\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <we-input string=\\"Small\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"\\" data-variable=\\"btn-border-radius-sm\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <we-input string=\\"Large\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"\\" data-variable=\\"btn-border-radius-lg\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n        </we-collapse>\\n        <we-checkbox string=\\"Ripple Effect\\" data-customize-website-assets=\\"website.ripple_effect_scss, website.ripple_effect_js\\" data-customize-website-variable=\\"false|true\\" data-variable=\\"btn-ripple\\"/>\\n        <we-select string=\\"Link Style\\" data-variable=\\"link-underline\\">\\n            <we-button data-customize-website-variable=\\"'never'\\">Normal</we-button>\\n            <we-button data-customize-website-variable=\\"'hover'\\">Underline On Hover</we-button>\\n            <we-button data-customize-website-variable=\\"'always'\\">Always Underlined</we-button>\\n        </we-select>\\n\\n        <!-- Inputs -->\\n        <we-title>Inputs</we-title>\\n        <we-collapse>\\n            <we-row string=\\"Paddings\\">\\n                <we-input title=\\"Y\\" data-customize-website-variable=\\"\\" data-variable=\\"input-padding-y\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n                <we-input title=\\"X\\" data-customize-website-variable=\\"\\" data-variable=\\"input-padding-x\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            </we-row>\\n            <we-row string=\\"Small\\" class=\\"o_we_sublevel_1\\">\\n                <we-input title=\\"Y\\" data-customize-website-variable=\\"\\" data-variable=\\"input-padding-y-sm\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n                <we-input title=\\"X\\" data-customize-website-variable=\\"\\" data-variable=\\"input-padding-x-sm\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            </we-row>\\n            <we-row string=\\"Large\\" class=\\"o_we_sublevel_1\\">\\n                <we-input title=\\"Y\\" data-customize-website-variable=\\"\\" data-variable=\\"input-padding-y-lg\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n                <we-input title=\\"X\\" data-customize-website-variable=\\"\\" data-variable=\\"input-padding-x-lg\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            </we-row>\\n        </we-collapse>\\n        <we-collapse>\\n            <we-input string=\\"Font Size\\" data-customize-website-variable=\\"\\" data-variable=\\"input-font-size\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <we-input string=\\"Small\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"\\" data-variable=\\"input-font-size-sm\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <we-input string=\\"Large\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"\\" data-variable=\\"input-font-size-lg\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n        </we-collapse>\\n        <we-input string=\\"Border Width\\" data-customize-website-variable=\\"\\" data-variable=\\"input-border-width\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n        <we-collapse>\\n            <we-input string=\\"Border Radius\\" data-customize-website-variable=\\"\\" data-variable=\\"input-border-radius\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <we-input string=\\"Small\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"\\" data-variable=\\"input-border-radius-sm\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <we-input string=\\"Large\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"\\" data-variable=\\"input-border-radius-lg\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n        </we-collapse>\\n\\n        <we-row string=\\"Status Colors\\">\\n            <we-colorpicker title=\\"Success\\" data-customize-website-color=\\"\\" data-color-type=\\"theme\\" data-color=\\"success\\" data-selected-tab=\\"custom-colors\\"/>\\n            <we-colorpicker title=\\"Info\\" data-customize-website-color=\\"\\" data-color-type=\\"theme\\" data-color=\\"info\\" data-selected-tab=\\"custom-colors\\"/>\\n            <we-colorpicker title=\\"Warning\\" data-customize-website-color=\\"\\" data-color-type=\\"theme\\" data-color=\\"warning\\" data-selected-tab=\\"custom-colors\\"/>\\n            <we-colorpicker title=\\"Error\\" data-customize-website-color=\\"\\" data-color-type=\\"theme\\" data-color=\\"danger\\" data-selected-tab=\\"custom-colors\\"/>\\n        </we-row>\\n        <we-collapse>\\n            <we-row string=\\"Grays\\" class=\\"o_we_gray_preview o_we_collapse_toggler\\">\\n                <t t-foreach=\\"9\\" t-as=\\"i\\">\\n                    <t t-set=\\"grayCode\\" t-value=\\"str((9 - i) * 100)\\"/>\\n                    <span t-attf-title=\\"Gray #{grayCode}\\" t-attf-variable=\\"#{grayCode}\\" t-attf-class=\\"o_we_user_value_widget o_we_gray_preview bg-#{grayCode}\\"/>\\n                </t>\\n            </we-row>\\n            <we-range string=\\"Hue\\" class=\\"o_we_sublevel_1 o_we_slider_tint\\" data-customize-gray=\\"\\" data-param=\\"gray-hue\\" data-min=\\"0\\" data-max=\\"359.9\\" data-step=\\"0.1\\"/>\\n            <we-range string=\\"Saturation\\" class=\\"o_we_sublevel_1\\" data-customize-gray=\\"\\" data-param=\\"gray-extra-saturation\\" data-step=\\"0.1\\"/>\\n        </we-collapse>\\n    </div>\\n    <div data-js=\\"OptionsTab\\" data-selector=\\"website-settings\\" data-no-check=\\"true\\">\\n        <we-row string=\\"Theme\\">\\n            <we-button data-switch-theme=\\"\\" data-no-preview=\\"true\\">Switch Theme</we-button>\\n        </we-row>\\n        <we-row string=\\"Code Injection\\" title=\\"Enter code that will be added into every page of your site\\">\\n            <we-button data-no-preview=\\"true\\" data-open-custom-code-dialog=\\"head\\">&amp;lt;head&amp;gt;</we-button>\\n            <we-button data-no-preview=\\"true\\" data-open-custom-code-dialog=\\"footer\\">&amp;lt;/body&amp;gt;</we-button>\\n        </we-row>\\n        <we-row string=\\"Google Map\\">\\n            <we-button data-configure-api-key=\\"\\" data-no-preview=\\"true\\">Custom Key</we-button>\\n        </we-row>\\n    </div>\\n    <!-- Info page ('/website/info') -->\\n    <div data-selector=\\"main:has(.o_website_info)\\" data-page-options=\\"true\\" groups=\\"website.group_website_designer\\" data-no-check=\\"true\\" string=\\"Info Page\\">\\n        <we-checkbox string=\\"Odoo Information\\" data-customize-website-views=\\"website.show_website_info\\" data-no-preview=\\"true\\" data-reload=\\"/\\"/>\\n    </div>\\n    <div data-js=\\"SwitchableViews\\" data-selector=\\"#wrapwrap &gt; main\\" data-no-check=\\"true\\" groups=\\"website.group_website_designer\\">\\n            <!-- Options will be populated by JS -->\\n    </div>\\n\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.snippet_options</attribute></xpath></data>"}	<data inherit_id="web_editor.snippet_options" primary="True">\n    <!-- =================================================================== -->\n    <!-- Modify generic snippet options                                      -->\n    <!-- =================================================================== -->\n\n    <xpath expr="//we-button[@data-name='image_transform_opt']" position="attributes">\n        <attribute name="data-dependencies">no_animation_opt</attribute>\n    </xpath>\n\n    <!-- =================================================================== -->\n    <!-- Adding website specific snippet options                             -->\n    <!-- =================================================================== -->\n\n    <xpath expr="." position="inside">\n\n    <!-- COLOR, BORDER, SHADOW | .s_three_columns | .s_comparisons -->\n    <div data-js="Box" data-selector=".s_three_columns .row &gt; div, .s_comparisons .row &gt; div" data-target=".card">\n        <we-colorpicker string="Colors" data-select-style="true" data-css-property="background-color" data-color-prefix="bg-"/>\n        <t t-call="website.snippet_options_border_widgets">\n            <t t-set="so_rounded_no_dependencies" t-value="True"/>\n        </t>\n        <t t-call="website.snippet_options_shadow_widgets"/>\n    </div>\n\n    <!-- COLOR | .s_cards -->\n    <div data-selector=".s_card, .accordion .card">\n        <we-colorpicker string="Color" data-select-style="true" data-css-property="background-color" data-color-prefix="bg-"/>\n    </div>\n\n    <!-- H-ALIGN -->\n    <div id="so_text_align" data-selector=".s_share, .s_text_highlight, .s_social_media">\n        <we-button-group string="Alignment">\n            <we-button class="fa fa-fw fa-align-left" title="Left" data-select-class="text-start"/>\n            <we-button class="fa fa-fw fa-align-center" title="Center" data-select-class="text-center"/>\n            <we-button class="fa fa-fw fa-align-right" title="Right" data-select-class="text-end"/>\n        </we-button-group>\n    </div>\n\n    <div data-selector=".s_share, .s_social_media">\n        <we-select string="Title Position" data-apply-to=".s_share_title, .s_social_media_title">\n            <we-button data-select-class="d-block">Top</we-button>\n            <we-button data-select-class="">Left</we-button>\n            <we-button data-select-class="d-none">None</we-button>\n        </we-select>\n        <we-select string="Layout" data-apply-to=".fa">\n            <we-button data-select-class="rounded shadow-sm">Square</we-button>\n            <we-button data-select-class="rounded-empty-circle shadow-sm">Circle</we-button>\n            <we-button data-select-class="rounded-circle shadow-sm">Disk</we-button>\n            <we-button data-select-class="m-1">None</we-button>\n        </we-select>\n        <we-select string="Size" data-apply-to=".fa">\n            <we-button data-select-class="">Small</we-button>\n            <we-button data-select-class="fa-2x">Medium</we-button>\n            <we-button data-select-class="fa-3x">Big</we-button>\n        </we-select>\n        <!-- Compatibility, keep reverse logical, don't use `icon_color` -->\n        <we-checkbox string="Color" data-select-class="no_icon_color|"/>\n    </div>\n\n    <div id="so_width" data-selector=".s_alert, .s_card, .s_blockquote, .s_text_highlight">\n        <we-select string="Width">\n            <we-button data-select-class="w-25">25%</we-button>\n            <we-button data-select-class="w-50">50%</we-button>\n            <we-button data-select-class="w-75">75%</we-button>\n            <we-button data-select-class="w-100" data-name="so_width_100">100%</we-button>\n        </we-select>\n    </div>\n\n    <div id="so_block_align" data-selector=".s_alert, .s_card, .s_blockquote, .s_text_highlight">\n        <we-button-group string="Alignment" data-dependencies="!so_width_100">\n            <we-button class="fa fa-fw fa-align-left" title="Left" data-select-class="me-auto"/>\n            <we-button class="fa fa-fw fa-align-center" title="Center" data-select-class="mx-auto"/>\n            <we-button class="fa fa-fw fa-align-right" title="Right" data-select-class="ms-auto"/>\n        </we-button-group>\n    </div>\n\n    <!-- Carousel | .s_carousel | .s_quotes_carousel -->\n    <!-- Dedicated colorpicker so that there is not 3 level of\n         o_colored_level. Use inline-style color for the same reason. -->\n    <t t-call="website.snippet_options_background_options">\n        <t t-set="selector" t-value="'section'"/>\n        <t t-set="target" t-value="'&gt; .carousel'"/>\n        <t t-set="with_colors" t-value="True"/>\n        <t t-set="with_images" t-value="True"/>\n        <t t-set="with_videos" t-value="True"/>\n        <t t-set="with_shapes" t-value="True"/>\n        <t t-set="css_compatible" t-value="True"/>\n        <t t-set="with_gradients" t-value="True"/>\n    </t>\n    <div data-js="Carousel" data-selector="section" data-target="&gt; .carousel">\n        <we-row string="Slide">\n            <we-button data-add-slide="true" data-no-preview="true" class="o_we_bg_brand_primary">Add Slide</we-button>\n        </we-row>\n        <we-select string="Style">\n            <we-button data-select-class="s_carousel_default">Default</we-button>\n            <we-button data-select-class="s_carousel_bordered">Bordered</we-button>\n            <we-button data-select-class="s_carousel_boxed">Boxed</we-button>\n            <we-button data-select-class="s_carousel_rounded">Rounded</we-button>\n        </we-select>\n        <we-select string="Transition">\n            <we-button data-select-class="slide">Slide</we-button>\n            <we-button data-select-class="carousel-fade slide">Fade</we-button>\n            <we-divider/>\n            <we-button data-select-class="">None</we-button>\n        </we-select>\n        <we-input string="Speed" data-select-data-attribute="0s" data-attribute-name="bsInterval" data-unit="s" data-save-unit="ms" data-step="0.1"/>\n    </div>\n\n    <div data-js="CarouselItem" data-selector=".s_carousel .carousel-item, .s_quotes_carousel .carousel-item">\n        <we-button class="fa fa-fw fa-angle-left" data-switch-to-slide="left" data-no-preview="true" data-tooltip="Move Backward"/>\n        <we-button class="fa fa-fw fa-angle-right me-2" data-switch-to-slide="right" data-no-preview="true" data-tooltip="Move Forward"/>\n        <we-button class="fa fa-fw fa-plus o_we_bg_success" data-add-slide-item="true" data-no-preview="true" data-tooltip="Add Slide"/>\n        <we-button class="fa fa-fw fa-minus o_we_bg_danger" data-remove-slide="true" data-no-preview="true" data-tooltip="Remove Slide"/>\n    </div>\n\n    <!-- Accordion -->\n    <div data-js="collapse" data-selector=".accordion &gt; .card" data-drop-in=".accordion:has(&gt; .card)"/>\n\n    <div data-js="MultipleItems" data-selector=".s_faq_collapse">\n        <we-row string="Item">\n            <we-button data-add-item="" data-item=".accordion &gt; .card:last" data-select-item="" data-no-preview="true" class="o_we_bg_brand_primary">\n                Add Item\n            </we-button>\n        </we-row>\n    </div>\n\n    <!-- Columns only -->\n    <div data-js="layout_column" data-selector="section.s_features_grid, section.s_process_steps" data-target="&gt; *:has(&gt; .row), &gt; .s_allow_columns">\n        <we-select string="Columns" data-no-preview="true">\n            <we-button data-select-count="0" data-name="zero_cols_opt">None</we-button>\n            <we-button data-select-count="1">1</we-button>\n            <we-button data-select-count="2">2</we-button>\n            <we-button data-select-count="3">3</we-button>\n            <we-button data-select-count="4">4</we-button>\n            <we-button data-select-count="5">5</we-button>\n            <we-button data-select-count="6">6</we-button>\n        </we-select>\n    </div>\n\n    <!-- Grid only -->\n    <div data-js="layout_column" data-selector="section.s_masonry_block" data-target="&gt; *:has(&gt; .row)">\n        <we-button-group class="o_grid" string="Add Elements" data-no-preview="true" data-dependencies="grid_mode">\n            <we-button class="o_we_bg_brand_primary o_grid" data-add-element="image" title="Image" data-name="image">Image</we-button>\n            <we-button class="o_we_bg_brand_primary o_grid" data-add-element="text" title="Text" data-name="text">Text</we-button>\n            <we-button class="o_we_bg_brand_primary o_grid" data-add-element="button" title="Button" data-name="button">Button</we-button>\n        </we-button-group>\n        <we-row string="Padding (Y, X)">\n            <we-input data-dependencies="grid_mode" data-select-style="" data-css-property="--grid-item-padding-y" data-unit="px" data-apply-to=".row"/>\n            <we-input data-dependencies="grid_mode" data-select-style="" data-css-property="--grid-item-padding-x" data-unit="px" data-apply-to=".row"/>\n        </we-row>\n    </div>\n\n    <!-- Grid and columns -->\n    <div data-js="layout_column" data-selector="section, section.s_carousel_wrapper .carousel-item" data-target="&gt; *:has(&gt; .row), &gt; .s_allow_columns" data-exclude=".s_masonry_block, .s_features_grid, .s_media_list, .s_showcase, .s_table_of_content, .s_process_steps">\n        <we-row>\n            <we-button-group string="Layout" data-no-preview="true">\n                <we-button data-select-layout="grid" data-name="grid_mode">Grid</we-button>\n                <we-button data-select-layout="normal" data-name="normal_mode">Cols</we-button>\n            </we-button-group>\n            <we-select class="o_grid" data-no-preview="true" data-dependencies="normal_mode">\n                <we-button data-select-count="0" data-name="zero_cols_opt">None</we-button>\n                <we-button data-select-count="1">1</we-button>\n                <we-button data-select-count="2">2</we-button>\n                <we-button data-select-count="3">3</we-button>\n                <we-button data-select-count="4">4</we-button>\n                <we-button data-select-count="5">5</we-button>\n                <we-button data-select-count="6">6</we-button>\n            </we-select>\n        </we-row>\n        <we-button-group class="o_grid o_we_sublevel_1" string="Add Elements" data-no-preview="true" data-dependencies="grid_mode">\n            <we-button class="o_we_bg_brand_primary o_grid" data-add-element="image" title="Image" data-name="image">Image</we-button>\n            <we-button class="o_we_bg_brand_primary o_grid" data-add-element="text" title="Text" data-name="text">Text</we-button>\n            <we-button class="o_we_bg_brand_primary o_grid" data-add-element="button" title="Button" data-name="button">Button</we-button>\n        </we-button-group>\n        <we-row class="o_we_sublevel_1" string="Padding (Y, X)">\n            <we-input data-dependencies="grid_mode" data-select-style="" data-css-property="--grid-item-padding-y" data-unit="px" data-apply-to=".row"/>\n            <we-input data-dependencies="grid_mode" data-select-style="" data-css-property="--grid-item-padding-x" data-unit="px" data-apply-to=".row"/>\n        </we-row>\n    </div>\n\n    <!--  Vertical Alignment -->\n    <div data-option-name="vAlignment" id="row_valign_snippet_option" data-selector=".s_text_image, .s_image_text, .s_three_columns" data-target=".row">\n        <we-button-group class="o_we_sublevel_1" string="Vert. Alignment" title="Vertical Alignment" data-dependencies="normal_mode">\n            <we-button title="Align Top" data-select-class="align-items-start" data-img="/website/static/src/img/snippets_options/align_top.svg"/>\n            <we-button title="Align Middle" data-select-class="align-items-center" data-img="/website/static/src/img/snippets_options/align_middle.svg"/>\n            <we-button title="Align Bottom" data-select-class="align-items-end" data-img="/website/static/src/img/snippets_options/align_bottom.svg"/>\n            <we-button title="Stretch to Equal Height" data-select-class="align-items-stretch" data-img="/website/static/src/img/snippets_options/align_stretch.svg"/>\n        </we-button-group>\n    </div>\n\n    <!-- Move snippets around -->\n    <div data-js="SnippetMove" data-selector="section, .accordion &gt; .card, .s_showcase .row:not(.s_col_no_resize) &gt; div" data-no-scroll=".accordion &gt; .card">\n        <we-button class="fa fa-fw fa-angle-up" data-move-snippet="prev" data-no-preview="true" data-name="move_up_opt"/>\n        <we-button class="fa fa-fw fa-angle-down" data-move-snippet="next" data-no-preview="true" data-name="move_down_opt"/>\n    </div>\n    <div data-js="SnippetMove" data-selector=".row:not(.s_col_no_resize) &gt; div, .nav-item" data-exclude=".s_showcase .row &gt; div" data-name="move_horizontally_opt">\n        <we-button class="fa fa-fw fa-angle-left" data-move-snippet="prev" data-no-preview="true" data-name="move_left_opt"/>\n        <we-button class="fa fa-fw fa-angle-right" data-move-snippet="next" data-no-preview="true" data-name="move_right_opt"/>\n    </div>\n\n    <!-- Background -->\n    <t t-set="only_bg_color_selector" t-value="'section .row &gt; div, .s_text_highlight, .s_mega_menu_thumbnails_footer'"/>\n    <t t-set="only_bg_color_exclude" t-value="'.s_col_no_bgcolor, .s_col_no_bgcolor.row &gt; div, .s_masonry_block .row &gt; div, .s_color_blocks_2 .row &gt; div, .s_image_gallery .row &gt; div'"/>\n\n    <t t-set="base_only_bg_image_selector" t-value="'.s_tabs .oe_structure &gt; *, footer .oe_structure &gt; *'"/>\n    <t t-set="only_bg_image_selector" t-value="base_only_bg_image_selector"/>\n    <t t-set="only_bg_image_exclude" t-value="''"/>\n\n    <t t-set="both_bg_color_image_selector" t-value="'section, .carousel-item, .s_masonry_block .row &gt; div, .s_color_blocks_2 .row &gt; div, .parallax'"/>\n    <t t-set="both_bg_color_image_exclude" t-value="base_only_bg_image_selector + ', .s_carousel_wrapper, .s_image_gallery .carousel-item, .s_google_map, .s_map, [data-snippet] :not(.oe_structure) &gt; [data-snippet], .s_masonry_block .s_col_no_resize'"/>\n\n    <t t-call="website.snippet_options_background_options">\n        <t t-set="selector" t-value="both_bg_color_image_selector"/>\n        <t t-set="exclude" t-value="both_bg_color_image_exclude"/>\n        <t t-set="with_colors" t-value="True"/>\n        <t t-set="with_images" t-value="True"/>\n        <t t-set="with_videos" t-value="True"/>\n        <t t-set="with_shapes" t-value="True"/>\n        <t t-set="with_color_combinations" t-value="True"/>\n        <t t-set="with_gradients" t-value="True"/>\n    </t>\n\n    <t t-call="website.snippet_options_background_options">\n        <t t-set="selector" t-value="only_bg_color_selector"/>\n        <t t-set="exclude" t-value="only_bg_color_exclude"/>\n        <t t-set="with_colors" t-value="True"/>\n        <t t-set="with_images" t-value="False"/>\n        <t t-set="with_color_combinations" t-value="True"/>\n        <t t-set="with_gradients" t-value="True"/>\n    </t>\n\n    <t t-call="website.snippet_options_background_options">\n        <t t-set="selector" t-value="only_bg_image_selector"/>\n        <t t-set="exclude" t-value="only_bg_image_exclude"/>\n        <t t-set="with_colors" t-value="False"/>\n        <t t-set="with_images" t-value="True"/>\n        <t t-set="with_videos" t-value="True"/>\n        <t t-set="with_shapes" t-value="True"/>\n    </t>\n\n    <!-- Border | Columns -->\n    <div data-js="Box" data-selector="section .row &gt; div" data-exclude=".s_col_no_bgcolor, .s_col_no_bgcolor.row &gt; div, .s_image_gallery .row &gt; div, .s_masonry_block .s_col_no_resize">\n        <t t-call="website.snippet_options_border_widgets"/>\n        <t t-call="website.snippet_options_shadow_widgets"/>\n    </div>\n\n    <div data-js="sizing_y" data-selector="section, .row &gt; div, .parallax, .s_hr, .carousel-item, .s_rating" data-exclude="section:has(&gt; .carousel), .s_image_gallery .carousel-item, .s_col_no_resize.row &gt; div, .s_col_no_resize"/>\n\n    <div data-js="sizing_x" data-selector=".row &gt; div" data-drop-near=".row:not(.s_col_no_resize) &gt; div" data-exclude=".s_col_no_resize.row &gt; div, .s_col_no_resize"/>\n\n    <div data-js="sizing_grid" data-selector=".row &gt; div" data-drop-near=".row.o_grid_mode &gt; div" data-exclude=".s_col_no_resize.row &gt; div, .s_col_no_resize"/>\n\n    <t t-set="so_snippet_addition_selector" t-translation="off">section, .parallax</t>\n    <div id="so_snippet_addition" t-att-data-selector="so_snippet_addition_selector" data-drop-in=":not(p).oe_structure:not(.oe_structure_solo), :not(.o_mega_menu):not(p)[data-oe-type=html], :not(p).oe_structure.oe_structure_solo:not(:has(&gt; section, &gt; div))"/>\n        <!-- /!\\ drop-in here is partly duplicated for s_popup (see dedicated options) -->\n        <!-- TODO should be improved -->\n\n    <t t-set="so_content_addition_selector" t-translation="off">blockquote, .s_card:not(.s_timeline_card), .s_alert, .o_facebook_page, .s_share, .s_social_media, .s_rating, .s_hr, .s_google_map, .s_map, .s_countdown, .s_chart, .s_text_highlight, .s_progress_bar, .s_badge, .s_embed_code, .s_donation, .s_add_to_cart</t>\n    <div id="so_content_addition" t-att-data-selector="so_content_addition_selector" t-attf-data-drop-near="p, h1, h2, h3, ul, ol, .row &gt; div:not(.o_grid_item_image) &gt; img, #{so_content_addition_selector}" data-drop-in=".content, nav"/>\n    <!-- TODO in master: remove the `.content` above, as it will not refer to\n        anything when the `content` classes in carousel will be removed. -->\n\n    <div data-js="SnippetSave" t-attf-data-selector="#{so_snippet_addition_selector}, #{so_content_addition_selector}, .s_popup" data-exclude=".o_no_save">\n        <we-button class="fa fa-fw fa-save o_we_link o_we_hover_warning" title="Save the block to use it elsewhere" data-save-snippet="" data-no-preview="true"/>\n    </div>\n\n    <div data-js="menu_data" data-selector="#top_menu li &gt; a, [data-content_menu_id] li &gt; a" data-exclude=".dropdown-toggle, li.o_header_menu_button a, [data-toggle], .o_offcanvas_logo" data-no-check="true"/>\n\n    <div data-js="company_data" data-selector="[data-oe-expression='res_company.partner_id']" data-no-check="true"/>\n\n    <div data-js="HeaderLayout" data-selector="#wrapwrap &gt; header" data-no-check="true" groups="website.group_website_designer">\n        <we-select string="Template" data-variable="header-template" data-reload="/" data-no-preview="true">\n            <we-button title="Default" data-name="header_default_opt" data-customize-website-views="website.template_header_default" data-customize-website-variable="'default'" data-img="/website/static/src/img/snippets_options/header_template_default.svg"/>\n            <we-button title="Hamburger menu" data-name="header_hamburger_opt" data-customize-website-views="website.template_header_hamburger" data-customize-website-variable="'hamburger'" data-img="/website/static/src/img/snippets_options/header_template_hamburger.svg"/>\n            <we-button title="Vertical" data-name="header_vertical_opt" data-customize-website-views="website.template_header_vertical" data-customize-website-variable="'vertical'" data-img="/website/static/src/img/snippets_options/header_template_vertical.svg"/>\n            <we-button title="Sidebar" data-name="header_sidebar_opt" data-customize-website-views="website.template_header_sidebar, website.no_autohide_menu" data-customize-website-variable="'sidebar'" data-img="/website/static/src/img/snippets_options/header_template_sidebar.svg"/>\n            <we-button title="Slogan" data-name="header_slogan_opt" data-customize-website-views="website.template_header_slogan" data-customize-website-variable="'slogan'" data-img="/website/static/src/img/snippets_options/header_template_slogan.svg"/>\n            <we-button title="Contact" data-name="header_contact_opt" data-customize-website-views="website.template_header_contact" data-customize-website-variable="'Contact'" data-img="/website/static/src/img/snippets_options/header_template_contact.svg"/>\n            <we-button title="Boxed" data-name="header_boxed_opt" data-customize-website-views="website.template_header_boxed" data-customize-website-variable="'boxed'" data-img="/website/static/src/img/snippets_options/header_template_boxed.svg"/>\n            <we-button title="Centered Logo" data-name="header_centered_logo_opt" data-customize-website-views="website.template_header_centered_logo" data-customize-website-variable="'centered_logo'" data-img="/website/static/src/img/snippets_options/header_template_centered_logo.svg"/>\n            <we-button title="Image" data-name="header_image_opt" data-customize-website-views="website.template_header_image" data-customize-website-variable="'image'" data-img="/website/static/src/img/snippets_options/header_template_image.svg"/>\n            <we-button title="Hamburger Full" data-name="header_hamburger_full_opt" data-customize-website-views="website.template_header_hamburger_full" data-customize-website-variable="'hamburger-full'" data-img="/website/static/src/img/snippets_options/header_template_hamburger_full.svg"/>\n            <we-button title="Magazine" data-name="header_magazine_opt" data-customize-website-views="website.template_header_magazine" data-customize-website-variable="'magazine'" data-img="/website/static/src/img/snippets_options/header_template_magazine.svg"/>\n        </we-select>\n\n        <!-- Header Sidebar Template - Options -->\n        <we-input string="Width" class="o_we_sublevel_1" data-dependencies="header_sidebar_opt" data-customize-website-variable="null" data-variable="sidebar-width" data-unit="px" data-save-unit="rem"/>\n\n        <we-row string="Colors">\n            <we-colorpicker data-customize-website-color="" data-color="menu" data-customize-website-layer2-color="" data-layer-color="menu-custom" data-layer-gradient="menu-gradient" data-no-bundle-reload="true" data-null-value="'NULL'" data-with-combinations="customizeWebsiteColor" data-with-gradients="true"/>\n            <we-colorpicker data-dependencies="header_boxed_opt" data-customize-website-color="" data-color="header-boxed" data-customize-website-layer2-color="" data-layer-color="header-boxed-custom" data-layer-gradient="header-boxed-gradient" data-no-bundle-reload="true" data-null-value="'NULL'" data-with-combinations="customizeWebsiteColor" data-with-gradients="true"/>\n        </we-row>\n    </div>\n\n    <!-- Header - Borders & Shadows -->\n    <div data-js="HeaderBox" id="option_header_shadow" data-selector="#wrapwrap &gt; header" data-target="nav" data-no-check="true" groups="website.group_website_designer">\n        <t t-call="website.snippet_options_border_widgets">\n            <t t-set="so_rounded_no_dependencies" t-value="True"/>\n            <t t-set="width_variable" t-value="'menu-border-width'"/>\n            <t t-set="style_variable" t-value="'menu-border-style'"/>\n            <t t-set="color_variable" t-value="'menu-border-color'"/>\n            <t t-set="radius_variable" t-value="'menu-border-radius'"/>\n        </t>\n        <t t-call="website.snippet_options_shadow_widgets">\n            <t t-set="shadow_variable" t-value="'menu-box-shadow'"/>\n        </t>\n    </div>\n\n    <div data-selector="#wrapwrap &gt; header" data-no-check="true" groups="website.group_website_designer">\n\n        <we-select string="Scroll Effect" data-dependencies="!header_sidebar_opt" class="o_scroll_effects_selector" data-variable="header-scroll-effect">\n            <t t-set="header_effect_standard_label">Standard</t>\n            <t t-set="header_effect_scroll_label">Scroll</t>\n            <t t-set="header_effect_fixed_label">Fixed</t>\n            <t t-set="header_effect_disappears_label">Disappears</t>\n            <t t-set="header_effect_fadeout_label">Fade Out</t>\n            <we-button id="option_header_visibility_standard" t-att-data-select-label="header_effect_standard_label" class="o_we_img_animate" data-customize-website-variable="'standard'" data-name="header_visibility_standard_opt" data-select-class="o_header_standard" data-customize-website-views="website.header_visibility_standard" data-img="/website/static/src/img/snippets_options/header_effect_standard.png">\n                <span t-esc="header_effect_standard_label"/>\n            </we-button>\n            <we-button id="option_header_effect_scroll" t-att-data-select-label="header_effect_scroll_label" class="o_we_img_animate" data-customize-website-variable="'scroll'" data-name="header_effect_scroll_opt" data-select-class="" data-customize-website-views="" data-img="/website/static/src/img/snippets_options/header_effect_scroll.png">\n                <span t-esc="header_effect_scroll_label"/>\n            </we-button>\n            <we-button id="option_header_effect_fixed" t-att-data-select-label="header_effect_fixed_label" class="o_we_img_animate" data-customize-website-variable="'fixed'" data-name="header_effect_fixed_opt" data-select-class="o_header_fixed" data-customize-website-views="website.header_visibility_fixed" data-img="/website/static/src/img/snippets_options/header_effect_fixed.png">\n                <span t-esc="header_effect_fixed_label"/>\n            </we-button>\n            <we-button id="option_header_effect_disappears" t-att-data-select-label="header_effect_disappears_label" class="o_we_img_animate" data-customize-website-variable="'disappears'" data-name="header_effect_disappears_opt" data-select-class="o_header_disappears" data-customize-website-views="website.header_visibility_disappears" data-img="/website/static/src/img/snippets_options/header_effect_disappears.png">\n                <span t-esc="header_effect_disappears_label"/>\n            </we-button>\n            <we-button id="option_header_effect_fade_out" t-att-data-select-label="header_effect_fadeout_label" class="o_we_img_animate" data-customize-website-variable="'fade-out'" data-name="header_effect_fade_out_opt" data-select-class="o_header_fade_out" data-customize-website-views="website.header_visibility_fade_out" data-img="/website/static/src/img/snippets_options/header_effect_fade_out.png">\n               <span t-esc="header_effect_fadeout_label"/>\n            </we-button>\n        </we-select>\n    </div>\n\n    <div data-js="TopMenuVisibility" data-selector="[data-main-object^='website.page('] #wrapwrap &gt; header" data-no-check="true">\n        <we-select string="Header Position" data-no-preview="true" data-dependencies="!header_sidebar_opt">\n            <we-button data-visibility="transparent">Over The Content</we-button>\n            <we-button data-name="regular_header_visibility_opt" data-visibility="regular">Regular</we-button>\n            <we-button data-visibility="hidden">Hidden</we-button>\n        </we-select>\n    </div>\n\n    <div data-js="topMenuColor" data-selector="[data-main-object^='website.page('] #wrapwrap &gt; header" data-no-check="true">\n        <we-colorpicker string="Background" class="o_we_sublevel_1" id="option_header_transparent_color" data-select-style="true" data-css-property="background-color" data-color-prefix="bg-" data-excluded="theme, common, custom"/>\n    </div>\n\n    <!-- Header > Navbar Options -->\n    <div data-js="HeaderNavbar" data-selector="#wrapwrap &gt; header nav.navbar" data-no-check="true" groups="website.group_website_designer">\n        <!-- Generic alignment option controling all the template at once. -->\n        <!-- Currently needed to be this way as the SCSS variable controls -->\n        <!-- the mobile alignement which is the same for all templates. -->\n        <we-select string="Alignment" data-name="header_alignment_opt" data-variable="hamburger-position" data-reload="/">\n            <we-button data-customize-website-views="" data-customize-website-variable="'left'">Left</we-button>\n            <we-button data-customize-website-views="website.template_header_default_align_center, website.template_header_hamburger_align_center, website.template_header_slogan_align_center" data-customize-website-variable="'center'">Center</we-button>\n            <we-button data-customize-website-views="website.template_header_default_align_right, website.template_header_hamburger_align_right, website.template_header_slogan_align_right" data-customize-website-variable="'right'">Right</we-button>\n        </we-select>\n\n        <!-- Generic Hamburger Options (mobile or not) -->\n        <we-select string="Hamburger Type" data-name="header_hamburger_type_opt" data-variable="hamburger-type" data-reload="/">\n            <we-button data-name="default_hamburger_opt" data-customize-website-variable="'default'" data-customize-website-views="">Default</we-button>\n            <we-button data-name="off_canvas_menu_opt" data-customize-website-variable="'off-canvas'" data-customize-website-views="website.option_header_off_canvas, website.option_header_off_canvas_template_header_hamburger, website.option_header_off_canvas_template_header_sidebar, website.option_header_off_canvas_template_header_hamburger_full">Off-Canvas</we-button>\n            <we-button data-name="no_hamburger_opt" data-customize-website-variable="'no-hamburger'" data-customize-website-views="website.option_header_no_mobile_hamburger">Same as desktop</we-button>\n        </we-select>\n\n        <we-select string="Off-Canvas Logo" class="o_we_sublevel_1" data-dependencies="off_canvas_menu_opt" data-reload="/">\n            <we-button data-customize-website-views="">Text</we-button>\n            <we-button data-customize-website-views="website.option_header_off_canvas_logo_show">Image</we-button>\n        </we-select>\n\n        <we-row string="Font">\n            <we-fontfamilypicker data-variable="navbar-font"/>\n            <we-input data-customize-website-variable="null" data-variable="header-font-size" data-unit="px" data-save-unit="rem"/>\n        </we-row>\n\n        <we-select string="Links Style" data-variable="header-links-style" data-reload="/">\n            <we-button data-name="option_header_navbar_links_default" data-customize-website-views="" data-customize-website-variable="'default'">Default</we-button>\n            <we-button data-name="option_header_navbar_links_fill" data-customize-website-views="website.header_navbar_pills_style" data-customize-website-variable="'fill'">Fill</we-button>\n            <we-button data-name="option_header_navbar_links_outline" data-customize-website-views="" data-customize-website-variable="'outline'">Outline</we-button>\n            <we-button data-name="option_header_navbar_links_pills" data-customize-website-views="website.header_navbar_pills_style" data-customize-website-variable="'pills'">Pills</we-button>\n            <we-button data-name="option_header_navbar_block" data-customize-website-views="website.header_navbar_pills_style" data-customize-website-variable="'block'">Block</we-button>\n            <we-button data-name="option_header_navbar_border_bottom" data-customize-website-views="" data-customize-website-variable="'border-bottom'">Border Bottom</we-button>\n        </we-select>\n\n        <we-select id="option_header_dropdown" string="Sub Menus" data-dependencies="!header_hamburger_opt" data-no-preview="true">\n            <we-button data-select-class="o_hoverable_dropdown" data-customize-website-views="website.header_hoverable_dropdown">On Hover</we-button>\n            <we-button data-select-class="" data-name="header_dropdown_on_click_opt">On Click</we-button>\n        </we-select>\n\n        <we-checkbox string="Show Sign In" data-customize-website-views="portal.user_sign_in" data-reload="/" data-no-preview="true"/>\n        <we-checkbox string="Call to Action" data-customize-website-views="website.header_call_to_action" data-reset-view-arch="true" data-reload="/"/>\n        <we-select string="Language Selector" data-reload="/">\n            <we-button data-name="header_language_selector_none_opt" data-customize-website-views="">None</we-button>\n            <we-button data-customize-website-views="website.header_language_selector">Dropdown</we-button>\n            <we-button data-customize-website-views="website.header_language_selector, website.header_language_selector_inline">Inline</we-button>\n        </we-select>\n        <we-select string="Label" class="o_we_sublevel_1" data-dependencies="!header_language_selector_none_opt" data-reload="/">\n            <we-button data-customize-website-views="">Text</we-button>\n            <we-button data-customize-website-views="website.header_language_selector_flag, website.header_language_selector_no_text">Flag</we-button>\n            <we-button data-customize-website-views="website.header_language_selector_flag">Flag and Text</we-button>\n        </we-select>\n        <we-select string="Logo" data-reload="/">\n            <we-button data-customize-website-views="" data-name="option_header_brand_none">None</we-button>\n            <we-button data-customize-website-views="website.option_header_brand_name">Text</we-button>\n            <we-button data-customize-website-views="website.option_header_brand_logo">Image</we-button>\n        </we-select>\n        <we-input string="Height" class="o_we_sublevel_1" data-dependencies="!option_header_brand_none" data-customize-website-variable="null" data-variable="logo-height" data-unit="px" data-save-unit="rem"/>\n        <we-input string="Height (Scrolled)" class="o_we_sublevel_1" data-name="option_logo_height_scrolled" data-customize-website-variable="null" data-variable="fixed-logo-height" data-unit="px" data-save-unit="rem" data-dependencies="!header_effect_scroll_opt"/>\n    </div>\n\n    <!-- Footer - Colors & Layouts -->\n    <div data-js="WebsiteLevelColor" data-selector="#wrapwrap &gt; footer" data-no-check="true" groups="website.group_website_designer">\n\n        <!-- Layouts -->\n        <we-select string="Template" data-variable="footer-template" data-reload="/">\n            <we-button title="Default" data-customize-website-views="website.footer_custom" data-customize-website-variable="'default'" data-img="/website/static/src/img/snippets_options/footer_template_default.svg"/>\n            <we-button title="Descriptive" data-customize-website-views="website.template_footer_descriptive" data-customize-website-variable="'descriptive'" data-img="/website/static/src/img/snippets_options/footer_template_descriptive.svg"/>\n            <we-button title="Centered" data-customize-website-views="website.template_footer_centered" data-customize-website-variable="'centered'" data-img="/website/static/src/img/snippets_options/footer_template_centered.svg"/>\n            <we-button title="Links" data-customize-website-views="website.template_footer_links" data-customize-website-variable="'links'" data-img="/website/static/src/img/snippets_options/footer_template_links.svg"/>\n            <we-button title="Minimalist" data-customize-website-views="website.template_footer_minimalist" data-customize-website-variable="'minimalist'" data-img="/website/static/src/img/snippets_options/footer_template_minimalist.svg"/>\n            <we-button title="Contact" data-customize-website-views="website.template_footer_contact" data-customize-website-variable="'contact'" data-img="/website/static/src/img/snippets_options/footer_template_contact.svg"/>\n            <we-button title="Call-to-action" data-customize-website-views="website.template_footer_call_to_action" data-customize-website-variable="'call_to_action'" data-img="/website/static/src/img/snippets_options/footer_template_call_to_action.svg"/>\n            <we-button title="Headline" data-customize-website-views="website.template_footer_headline" data-customize-website-variable="'headline'" data-img="/website/static/src/img/snippets_options/footer_template_headline.svg"/>\n        </we-select>\n        <!-- Colors -->\n        <we-colorpicker string="Colors" data-customize-website-color="" data-color="footer" data-customize-website-layer2-color="" data-layer-color="footer-custom" data-layer-gradient="footer-gradient" data-no-bundle-reload="true" data-null-value="'NULL'" data-with-combinations="customizeWebsiteColor" data-with-gradients="true"/>\n        <we-select string="Slideout Effect" data-variable="footer-effect" data-reload="/">\n            <we-button string="Regular" data-customize-website-views="" data-customize-website-variable=""/>\n            <we-button string="Slide Hover" data-customize-website-views="website.template_footer_slideout" data-customize-website-variable="'slideout_slide_hover'"/>\n            <we-button string="Shadow" data-customize-website-views="website.template_footer_slideout" data-customize-website-variable="'slideout_shadow'"/>\n        </we-select>\n        <we-checkbox string="Copyright" data-name="footer_copyright_opt" data-customize-website-views="website.footer_no_copyright|" data-no-preview="true" data-reload="/"/>\n        <we-checkbox string="Language Selector" data-dependencies="!footer_copyright_opt" data-customize-website-views="website.footer_no_copyright|portal.footer_language_selector" data-no-preview="true" data-reload="/"/>\n    </div>\n\n    <!-- Footer - Borders & Shadows -->\n    <div data-js="Box" data-selector="#wrapwrap &gt; footer" data-target="#footer" data-no-check="true" groups="website.group_website_designer">\n        <t t-call="website.snippet_options_border_widgets"/>\n        <t t-call="website.snippet_options_shadow_widgets"/>\n    </div>\n\n    <!-- Scroll to Top -->\n    <div data-selector="#wrapwrap &gt; footer" data-no-check="true" groups="website.group_website_designer">\n        <we-row string="Scroll Top Button">\n            <we-checkbox data-name="footer_scrolltop_opt" data-customize-website-views="website.option_footer_scrolltop" data-customize-website-variable="false|true" data-variable="footer-scrolltop" data-reload="/"/>\n            <we-select data-dependencies="footer_scrolltop_opt" data-apply-to="#o_footer_scrolltop_wrapper">\n                <we-button string="Left" data-select-class="justify-content-start"/>\n                <we-button string="Center" data-select-class="justify-content-center"/>\n                <we-button string="Right" data-select-class="justify-content-end"/>\n            </we-select>\n        </we-row>\n    </div>\n\n    <div data-js="HideFooter" data-selector="[data-main-object^='website.page('] #wrapwrap &gt; footer" data-no-check="true" groups="website.group_website_designer">\n        <we-checkbox string="Page Visibility" data-name="hide_footer_page_opt" data-visibility="hidden|shown" data-no-preview="true"/>\n    </div>\n\n    <!-- Copyright -->\n    <div data-js="WebsiteLevelColor" data-selector=".o_footer_copyright" data-no-check="true" groups="website.group_website_designer">\n        <we-colorpicker string="Colors" data-customize-website-color="" data-color="copyright" data-customize-website-layer2-color="" data-layer-color="copyright-custom" data-layer-gradient="copyright-gradient" data-no-bundle-reload="true" data-null-value="'NULL'" data-with-combinations="customizeWebsiteColor" data-with-gradients="true"/>\n        <we-select string="Language Selector" data-reload="/">\n            <we-button data-name="language_selector_none_opt" data-customize-website-views="">None</we-button>\n            <we-button data-customize-website-views="portal.footer_language_selector">Dropdown</we-button>\n            <we-button data-customize-website-views="portal.footer_language_selector, website.footer_language_selector_inline">Inline</we-button>\n        </we-select>\n        <we-select string="Label" class="o_we_sublevel_1" data-dependencies="!language_selector_none_opt" data-reload="/">\n            <we-button data-customize-website-views="">Text</we-button>\n            <we-button data-customize-website-views="website.footer_language_selector_flag, website.footer_language_selector_no_text">Flag</we-button>\n            <we-button data-customize-website-views="website.footer_language_selector_flag">Flag and Text</we-button>\n        </we-select>\n    </div>\n\n    <!-- Anchor Name -->\n    <div data-js="anchor" data-selector=":not(p).oe_structure &gt; *, :not(p)[data-oe-type=html] &gt; *" data-exclude=".modal *, .oe_structure .oe_structure *, [data-oe-type=html] .oe_structure *, .s_popup">\n        <we-button class="fa fa-fw fa-link o_we_link" title="Create a link to target this section" data-no-preview="true"/>\n    </div>\n\n    <!-- Mega Menu settings -->\n    <div data-js="MegaMenuLayout" data-selector=".o_mega_menu">\n        <we-select string="Template" data-name="mega_menu_template_opt">\n            <t t-set="_label">Multi Menus</t>\n            <we-button t-att-data-select-label="_label" data-select-template="website.s_mega_menu_multi_menus" data-img="/website/static/src/img/snippets_thumbs/s_mega_menu_multi_menus.svg" t-out="_label"/>\n            <t t-set="_label">Image Menu</t>\n            <we-button t-att-data-select-label="_label" data-select-template="website.s_mega_menu_menu_image_menu" data-img="/website/static/src/img/snippets_thumbs/s_mega_menu_menu_image_menu.svg" t-out="_label"/>\n            <t t-set="_label">Odoo Menu</t>\n            <we-button t-att-data-select-label="_label" data-select-template="website.s_mega_menu_odoo_menu" data-img="/website/static/src/img/snippets_thumbs/s_mega_menu_odoo_menu.svg" t-out="_label"/>\n            <t t-set="_label">Little Icons</t>\n            <we-button t-att-data-select-label="_label" data-select-template="website.s_mega_menu_little_icons" data-img="/website/static/src/img/snippets_thumbs/s_mega_menu_little_icons.svg" t-out="_label"/>\n            <t t-set="_label">Big Icons Subtitles</t>\n            <we-button t-att-data-select-label="_label" data-select-template="website.s_mega_menu_big_icons_subtitles" data-img="/website/static/src/img/snippets_thumbs/s_mega_menu_big_icons_subtitles.svg" t-out="_label"/>\n            <t t-set="_label">Images Subtitles</t>\n            <we-button t-att-data-select-label="_label" data-select-template="website.s_mega_menu_images_subtitles" data-img="/website/static/src/img/snippets_thumbs/s_mega_menu_images_subtitles.svg" t-out="_label"/>\n            <t t-set="_label">Logos</t>\n            <we-button t-att-data-select-label="_label" data-select-template="website.s_mega_menu_menus_logos" data-img="/website/static/src/img/snippets_thumbs/s_mega_menu_menus_logos.svg" t-out="_label"/>\n            <t t-set="_label">Thumbnails</t>\n            <we-button t-att-data-select-label="_label" data-select-template="website.s_mega_menu_thumbnails" data-img="/website/static/src/img/snippets_thumbs/s_mega_menu_thumbnails.svg" t-out="_label"/>\n            <t t-set="_label">Cards</t>\n            <we-button t-att-data-select-label="_label" data-select-template="website.s_mega_menu_cards" data-img="/website/static/src/img/snippets_thumbs/s_mega_menu_cards.svg" t-out="_label"/>\n        </we-select>\n        <we-select string="Size">\n            <we-button data-select-class="">Full-Width</we-button>\n            <we-button data-select-class="o_mega_menu_container_size">Narrow</we-button>\n        </we-select>\n    </div>\n\n    <div data-js="MegaMenuNoDelete" data-selector=".o_mega_menu &gt; section"/>\n\n    <div data-selector=".o_mega_menu .nav &gt; .nav-link" data-drop-in=".o_mega_menu nav" data-drop-near=".o_mega_menu .nav-link"/>\n\n    <div data-js="CoverProperties" data-selector=".o_record_cover_container" data-no-check="true">\n        <we-row string="Background" class="o_we_full_row">\n            <t t-call="web_editor.snippet_options_background_color_widget">\n                <t t-set="with_color_combinations" t-value="True"/>\n                <t t-set="with_gradients" t-value="True"/>\n            </t>\n            <we-button-group class="ms-auto">\n                <we-imagepicker title="Image" data-background="" data-button-style="true"/>\n                <we-button class="fa fa-fw fa-ban" title="None" data-background="">\n                </we-button>\n            </we-button-group>\n        </we-row>\n        <we-select string="Size" data-name="size_opt" data-cover-opt-name="size">\n            <we-button data-select-class="o_full_screen_height">Full Screen</we-button>\n            <we-button class="o_record_cover_opt_size_default" data-select-class="o_half_screen_height">Half Screen</we-button>\n            <we-button data-select-class="cover_auto">Fit text</we-button>\n        </we-select>\n        <we-select string="Filter Intensity" data-name="filters_opt" data-cover-opt-name="filters">\n            <we-button data-filter-value="0.0">None</we-button>\n            <we-button data-filter-value="0.2">Low</we-button>\n            <we-button data-filter-value="0.4">Medium</we-button>\n            <we-button data-filter-value="0.6">High</we-button>\n        </we-select>\n        <we-select string="Text Alignment" data-name="text_align_opt" data-cover-opt-name="text_align">\n            <we-button data-select-class="">Left</we-button>\n            <we-button data-select-class="text-center">Centered</we-button>\n            <we-button data-select-class="text-end">Right</we-button>\n        </we-select>\n    </div>\n\n    <!-- Stretch section -->\n    <div data-js="ContainerWidth" data-selector="section, .s_carousel .carousel-item, s_quotes_carousel .carousel-item" data-exclude="[data-snippet] :not(.oe_structure) &gt; [data-snippet]" data-target="&gt; .container, &gt; .container-fluid, &gt; .o_container_small">\n        <we-button-group string="Content Width">\n            <we-button data-select-class="o_container_small" data-img="/website/static/src/img/snippets_options/content_width_small.svg" title="Small"/>\n            <we-button data-select-class="container" data-img="/website/static/src/img/snippets_options/content_width_normal.svg" title="Regular"/>\n            <we-button data-select-class="container-fluid" data-img="/website/static/src/img/snippets_options/content_width_full.svg" title="Full"/>\n        </we-button-group>\n    </div>\n\n    <!-- Scroll to next section button (only for full height) -->\n    <div data-js="ScrollButton" data-selector="section" data-exclude="[data-snippet] :not(.oe_structure) &gt; [data-snippet]">\n        <!-- Min height of section -->\n        <!-- TODO adapt in master, this is patched in JS -->\n        <we-button-group string="Height" data-show-scroll-button="">\n            <we-button data-name="minheight_auto_opt" data-select-class="" title="Fit content">Auto</we-button>\n            <we-button data-select-class="o_half_screen_height" title="Half screen">50%</we-button>\n            <we-button data-select-class="o_full_screen_height" title="Full screen" data-name="full_height_opt" data-show-scroll-button="true">100%</we-button>\n        </we-button-group>\n\n        <we-checkbox string="Scroll down button" data-toggle-button="true" data-no-preview="true" data-dependencies="full_height_opt" data-name="scroll_button_opt"/>\n        <we-row string="Colors" class="o_we_sublevel_1">\n            <we-colorpicker data-select-style="true" data-css-property="background-color" data-color-prefix="bg-" data-apply-to=".o_scroll_button" data-dependencies="scroll_button_opt"/>\n            <we-colorpicker data-select-style="true" data-css-property="color" data-color-prefix="text-" data-apply-to=".o_scroll_button" data-dependencies="scroll_button_opt"/>\n        </we-row>\n        <we-select string="Spacing" class="o_we_sublevel_1" data-apply-to=".o_scroll_button" data-dependencies="scroll_button_opt">\n            <we-button data-select-class="">None</we-button>\n            <we-button data-select-class="mb-1">Extra-Small</we-button>\n            <we-button data-select-class="mb-2">Small</we-button>\n            <we-button data-select-class="mb-3">Medium</we-button>\n            <we-button data-select-class="mb-4">Large</we-button>\n            <we-button data-select-class="mb-5">Extra-Large</we-button>\n        </we-select>\n    </div>\n\n    <t t-set="_device_visibility_widgets">\n        <we-button class="o_we_device" data-toggle-device-visibility="no_desktop" title="Show/Hide on Desktop" data-no-preview="true" data-img="/website/static/src/img/snippets_options/desktop_invisible.svg"/>\n        <we-button class="o_we_device" data-toggle-device-visibility="no_mobile" title="Show/Hide on Mobile" data-no-preview="true" data-img="/website/static/src/img/snippets_options/mobile_invisible.svg"/>\n    </t>\n    <div data-js="ConditionalVisibility" data-selector="section">\n        <t t-set="current_website" t-value="request.env['website'].get_current_website()"/>\n        <we-collapse>\n            <we-row string="Visibility">\n                <t t-out="_device_visibility_widgets"/>\n                <we-select data-attribute-name="visibility" data-no-preview="true">\n                    <we-button data-select-data-attribute="">No condition</we-button>\n                    <we-button data-select-data-attribute="conditional" data-select-class="o_snippet_invisible" data-name="visibility_conditional">Conditionally</we-button>\n                </we-select>\n            </we-row>\n\n            <t t-if="request.geoip.get('country_code')">\n                <t t-call="website.snippet_options_conditional_visibility">\n                    <t t-set="option_name">Country</t>\n                    <t t-set="attribute_rule" t-valuef="visibilityValueCountryRule"/>\n                    <t t-set="save_attribute" t-valuef="visibilityValueCountry"/>\n                    <t t-set="attribute_name" t-valuef="data-country"/>\n                    <t t-set="model" t-valuef="res.country"/>\n                    <t t-set="call_with" t-valuef="code"/>\n                    <t t-set="data_fields" t-valuef="[&quot;code&quot;]"/>\n                </t>\n            </t>\n            <t t-if="len(current_website.language_ids) &gt; 1">\n                <t t-call="website.snippet_options_conditional_visibility">\n                    <t t-set="option_name">Languages</t>\n                    <t t-set="attribute_rule" t-valuef="visibilityValueLangRule"/>\n                    <t t-set="save_attribute" t-valuef="visibilityValueLang"/>\n                    <t t-set="attribute_name" t-valuef="lang"/>\n                    <t t-set="model" t-valuef="res.lang"/>\n                    <t t-set="call_with" t-valuef="code"/>\n                    <t t-set="domain" t-translation="off">[["id", "in", <t t-out="current_website.language_ids.ids"/>]]</t>\n                    <t t-set="data_fields" t-valuef="[&quot;code&quot;]"/>\n                </t>\n            </t>\n            <t t-call="website.snippet_options_conditional_visibility">\n                <t t-set="option_name">UTM Campaign</t>\n                <t t-set="attribute_rule" t-valuef="visibilityValueUtmCampaignRule"/>\n                <t t-set="save_attribute" t-valuef="visibilityValueUtmCampaign"/>\n                <t t-set="attribute_name" t-valuef="data-utm-campaign"/>\n                <t t-set="model" t-valuef="utm.campaign"/>\n                <t t-set="call_with" t-valuef="display_name"/>\n            </t>\n            <t t-call="website.snippet_options_conditional_visibility">\n                <t t-set="option_name">UTM Medium</t>\n                <t t-set="attribute_rule" t-valuef="visibilityValueUtmMediumRule"/>\n                <t t-set="save_attribute" t-valuef="visibilityValueUtmMedium"/>\n                <t t-set="attribute_name" t-valuef="data-utm-medium"/>\n                <t t-set="model" t-valuef="utm.medium"/>\n                <t t-set="call_with" t-valuef="display_name"/>\n            </t>\n            <t t-call="website.snippet_options_conditional_visibility">\n                <t t-set="option_name">UTM Source</t>\n                <t t-set="attribute_rule" t-valuef="visibilityValueUtmSourceRule"/>\n                <t t-set="save_attribute" t-valuef="visibilityValueUtmSource"/>\n                <t t-set="attribute_name" t-valuef="data-utm-source"/>\n                <t t-set="model" t-valuef="utm.source"/>\n                <t t-set="call_with" t-valuef="display_name"/>\n            </t>\n            <we-select string="Users" class="o_we_sublevel_1" data-dependencies="visibility_conditional" data-attribute-name="data-logged" data-save-attribute="visibilityValueLogged" data-no-preview="true" data-attribute-default-value="">\n                <we-button data-select-value="true">Visible for Logged In</we-button>\n                <we-button data-select-value="false">Visible for Logged Out</we-button>\n                <we-button data-select-value="">Visible for Everyone</we-button>\n            </we-select>\n        </we-collapse>\n    </div>\n\n    <!-- Mobile/Desktop display options -->\n    <div data-js="DeviceVisibility" data-selector="section .row &gt; div" data-exclude=".s_col_no_resize.row &gt; div, .s_masonry_block .s_col_no_resize">\n        <we-row string="Visibility">\n            <t t-out="_device_visibility_widgets"/>\n        </we-row>\n    </div>\n\n    <!-- Cookies Bar -->\n    <div data-selector="#website_cookies_bar" data-js="CookiesBar" data-target=".modal">\n        <we-select string="Layout" class="o_we_inline">\n            <we-button data-select-class="o_cookies_discrete" data-select-layout="discrete" data-trigger="position_bottom,s_popup_size_full">Discrete</we-button>\n            <we-button data-select-class="o_cookies_classic" data-select-layout="classic" data-trigger="position_bottom,s_popup_size_full">Classic</we-button>\n            <we-button data-name="layout_popup_opt" data-select-class="o_cookies_popup" data-select-layout="popup" data-trigger="position_middle,s_popup_size_md">Popup</we-button>\n        </we-select>\n    </div>\n\n    <!-- Image position in grid -->\n    <!-- TODO something is added here in JS to handle grid image position mode -->\n\n    <!-- Website Animate -->\n    <div data-js="WebsiteAnimate" data-selector=".o_animable, section .row &gt; div, img, .fa, .btn, .o_animated_text" data-exclude="[data-oe-xpath], .o_not-animable, .s_col_no_resize.row &gt; div, .s_col_no_resize">\n        <!-- Animation mode -->\n        <we-row string="Animation">\n            <we-select data-dependencies="!image_transform_opt" data-is-animation-type-selection="true" data-no-preview="true">\n                <we-button data-animation-mode="" data-select-class="" data-name="no_animation_opt">None</we-button>\n                <we-button data-animation-mode="onAppearance" data-force-animation="true" data-select-class="o_animate" data-name="animation_on_appearance_opt">On Appearance</we-button>\n                <we-button data-animation-mode="onScroll" data-select-class="o_animate o_animate_on_scroll" data-force-animation="true" data-name="animation_on_scroll_opt">On Scroll</we-button>\n            </we-select>\n            <we-button-group data-dependencies="animation_on_scroll_opt" data-no-preview="true" data-force-animation="true">\n                <we-button data-select-class="">In</we-button>\n                <we-button data-select-class="o_animate_out">Out</we-button>\n            </we-button-group>\n        </we-row>\n        <!-- Effect -->\n        <we-select string="Effect" class="o_we_sublevel_1" data-dependencies="!no_animation_opt" data-name="animation_effect_opt">\n            <we-button data-select-class="" data-name="o_anim_no_effect_opt" data-dependencies="no_animation_opt">None</we-button>\n            <we-button data-select-class="o_anim_fade_in" data-trigger="animation_direction_in_place_opt">Fade</we-button>\n            <we-button